    ];

    $recipient = docs_find_assignment_author_entry($record, $folder, $subordinate);
    if ($recipient === null) {
        $recipient = docs_find_fallback_response_notification_author($record, $subordinate);
    }
    if ($recipient === null) {
        docs_write_response_log('Не найден ответственный для уведомления об отправке на проверку', $logContext);
        return;
    }

    $recipientName = docs_extract_assignee_display_name($recipient);
    if ($recipientName === '') {
        $recipientName = sanitize_text_field((string) ($recipient['name'] ?? ($recipient['responsible'] ?? '')), 200);
    }

    $chatId = docs_resolve_telegram_chat_id_from_assignee($recipient);
    if ($chatId === null) {
        docs_write_response_log('У ответственного отсутствует Telegram ID для уведомления об отправке на проверку', $logContext + [
            'recipient' => [
                'name' => $recipientName,
                'id' => $recipient['id'] ?? null,
                'telegram' => $recipient['telegram'] ?? ($recipient['chatId'] ?? null),
                'source' => $recipient['source'] ?? 'record_or_settings',
            ],
        ]);
        return;
    }

    $botToken = docs_resolve_telegram_bot_token();
    if ($botToken === null || $botToken === '') {
        docs_write_response_log('Не найден токен Telegram-бота для уведомления ответственного об отправке на проверку', $logContext + [
            'chatId' => (string) $chatId,
        ]);
        return;
    }

    $baseUrl = docs_resolve_application_base_url();
    $appPath = '/js/documents/app/telegram-appdosc.html';
    $startParam = docs_build_task_start_param($record);
    $link = docs_build_mini_app_link($baseUrl, $appPath, (string) $chatId, $startParam);
    $message = docs_build_subordinate_submission_notification_message($record, $organization, $subordinate, $link);
    if ($message === '') {
        return;
    }

    $replyMarkup = null;
    if ($link !== '') {
        $replyMarkup = [
            'inline_keyboard' => [
                [[
                    'text' => 'Открыть задачу',
                    'web_app' => ['url' => $link],
                ]],
            ],
        ];
    }

    docs_write_response_log('Подготовка уведомления ответственному об отправке на проверку', $logContext + [
        'chatId' => (string) $chatId,
        'recipient' => [
            'name' => $recipientName,
            'id' => $recipient['id'] ?? null,
            'source' => $recipient['source'] ?? 'record_or_settings',
        ],
    ]);

    $result = docs_send_telegram_message((string) $chatId, $message, $botToken, $replyMarkup, 'HTML');
    docs_write_response_log(
        !empty($result['success'])
            ? 'Уведомление ответственному об отправке на проверку отправлено'
            : 'Ошибка отправки уведомления ответственному об отправке на проверку',
        $logContext + [
            'chatId' => (string) $chatId,
            'result' => $result,
        ]
    );
}

function docs_normalize_assignment_role(?string $role): string
{
    if ($role === null) {
        return '';
    }

    $normalized = mb_strtolower(trim($role), 'UTF-8');
    if ($normalized === '') {
        return '';
    }

    $map = [
        'director' => 'director',
        'директор' => 'director',
        'руководитель' => 'director',
        'admin' => 'admin',
        'administrator' => 'admin',
        'администратор' => 'admin',
        'админ' => 'admin',
        'responsible' => 'responsible',
        'ответственный' => 'responsible',
        'subordinate' => 'subordinate',
        'подчиненный' => 'subordinate',
        'подчинённый' => 'subordinate',
    ];

    return $map[$normalized] ?? '';
}

function docs_resolve_assignment_author_role_from_session(?array $sessionAuth): string
{
    if (!is_array($sessionAuth)) {
        return '';
    }

    $sessionRole = docs_normalize_assignment_role((string) ($sessionAuth['role'] ?? ''));
    if ($sessionRole === 'admin') {
        return 'admin';
    }

    if (($sessionAuth['role'] ?? '') === 'user') {
        $responsibleRole = docs_normalize_assignment_role((string) ($sessionAuth['responsibleRole'] ?? ''));
        if ($responsibleRole !== '') {
            return $responsibleRole;
        }
    }

    return $sessionRole;
}

function docs_resolve_assignment_author_role_from_context(bool $isDirector, bool $isTaskResponsible, bool $isTaskSubordinate): string
{
    if ($isDirector) {
        return 'director';
    }

    if ($isTaskResponsible) {
        return 'responsible';
    }

    if ($isTaskSubordinate) {
        return 'subordinate';
    }

    return '';
}

function docs_build_director_responsible_chain_label(array $record): string
{
    $directorNames = docs_collect_director_names_from_record($record);
    $responsibleNames = docs_collect_responsible_names_from_record($record);

    if (empty($directorNames) && empty($responsibleNames)) {
        return '';
    }

    $parts = [];

    if (!empty($directorNames)) {
        $parts[] = 'Директор: ' . implode(', ', $directorNames);
    }

    if (!empty($responsibleNames)) {
        $parts[] = 'Ответственный: ' . implode(', ', $responsibleNames);
    }

    return implode(' → ', $parts);
}

function docs_build_assignment_notification_message(array $record, array $assignee, string $organization, string $appUrl): string
{
    $lines = [];

    $assignmentComment = sanitize_assignment_comment($assignee['assignmentComment'] ?? '');
    $assignmentDueRaw = sanitize_date_field($assignee['assignmentDueDate'] ?? '');
    $assignmentDueFormatted = docs_format_human_date($assignmentDueRaw);
    $assignmentInstruction = sanitize_text_field($assignee['assignmentInstruction'] ?? '', 800);
    if ($assignmentInstruction === '') {
        $assignmentInstruction = $assignmentComment;
    }
    if ($assignmentInstruction === '') {
        $assignmentInstruction = sanitize_text_field($record['instruction'] ?? '', 800);
    }

    $assigneeName = sanitize_text_field($assignee['name'] ?? '', 200);
    if ($assigneeName !== '') {
        $lines[] = $assigneeName . ', вам задача! 📌';
    } else {
        $lines[] = 'Вам задача! 📌';
    }

    $assignedByName = sanitize_text_field($assignee['assignedBy'] ?? '', 200);
    $assignedByLabel = $assignedByName;
    if ($assignedByLabel === '') {
        $directorNames = docs_collect_director_names_from_record($record);
        $assignedByLabel = !empty($directorNames) ? implode(', ', $directorNames) : '';
    }
    if ($assignedByLabel === '') {
        $assignedByLabel = 'не указан';
    }

    $lines[] = '';
    $lines[] = 'от: ' . $assignedByLabel;

    $registryNumber = sanitize_text_field($record['registryNumber'] ?? '', 120);
    $documentDate = docs_format_human_date($record['documentDate'] ?? '');
    if ($registryNumber !== '' || $documentDate !== '') {
        $incomingParts = [];
        if ($registryNumber !== '') {
            $incomingParts[] = $registryNumber;
        }
        if ($documentDate !== '') {
            $incomingParts[] = 'от ' . $documentDate;
        }
        $lines[] = 'Вх. №: ' . implode(' ', $incomingParts);
    } else {
        $lines[] = 'Вх. №: не указан';
    }

    $theme = sanitize_text_field($record['summary'] ?? '', 350);
    if ($theme === '') {
        $theme = sanitize_text_field($record['content'] ?? '', 350);
    }
    if ($theme === '') {
        $theme = sanitize_text_field($record['description'] ?? '', 350);
    }
    $lines[] = 'Тема: ' . ($theme !== '' ? $theme : 'не указана');

    $content = sanitize_text_field($record['correspondent'] ?? '', 350);
    if ($content === '') {
        $content = sanitize_text_field($record['summary'] ?? '', 350);
    }
    $lines[] = 'Содержание: ' . ($content !== '' ? $content : 'не указано');

    $instruction = $assignmentInstruction !== '' ? docs_truncate_notification_text($assignmentInstruction, 350) : 'не указано';
    $lines[] = 'Поручение: ' . $instruction;

    $recordDueDate = docs_format_human_date($record['dueDate'] ?? '');
    $dueDisplay = $assignmentDueFormatted !== '' ? $assignmentDueFormatted : $recordDueDate;
    $lines[] = 'Срок: ' . ($dueDisplay !== '' ? $dueDisplay : 'не указан');

    $responsibleNames = docs_collect_responsible_names_from_record($record);
    $responsibleLabel = !empty($responsibleNames) ? implode(', ', array_map(static function ($name): string {
        return sanitize_text_field((string) $name, 200);
    }, $responsibleNames)) : 'не указаны';

    $subordinateNames = docs_collect_subordinate_names_from_record($record);
    $subordinateLabel = !empty($subordinateNames) ? implode(', ', array_map(static function ($name): string {
        return sanitize_text_field((string) $name, 200);
    }, $subordinateNames)) : 'не указаны';

    $lines[] = '';
    $lines[] = 'Ответственные: ' . $responsibleLabel;
    $lines[] = 'Подчинённые: ' . $subordinateLabel;

    $lines[] = '';
    $lines[] = 'Файлы:';
    $fileNames = docs_collect_file_names_from_record($record);
    if (!empty($fileNames)) {
        foreach ($fileNames as $fileName) {
            $normalizedFileName = sanitize_text_field((string) $fileName, 255);
            if ($normalizedFileName === '') {
                continue;
            }

            if (mb_strlen($normalizedFileName, 'UTF-8') > 40) {
                $normalizedFileName = rtrim(mb_substr($normalizedFileName, 0, 40, 'UTF-8')) . '...';
            }

            $lines[] = $normalizedFileName;
        }
    } else {
        $lines[] = 'не указаны';
    }

    if ($appUrl !== '') {
        $lines[] = '';
        $lines[] = 'Открыть задачу: кнопка ниже.';
    }

    $message = trim(implode("\n", array_filter($lines, static function ($line) {
        return $line !== null;
    })));

    if ($message === '') {
        return '';
    }

    if (mb_strlen($message, 'UTF-8') > 3800) {
        $message = mb_substr($message, 0, 3799, 'UTF-8');
    }

    return $message;
}

function docs_build_director_reminder_message(array $record, array $director, string $organization, string $appUrl): string
{
    $lines = [];

    $directorName = sanitize_text_field($director['name'] ?? '', 200);
    if ($directorName === '') {
        $directorName = sanitize_text_field($director['responsible'] ?? '', 200);
    }

    if ($directorName !== '') {
        $lines[] = '🔔 ' . $directorName . ', напоминание по задаче';
    } else {
        $lines[] = '🔔 Напоминание по задаче';
    }

    $lines[] = 'Пожалуйста, распределите задачу на ответственных и подчинённых.';

    $organizationName = sanitize_text_field($organization, 160);
    if ($organizationName !== '') {
        $lines[] = 'Организация: ' . $organizationName;
    }

    $documentParts = [];
    $documentNumber = sanitize_text_field($record['documentNumber'] ?? '', 120);
    if ($documentNumber !== '') {
        $documentParts[] = '№ ' . $documentNumber;
    }
    $documentDate = docs_format_human_date($record['documentDate'] ?? '');
    if ($documentDate !== '') {
        $documentParts[] = 'от ' . $documentDate;
    }
    $documentTitle = sanitize_text_field($record['document'] ?? '', 200);
    if ($documentTitle !== '') {
        $documentParts[] = $documentTitle;
    }

    if (!empty($documentParts)) {
        $lines[] = 'Документ: ' . implode(' ', $documentParts);
    }

    $registryNumber = sanitize_text_field($record['registryNumber'] ?? '', 120);
    if ($registryNumber !== '') {
        $lines[] = 'Рег. №: ' . $registryNumber;
    }

    $correspondent = sanitize_text_field($record['correspondent'] ?? '', 200);
    if ($correspondent !== '') {
        $lines[] = 'Корреспондент: ' . $correspondent;
    }

    $recordDueDate = docs_format_human_date($record['dueDate'] ?? '');
    $lines[] = 'Срок: ' . ($recordDueDate !== '' ? $recordDueDate : 'не указан');

    $summary = sanitize_text_field($record['summary'] ?? '', 800);
    if ($summary !== '') {
        $lines[] = '';
        $lines[] = 'Кратко: ' . docs_truncate_notification_text($summary, 350);
    }

    $resolution = sanitize_text_field($record['resolution'] ?? '', 800);
    if ($resolution !== '') {
        $lines[] = '';
        $lines[] = 'Резолюция: ' . docs_truncate_notification_text($resolution, 350);
    }

    if ($appUrl !== '') {
        $lines[] = '';
        $lines[] = 'Открыть задачу: кнопка ниже.';
    }

    $message = trim(implode("\n", array_filter($lines, static function ($line) {
        return $line !== null;
    })));

    if ($message === '') {
        return '';
    }

    if (mb_strlen($message, 'UTF-8') > 3800) {
        $message = mb_substr($message, 0, 3799, 'UTF-8');
    }

    return $message;
}

function docs_build_subordinate_instruction_summary(array $entries): string
{
    $lines = [];

    foreach ($entries as $entry) {
        if (!is_array($entry)) {
            continue;
        }

        $comment = sanitize_assignment_comment($entry['assignmentComment'] ?? '');
        $dueRaw = sanitize_date_field($entry['assignmentDueDate'] ?? '');
        $hasComment = $comment !== '';
        $hasDue = $dueRaw !== '';

        if (!$hasComment && !$hasDue) {
            continue;
        }

        $name = sanitize_text_field($entry['name'] ?? '', 200);
        if ($name === '') {
            $name = sanitize_text_field($entry['responsible'] ?? '', 200);
        }
        if ($name === '') {
            $name = sanitize_text_field($entry['login'] ?? '', 120);
        }
        if ($name === '') {
            $name = sanitize_text_field($entry['id'] ?? '', 120);
        }

        $parts = [];
        if ($hasComment) {
            $parts[] = $comment;
        }
        if ($hasDue) {
            $parts[] = 'Срок: ' . docs_format_human_date($dueRaw);
        }

        $lineBody = trim(implode(' • ', array_filter($parts)));
        if ($name !== '') {
            $lines[] = trim($name . ($lineBody !== '' ? ' — ' . $lineBody : ''));
        } elseif ($lineBody !== '') {
            $lines[] = $lineBody;
        }
    }

    return trim(implode("\n", array_filter($lines)));
}

function docs_update_instruction_from_subordinates(array &$record): void
{
    $entries = [];

    if (isset($record['subordinates']) && is_array($record['subordinates'])) {
        $entries = $record['subordinates'];
    } elseif (isset($record['subordinate']) && is_array($record['subordinate'])) {
        $entries = [$record['subordinate']];
    }

    $summary = docs_build_subordinate_instruction_summary($entries);
    $record['instruction'] = sanitize_instruction($summary);
}

function docs_send_task_assignment_notifications(array $assignees, array $record, string $organization): void
{
    if (empty($assignees)) {
        return;
    }

    $botToken = docs_resolve_telegram_bot_token();
    if ($botToken === null || $botToken === '') {
        log_docs_event('Assignment notification skipped: bot token missing', [
            'organization' => $organization,
            'documentId' => $record['id'] ?? null,
        ]);

        return;
    }

    $baseUrl = docs_resolve_application_base_url();
    $appPath = '/js/documents/app/telegram-appdosc.html';

    $sentChatIds = [];

    foreach ($assignees as $assignee) {
        if (!is_array($assignee)) {
            continue;
        }

        $chatId = docs_resolve_telegram_chat_id_from_assignee($assignee);
        if ($chatId === null) {
            log_docs_event('Assignment notification skipped: chat id unavailable', [
                'organization' => $organization,
                'documentId' => $record['id'] ?? null,
                'assignee' => $assignee,
            ]);
            continue;
        }

        if (isset($sentChatIds[$chatId])) {
            continue;
        }

        $startParam = docs_build_task_start_param($record);
        $link = docs_build_mini_app_link($baseUrl, $appPath, $chatId, $startParam);

        $message = docs_build_assignment_notification_message($record, $assignee, $organization, $link);
        if ($message === '') {
            continue;
        }

        $replyMarkup = null;
        if ($link !== '') {
            $replyMarkup = [
                'inline_keyboard' => [
                    [
                        [
                            'text' => 'Открыть задачу',
                            'web_app' => [
                                'url' => $link,
                            ],
                        ],
                    ],
                ],
            ];
        }

        if ($startParam !== '') {
            docs_write_entry_task_log('Мини-приложение: сформирована ссылка на задачу', [
                'scope' => 'assignment_notification',
                'organization' => $organization,
                'documentId' => $record['id'] ?? null,
                'startParam' => $startParam,
                'chatId' => $chatId,
                'assigneeRole' => $assignee['role'] ?? null,
            ]);
        }

        $result = docs_send_telegram_message($chatId, $message, $botToken, $replyMarkup);

        $logContext = [
            'organization' => $organization,
            'documentId' => $record['id'] ?? null,
            'chatId' => $chatId,
            'assignee' => [
                'id' => $assignee['id'] ?? null,
                'name' => $assignee['name'] ?? null,
                'telegram' => $assignee['telegram'] ?? null,
                'chatId' => $assignee['chatId'] ?? null,
                'role' => $assignee['role'] ?? null,
            ],
        ];

        if (!empty($result['success'])) {
            $logContext['response'] = $result['response'] ?? null;
            log_docs_event('Assignment notification sent', $logContext);
        } else {
            $logContext['error'] = $result['error'] ?? null;
            if (isset($result['response'])) {
                $logContext['response'] = $result['response'];
            }
            log_docs_event('Assignment notification failed', $logContext);
        }

        $sentChatIds[$chatId] = true;
    }
}

function docs_truthy_value($value): bool
{
    if (is_bool($value)) {
        return $value;
    }

    if (is_int($value) || is_float($value)) {
        return (int) $value === 1;
    }

    if (!is_string($value)) {
        return false;
    }

    $normalized = mb_strtolower(trim($value), 'UTF-8');

    return in_array($normalized, ['1', 'true', 'yes', 'y', 'on', 'да'], true);
}

function docs_ru_plural(int $count, string $one, string $few, string $many): string
{
    $count = abs($count);
    $lastTwo = $count % 100;
    $last = $count % 10;

    if ($lastTwo >= 11 && $lastTwo <= 14) {
        return $many;
    }

    if ($last === 1) {
        return $one;
    }

    if ($last >= 2 && $last <= 4) {
        return $few;
    }

    return $many;
}

function docs_get_overdue_digest_state_path(string $folder): string
{
    return DOCUMENTS_ROOT . '/' . $folder . '/' . OVERDUE_DIGEST_STATE_FILENAME;
}

function docs_load_overdue_digest_state(string $folder): array
{
    $path = docs_get_overdue_digest_state_path($folder);
    if (!is_file($path)) {
        return ['sent' => []];
    }

    $raw = @file_get_contents($path);
    if (!is_string($raw) || trim($raw) === '') {
        return ['sent' => []];
    }

    $decoded = json_decode($raw, true);
    if (!is_array($decoded)) {
        return ['sent' => []];
    }

    if (!isset($decoded['sent']) || !is_array($decoded['sent'])) {
        $decoded['sent'] = [];
    }

    return $decoded;
}

function docs_cleanup_overdue_digest_state(array &$state): void
{
    if (!isset($state['sent']) || !is_array($state['sent'])) {
        $state['sent'] = [];
        return;
    }

    $dates = array_values(array_filter(array_keys($state['sent']), static function ($value): bool {
        return is_string($value) && preg_match('/^\d{4}-\d{2}-\d{2}$/', $value) === 1;
    }));
    sort($dates, SORT_STRING);

    $keepLimit = 45;
    while (count($dates) > $keepLimit) {
        $date = array_shift($dates);
        if (is_string($date)) {
            unset($state['sent'][$date]);
        }
    }
}

function docs_save_overdue_digest_state(string $folder, array $state): void
{
    docs_cleanup_overdue_digest_state($state);
    $directory = ensure_organization_directory($folder);
    $path = rtrim($directory, '/\\') . '/' . OVERDUE_DIGEST_STATE_FILENAME;
    $state['updatedAt'] = date('c');

    $encoded = json_encode($state, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    if ($encoded === false) {
        return;
    }

    @file_put_contents($path, $encoded . PHP_EOL, LOCK_EX);
    @chmod($path, 0644);
}

function docs_overdue_digest_was_sent(array $state, string $date, string $chatId): bool
{
    return isset($state['sent'][$date])
        && is_array($state['sent'][$date])
        && isset($state['sent'][$date][$chatId]);
}

function docs_mark_overdue_digest_sent(array &$state, string $date, string $chatId, int $tasksCount): void
{
    if (!isset($state['sent']) || !is_array($state['sent'])) {
        $state['sent'] = [];
    }
    if (!isset($state['sent'][$date]) || !is_array($state['sent'][$date])) {
        $state['sent'][$date] = [];
    }

    $state['sent'][$date][$chatId] = [
        'sentAt' => date('c'),
        'tasksCount' => max(0, $tasksCount),
    ];
}

function docs_collect_overdue_digest_assignees(array $record): array
{
    $entries = [];

    $push = static function ($value, string $fallbackRole) use (&$entries): void {
        if (!is_array($value) || empty($value)) {
            return;
        }

        $entry = $value;
        $role = docs_normalize_assignment_role((string) ($entry['role'] ?? ''));
        if ($role === '') {
            $role = $fallbackRole;
            $entry['role'] = $role;
        }

        if ($role === 'director' || $role === 'admin') {
            return;
        }

        if ($role !== 'responsible' && $role !== 'subordinate') {
            $role = 'responsible';
        }

        $entry['role'] = $role;

        $entries[] = $entry;
    };

    foreach (docs_extract_assignees($record) as $entry) {
        $push($entry, 'responsible');
    }

    if (isset($record['responsibles']) && is_array($record['responsibles'])) {
        foreach ($record['responsibles'] as $entry) {
            $push($entry, 'responsible');
        }
    }

    if (isset($record['responsible']) && is_array($record['responsible'])) {
        $push($record['responsible'], 'responsible');
    }

    if (isset($record['subordinates']) && is_array($record['subordinates'])) {
        foreach ($record['subordinates'] as $entry) {
            $push($entry, 'subordinate');
        }
    }

    if (isset($record['subordinate']) && is_array($record['subordinate'])) {
        $push($record['subordinate'], 'subordinate');
    }

    $unique = [];
    $seen = [];

    foreach ($entries as $entry) {
        $keys = docs_collect_assignee_index_keys($entry);
        if (empty($keys)) {
            $encodedEntry = json_encode($entry, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
            $keys = ['hash::' . md5(is_string($encodedEntry) ? $encodedEntry : '')];
        }

        $duplicate = false;
        foreach ($keys as $key) {
            $normalizedKey = mb_strtolower(trim((string) $key), 'UTF-8');
            if ($normalizedKey !== '' && isset($seen[$normalizedKey])) {
                $duplicate = true;
                break;
            }
        }

        if ($duplicate) {
            continue;
        }

        foreach ($keys as $key) {
            $normalizedKey = mb_strtolower(trim((string) $key), 'UTF-8');
            if ($normalizedKey !== '') {
                $seen[$normalizedKey] = true;
            }
        }

        $unique[] = $entry;
    }

    return $unique;
}

function docs_collect_overdue_assignee_lookup_candidates(array $assignee): array
{
    $candidates = [];

    foreach (['id', 'telegram', 'chatId', 'number', 'email', 'login'] as $field) {
        if (!empty($assignee[$field])) {
            $candidates[] = (string) $assignee[$field];
        }
    }

    foreach (['name', 'responsible', 'fio', 'fullName'] as $field) {
        if (!empty($assignee[$field])) {
            $candidates[] = (string) $assignee[$field];
        }
    }

    if (!empty($assignee['number'])) {
        $name = $assignee['responsible'] ?? ($assignee['name'] ?? '');
        if ($name !== '') {
            $candidates[] = trim((string) $assignee['number'] . ' ' . (string) $name);
        }
    }

    return array_values(array_unique(array_filter(array_map(static function ($value) {
        $trimmed = trim((string) $value);

        return $trimmed !== '' ? $trimmed : null;
    }, $candidates))));
}

function docs_enrich_overdue_digest_assignee(array $assignee, array $settings): array
{
    if (docs_resolve_telegram_chat_id_from_assignee($assignee) !== null) {
        return $assignee;
    }

    $candidates = docs_collect_overdue_assignee_lookup_candidates($assignee);
    if (empty($candidates)) {
        return $assignee;
    }

    $pools = [];
    foreach (['responsibles', 'block3'] as $groupKey) {
        if (isset($settings[$groupKey]) && is_array($settings[$groupKey])) {
            $pools[] = $settings[$groupKey];
        }
    }

    foreach ($pools as $pool) {
        foreach ($pool as $entry) {
            if (!is_array($entry) || empty($entry)) {
                continue;
            }

            $matched = false;
            foreach ($candidates as $candidate) {
                if (docs_entry_matches_candidate($entry, $candidate)) {
                    $matched = true;
                    break;
                }
            }
            if (!$matched) {
                continue;
            }

            foreach (['id', 'telegram', 'chatId', 'email', 'login', 'number', 'position', 'department'] as $field) {
                if ((empty($assignee[$field]) || !isset($assignee[$field])) && !empty($entry[$field])) {
                    $assignee[$field] = $entry[$field];
                }
            }

            if (empty($assignee['name']) && !empty($entry['responsible'])) {
                $assignee['name'] = $entry['responsible'];
            }
            if (empty($assignee['responsible']) && !empty($entry['responsible'])) {
                $assignee['responsible'] = $entry['responsible'];
            }

            return $assignee;
        }
    }

    return $assignee;
}

function docs_overdue_digest_assignee_is_active(array $assignee): bool
{
    $statusKey = docs_status_key_from_status($assignee['status'] ?? null);
    if ($statusKey === 'done' || $statusKey === 'cancelled') {
        return false;
    }

    $reviewStatus = docs_normalize_subordinate_review_status($assignee['reviewStatus'] ?? '');

    return $reviewStatus !== 'accepted';
}

function docs_resolve_overdue_digest_due_date(array $record, array $assignee): string
{
    $personalDue = sanitize_date_field($assignee['assignmentDueDate'] ?? '');
    if ($personalDue !== '') {
        return $personalDue;
    }

    return sanitize_date_field($record['dueDate'] ?? '');
}

function docs_build_overdue_digest_task_key(array $record, string $organization, string $dueDate): string
{
    $parts = [$organization];
    foreach (['id', 'entryNumber', 'registryNumber', 'documentNumber'] as $field) {
        if (!empty($record[$field])) {
            $parts[] = $field . ':' . (string) $record[$field];
            break;
        }
    }

    if (count($parts) === 1) {
        $encodedRecord = json_encode($record, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
        $parts[] = 'hash:' . md5(is_string($encodedRecord) ? $encodedRecord : '');
    }

    $parts[] = 'due:' . $dueDate;

    return implode('|', $parts);
}

function docs_build_overdue_digest_item(
    array $record,
    array $assignee,
    string $organization,
    string $folder,
    DateTimeImmutable $today,
    DateTimeZone $timezone
): ?array {
    if (!docs_record_is_active($record) || !docs_overdue_digest_assignee_is_active($assignee)) {
        return null;
    }

    $dueDateRaw = docs_resolve_overdue_digest_due_date($record, $assignee);
    if ($dueDateRaw === '') {
        return null;
    }

    $dueDate = DateTimeImmutable::createFromFormat('!Y-m-d', $dueDateRaw, $timezone);
    if (!$dueDate instanceof DateTimeImmutable || $dueDate->getTimestamp() >= $today->getTimestamp()) {
        return null;
    }

    $content = sanitize_text_field((string) ($record['correspondent'] ?? ''), 250);
    if ($content === '') {
        $content = sanitize_text_field((string) ($record['summary'] ?? ''), 250);
    }
    if ($content === '') {
        $content = sanitize_text_field((string) ($record['document'] ?? ''), 250);
    }

    $daysOverdue = (int) $dueDate->diff($today)->days;

    return [
        'organization' => $organization,
        'folder' => $folder,
        'taskKey' => docs_build_overdue_digest_task_key($record, $organization, $dueDateRaw),
        'documentId' => sanitize_text_field((string) ($record['id'] ?? ''), 200),
        'entryNumber' => sanitize_text_field((string) ($record['entryNumber'] ?? ''), 80),
        'registryNumber' => sanitize_text_field((string) ($record['registryNumber'] ?? ''), 120),
        'documentNumber' => sanitize_text_field((string) ($record['documentNumber'] ?? ''), 120),
        'content' => $content,
        'dueDate' => $dueDateRaw,
        'dueDateLabel' => docs_format_human_date($dueDateRaw),
        'daysOverdue' => max(1, $daysOverdue),
        'assigneeName' => docs_extract_assignee_display_name($assignee),
    ];
}

function docs_format_overdue_digest_task_line(array $task, int $index): string
{
    $identifier = '';
    if (!empty($task['registryNumber'])) {
        $identifier = 'рег. № ' . $task['registryNumber'];
    } elseif (!empty($task['entryNumber'])) {
        $identifier = 'запись № ' . $task['entryNumber'];
    } elseif (!empty($task['documentNumber'])) {
        $identifier = 'док. № ' . $task['documentNumber'];
    }

    $parts = [];
    if (!empty($task['organization'])) {
        $parts[] = (string) $task['organization'];
    }
    if ($identifier !== '') {
        $parts[] = $identifier;
    }

    $dueLabel = !empty($task['dueDateLabel']) ? (string) $task['dueDateLabel'] : (string) ($task['dueDate'] ?? '');
    if ($dueLabel !== '') {
        $parts[] = 'срок ' . $dueLabel;
    }

    $days = isset($task['daysOverdue']) ? (int) $task['daysOverdue'] : 0;
    if ($days > 0) {
        $parts[] = 'просрочено ' . $days . ' ' . docs_ru_plural($days, 'день', 'дня', 'дней');
    }

    $line = ((int) $index + 1) . '. ' . implode(' — ', $parts);
    $content = sanitize_text_field((string) ($task['content'] ?? ''), 180);
    if ($content !== '') {
        $line .= "\n" . docs_truncate_notification_text($content, 180);
    }

    return $line;
}

function docs_build_overdue_digest_message(array $recipient, string $appUrl): string
{
    $tasks = isset($recipient['tasks']) && is_array($recipient['tasks']) ? array_values($recipient['tasks']) : [];
    $total = count($tasks);
    if ($total < 1) {
        return '';
    }

    $name = sanitize_text_field((string) ($recipient['name'] ?? ''), 200);
    $taskLabel = docs_ru_plural($total, 'просроченная задача', 'просроченные задачи', 'просроченных задач');
    $lines = [];
    $lines[] = $name !== ''
        ? $name . ', у вас ' . $total . ' ' . $taskLabel . '.'
        : 'У вас ' . $total . ' ' . $taskLabel . '.';
    $lines[] = 'Пожалуйста, проверьте сроки выполнения.';
    $lines[] = '';

    $visibleTasks = array_slice($tasks, 0, DOCS_OVERDUE_DIGEST_MAX_ITEMS);
    foreach ($visibleTasks as $index => $task) {
        if (!is_array($task)) {
            continue;
        }
        $lines[] = docs_format_overdue_digest_task_line($task, $index);
    }

    $hiddenCount = $total - count($visibleTasks);
    if ($hiddenCount > 0) {
        $lines[] = '';
        $lines[] = 'Ещё ' . $hiddenCount . ' ' . docs_ru_plural($hiddenCount, 'задача', 'задачи', 'задач') . ' в мини-приложении.';
    }

    if ($appUrl !== '') {
        $lines[] = '';
        $lines[] = 'Открыть задачи: кнопка ниже.';
    }

    $message = trim(implode("\n", $lines));
    if ($message !== '' && mb_strlen($message, 'UTF-8') > 3800) {
        $message = mb_substr($message, 0, 3799, 'UTF-8');
    }

    return $message;
}

function docs_send_overdue_digest(bool $dryRun = false): array
{
    $timezone = new DateTimeZone(DOCS_OVERDUE_DIGEST_TIMEZONE);
    $today = new DateTimeImmutable('today', $timezone);
    $digestDate = $today->format('Y-m-d');
    $organizations = load_organizations();
    $states = [];
    $dirtyFolders = [];
    $recipients = [];
    $stats = [
        'date' => $digestDate,
        'timezone' => DOCS_OVERDUE_DIGEST_TIMEZONE,
        'dryRun' => $dryRun,
        'organizationsChecked' => 0,
        'recordsChecked' => 0,
        'overdueTasksQueued' => 0,
        'recipientsQueued' => 0,
        'sent' => 0,
        'failed' => 0,
        'skippedAlreadySent' => 0,
        'skippedMissingChatId' => 0,
        'skippedInactive' => 0,
    ];

    foreach ($organizations as $organization) {
        if (!is_string($organization) || trim($organization) === '') {
            continue;
        }

        $organization = docs_normalize_organization_candidate($organization);
        if ($organization === '') {
            continue;
        }

        $stats['organizationsChecked']++;
        $folder = sanitize_folder_name($organization);
        $records = load_registry($folder);
        $settings = load_admin_settings($folder);
        if (!isset($states[$folder])) {
            $states[$folder] = docs_load_overdue_digest_state($folder);
        }

        foreach ($records as $record) {
            if (!is_array($record)) {
                continue;
            }

            $stats['recordsChecked']++;
            if (!docs_record_is_active($record)) {
                $stats['skippedInactive']++;
                continue;
            }

            $assignees = docs_collect_overdue_digest_assignees($record);
            foreach ($assignees as $assignee) {
                if (!is_array($assignee)) {
                    continue;
                }

                $assignee = docs_enrich_overdue_digest_assignee($assignee, $settings);
                $item = docs_build_overdue_digest_item($record, $assignee, $organization, $folder, $today, $timezone);
                if ($item === null) {
                    continue;
                }

                $chatId = docs_resolve_telegram_chat_id_from_assignee($assignee);
                if ($chatId === null) {
                    $stats['skippedMissingChatId']++;
                    docs_write_response_log('Пропущено уведомление о просрочке: у исполнителя нет Telegram ID', [
                        'organization' => $organization,
                        'folder' => $folder,
                        'documentId' => $record['id'] ?? null,
                        'assignee' => [
                            'name' => docs_extract_assignee_display_name($assignee),
                            'role' => $assignee['role'] ?? null,
                        ],
                    ]);
                    continue;
                }

                if (docs_overdue_digest_was_sent($states[$folder], $digestDate, (string) $chatId)) {
                    $stats['skippedAlreadySent']++;
                    continue;
                }

                if (!isset($recipients[$chatId])) {
                    $recipients[$chatId] = [
                        'chatId' => (string) $chatId,
                        'name' => docs_extract_assignee_display_name($assignee),
                        'tasks' => [],
                        'taskKeys' => [],
                        'folders' => [],
                    ];
                }

                if (empty($recipients[$chatId]['name'])) {
                    $recipients[$chatId]['name'] = docs_extract_assignee_display_name($assignee);
                }

                $taskKey = (string) ($item['taskKey'] ?? '');
                if ($taskKey !== '' && isset($recipients[$chatId]['taskKeys'][$taskKey])) {
                    continue;
                }

                if ($taskKey !== '') {
                    $recipients[$chatId]['taskKeys'][$taskKey] = true;
                }
                $recipients[$chatId]['tasks'][] = $item;
                $recipients[$chatId]['folders'][$folder] = true;
                $stats['overdueTasksQueued']++;
            }
        }
    }

    $stats['recipientsQueued'] = count($recipients);

    $baseUrl = docs_resolve_application_base_url();
    $appPath = '/js/documents/app/telegram-appdosc.html';
    $botToken = $dryRun ? null : docs_resolve_telegram_bot_token();
    if (!$dryRun && ($botToken === null || $botToken === '')) {
        $stats['error'] = 'bot_token_missing';
        docs_write_response_log('Не найден токен Telegram-бота для дайджеста просроченных задач', $stats);

        return $stats;
    }

    foreach ($recipients as $chatId => $recipient) {
        $tasks = isset($recipient['tasks']) && is_array($recipient['tasks']) ? $recipient['tasks'] : [];
        if (empty($tasks)) {
            continue;
        }

        usort($tasks, static function (array $a, array $b): int {
            $dueCompare = strcmp((string) ($a['dueDate'] ?? ''), (string) ($b['dueDate'] ?? ''));
            if ($dueCompare !== 0) {
                return $dueCompare;
            }

            return strcmp((string) ($a['organization'] ?? ''), (string) ($b['organization'] ?? ''));
        });
        $recipient['tasks'] = $tasks;

        $link = docs_build_mini_app_link($baseUrl, $appPath, (string) $chatId, '');
        $message = docs_build_overdue_digest_message($recipient, $link);
        if ($message === '') {
            continue;
        }

        if ($dryRun) {
            continue;
        }

        $replyMarkup = [
            'inline_keyboard' => [
                [[
                    'text' => 'Открыть задачи',
                    'web_app' => ['url' => $link],
                ]],
            ],
        ];

        $result = docs_send_telegram_message((string) $chatId, $message, $botToken, $replyMarkup);
        if (!empty($result['success'])) {
            $stats['sent']++;
            foreach (array_keys($recipient['folders']) as $folder) {
                if (!isset($states[$folder])) {
                    $states[$folder] = docs_load_overdue_digest_state($folder);
                }
                docs_mark_overdue_digest_sent($states[$folder], $digestDate, (string) $chatId, count($tasks));
                $dirtyFolders[$folder] = true;
            }
        } else {
            $stats['failed']++;
        }

        docs_write_response_log(
            !empty($result['success'])
                ? 'Дайджест просроченных задач отправлен'
                : 'Ошибка отправки дайджеста просроченных задач',
            [
                'chatId' => (string) $chatId,
                'tasksCount' => count($tasks),
                'folders' => array_keys($recipient['folders']),
                'result' => $result,
            ]
        );
    }

    if (!$dryRun) {
        foreach (array_keys($dirtyFolders) as $folder) {
            docs_save_overdue_digest_state($folder, $states[$folder] ?? ['sent' => []]);
        }
    }

    $stats['recipientsSample'] = array_slice(array_map(static function (array $recipient): array {
        return [
            'chatId' => $recipient['chatId'] ?? '',
            'name' => $recipient['name'] ?? '',
            'tasksCount' => isset($recipient['tasks']) && is_array($recipient['tasks']) ? count($recipient['tasks']) : 0,
            'folders' => isset($recipient['folders']) && is_array($recipient['folders']) ? array_keys($recipient['folders']) : [],
        ];
    }, array_values($recipients)), 0, 10);

    return $stats;
}

function docs_build_subordinate_review_notification_message(
    array $record,
    string $organization,
    array $subordinate,
    string $appUrl
): string {
    $status = docs_normalize_subordinate_review_status($subordinate['reviewStatus'] ?? '');
    if ($status === '') {
        return '';
    }

    $lines = [];
    $name = docs_extract_assignee_display_name($subordinate);
    $decisionLabel = docs_subordinate_review_status_label($status);

    if ($status === 'revision') {
        $lines[] = '⛔️ НА ДОРАБОТКУ ⛔️';
        $lines[] = '';
    }

    $lines[] = $name !== ''
        ? $name . ', по вашей задаче принято решение.'
        : 'По вашей задаче принято решение.';

    $organizationName = sanitize_text_field($organization, 160);
    if ($organizationName !== '') {
        $lines[] = 'Организация: ' . $organizationName;
    }

    $registryNumber = sanitize_text_field((string) ($record['registryNumber'] ?? ''), 120);
    if ($registryNumber !== '') {
        $lines[] = 'Рег. №: ' . $registryNumber;
    }

    $content = sanitize_text_field((string) ($record['correspondent'] ?? ''), 250);
    if ($content === '') {
        $content = sanitize_text_field((string) ($record['summary'] ?? ''), 250);
    }
    $lines[] = 'Содержание: ' . ($content !== '' ? $content : 'не указано');
    $lines[] = 'Решение: ' . $decisionLabel;
    $lines[] = 'Статус: ' . ($status === 'accepted' ? 'Выполнено' : 'В работе');

    $comment = sanitize_assignment_comment($subordinate['reviewComment'] ?? '');
    if ($comment !== '') {
        $lines[] = 'Комментарий: ' . docs_truncate_notification_text($comment, 700);
    }

    if ($appUrl !== '') {
        $lines[] = '';
        $lines[] = 'Открыть задачу: кнопка ниже.';
    }

    $message = trim(implode("\n", $lines));
    if ($message !== '' && mb_strlen($message, 'UTF-8') > 3800) {
        $message = mb_substr($message, 0, 3799, 'UTF-8');
    }

    return $message;
}

function docs_notify_subordinate_about_review(array $record, string $organization, array $subordinate): void
{
    $chatId = docs_resolve_telegram_chat_id_from_assignee($subordinate);
    $logContext = [
        'organization' => $organization,
        'documentId' => $record['id'] ?? null,
        'registryNumber' => $record['registryNumber'] ?? null,
        'subordinate' => [
            'name' => docs_extract_assignee_display_name($subordinate),
            'id' => $subordinate['id'] ?? null,
            'telegram' => $subordinate['telegram'] ?? null,
            'chatId' => $subordinate['chatId'] ?? null,
        ],
        'reviewStatus' => $subordinate['reviewStatus'] ?? null,
    ];

    if ($chatId === null) {
        docs_write_response_log('У подчинённого отсутствует Telegram ID для уведомления о приемке', $logContext);
        return;
    }

    $botToken = docs_resolve_telegram_bot_token();
    if ($botToken === null || $botToken === '') {
        docs_write_response_log('Не найден токен Telegram-бота для уведомления подчинённого о приемке', $logContext + [
            'chatId' => (string) $chatId,
        ]);
        return;
    }

    $baseUrl = docs_resolve_application_base_url();
    $appPath = '/js/documents/app/telegram-appdosc.html';
    $startParam = docs_build_task_start_param($record);
    $link = docs_build_mini_app_link($baseUrl, $appPath, (string) $chatId, $startParam);
    $message = docs_build_subordinate_review_notification_message($record, $organization, $subordinate, $link);
    if ($message === '') {
        return;
    }

    $replyMarkup = null;
    if ($link !== '') {
        $replyMarkup = [
            'inline_keyboard' => [
                [[
                    'text' => 'Открыть задачу',
                    'web_app' => ['url' => $link],
                ]],
            ],
        ];
    }

    docs_write_response_log('Подготовка уведомления подчинённому о приемке', $logContext + [
        'chatId' => (string) $chatId,
    ]);

    $result = docs_send_telegram_message((string) $chatId, $message, $botToken, $replyMarkup);
    docs_write_response_log(
        !empty($result['success'])
            ? 'Уведомление подчинённому о приемке отправлено'
            : 'Ошибка отправки уведомления подчинённому о приемке',
        $logContext + [
            'chatId' => (string) $chatId,
            'result' => $result,
        ]
    );
}

function docs_parse_telegram_init_data_string(string $initData): ?array
{
    $initData = trim($initData);
    if ($initData === '') {
        return null;
    }

    $pairs = preg_split('/&/', $initData, -1, PREG_SPLIT_NO_EMPTY);
    if (empty($pairs)) {
        return null;
    }

    $fields = [];

    foreach ($pairs as $pair) {
        if (!is_string($pair) || $pair === '') {
            continue;
        }

        $parts = explode('=', $pair, 2);
        $key = rawurldecode($parts[0] ?? '');
        $value = rawurldecode($parts[1] ?? '');

        if ($key === '') {
            continue;
        }

        $fields[$key] = $value;
    }

    if (empty($fields)) {
        return null;
    }

    $hash = $fields['hash'] ?? '';
    if (!is_string($hash) || trim($hash) === '') {
        return null;
    }

    unset($fields['hash']);

    return [
        'fields' => $fields,
        'hash' => trim($hash),
    ];
}

function docs_verify_telegram_init_data(array $parsed, string $botToken): ?array
{
    if (empty($parsed['fields']) || !is_array($parsed['fields'])) {
        return null;
    }

    $fields = [];
    foreach ($parsed['fields'] as $key => $value) {
        if (!is_string($key)) {
            continue;
        }

        if (is_array($value)) {
            $encoded = json_encode($value, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_PARTIAL_OUTPUT_ON_ERROR);
            $fields[$key] = $encoded !== false ? $encoded : '';
            continue;
        }

        if (is_bool($value)) {
            $fields[$key] = $value ? '1' : '0';
            continue;
        }

        if ($value === null) {
            $fields[$key] = '';
            continue;
        }

        $fields[$key] = (string) $value;
    }

    if (empty($fields)) {
        return null;
    }

    ksort($fields, SORT_STRING);

    $pieces = [];
    foreach ($fields as $key => $value) {
        $pieces[] = $key . '=' . $value;
    }

    $dataCheckString = implode("\n", $pieces);

    $secretKey = hash_hmac('sha256', $botToken, 'WebAppData', true);
    $calculatedHash = hash_hmac('sha256', $dataCheckString, $secretKey);

    if (!hash_equals($parsed['hash'], $calculatedHash)) {
        return null;
    }

    $user = null;
    if (isset($parsed['fields']['user']) && is_string($parsed['fields']['user'])) {
        $decoded = json_decode($parsed['fields']['user'], true);
        if (is_array($decoded)) {
            $user = $decoded;
        }
    }

    return [
        'fields' => $parsed['fields'],
        'hash' => $parsed['hash'],
        'dataCheckString' => $dataCheckString,
        'user' => $user,
    ];
}

function docs_resolve_telegram_init_data_context(): array
{
    static $cached = null;

    if ($cached !== null) {
        return $cached;
    }

    $cached = [
        'present' => false,
        'valid' => false,
        'hashValid' => false,
        'error' => null,
        'source' => [],
        'user' => null,
        'authDate' => null,
        'sourceType' => 'none',
    ];

    $initData = '';
    $sourceType = 'none';

    $headerValue = $_SERVER['HTTP_X_TELEGRAM_INIT_DATA'] ?? null;
    if (is_string($headerValue) && trim($headerValue) !== '') {
        $initData = trim($headerValue);
        $sourceType = 'header';
    } else {
        $candidates = [];

        if (!empty($_POST) && is_array($_POST)) {
            $candidates[] = $_POST;
        }

        if (!empty($_GET) && is_array($_GET)) {
            $candidates[] = $_GET;
        }

        if (($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'POST') {
            $jsonPayload = load_json_payload();
            if (!empty($jsonPayload) && is_array($jsonPayload)) {
                $candidates[] = $jsonPayload;
            }
        }

        foreach ($candidates as $candidate) {
            foreach (['telegram_init_data', 'init_data', 'initData', 'telegramInitData'] as $key) {
                if (!isset($candidate[$key])) {
                    continue;
                }

                $value = $candidate[$key];
                if (!is_string($value) && !is_numeric($value)) {
                    continue;
                }

                $stringValue = trim((string) $value);
                if ($stringValue === '') {
                    continue;
                }

                $initData = $stringValue;
                $sourceType = 'payload';
                break 2;
            }
        }
    }

    if ($initData === '') {
        return $cached;
    }

    $cached['present'] = true;
    $cached['sourceType'] = $sourceType;
    $cached['initDataLength'] = strlen($initData);

    $botToken = docs_resolve_telegram_bot_token();
    if ($botToken === null || $botToken === '') {
        $cached['error'] = 'missing_token';
        log_docs_event('Telegram init data received but bot token missing', [
            'source' => $sourceType,
            'initDataLength' => strlen($initData),
        ]);

        return $cached;
    }

    $parsed = docs_parse_telegram_init_data_string($initData);
    if ($parsed === null) {
        $cached['error'] = 'invalid_payload';
        log_docs_event('Telegram init data parsing failed', [
            'source' => $sourceType,
            'initDataLength' => strlen($initData),
        ]);

        return $cached;
    }

    $verification = docs_verify_telegram_init_data($parsed, $botToken);
    if ($verification === null) {
        $cached['error'] = 'hash_mismatch';
        log_docs_event('Telegram init data hash mismatch', [
            'source' => $sourceType,
            'initDataLength' => strlen($initData),
            'hasHash' => true,
        ]);

        return $cached;
    }

    $cached['hashValid'] = true;

    $fields = $verification['fields'];
    $authDate = null;
    if (isset($fields['auth_date']) && $fields['auth_date'] !== '') {
        $authDate = (int) $fields['auth_date'];
        if ($authDate <= 0) {
            $authDate = null;
        }
    }

    $cached['authDate'] = $authDate;

    $now = time();
    if ($authDate !== null) {
        if ($authDate > $now + 300) {
            $cached['error'] = 'invalid_auth_date';
            log_docs_event('Telegram init data auth_date is in the future', [
                'source' => $sourceType,
                'authDate' => $authDate,
                'now' => $now,
            ]);

            return $cached;
        }

        if ($authDate < $now - TELEGRAM_INIT_DATA_MAX_AGE) {
            $cached['error'] = 'expired';
            log_docs_event('Telegram init data auth_date expired', [
                'source' => $sourceType,
                'authDate' => $authDate,
                'now' => $now,
            ]);

            return $cached;
        }
    }

    $user = $verification['user'];
    $source = [];

    if (is_array($user)) {
        if (isset($user['id'])) {
            $source['telegram_user_id'] = (string) $user['id'];
        }
        if (!empty($user['username'])) {
            $source['telegram_username'] = (string) $user['username'];
        }

        $nameParts = [];
        if (!empty($user['first_name'])) {
            $nameParts[] = (string) $user['first_name'];
        }
        if (!empty($user['last_name'])) {
            $nameParts[] = (string) $user['last_name'];
        }

        if (!empty($nameParts)) {
            $source['telegram_full_name'] = trim(implode(' ', $nameParts));
        }
    }

    if (!isset($source['telegram_user_id']) || $source['telegram_user_id'] === '') {
        $cached['error'] = 'user_missing';
        log_docs_event('Telegram init data user information missing', [
            'source' => $sourceType,
            'initDataLength' => strlen($initData),
        ]);

        return $cached;
    }

    $cached['source'] = $source;
    $cached['user'] = is_array($user) ? array_filter([
        'id' => isset($user['id']) ? (string) $user['id'] : null,
        'username' => $user['username'] ?? null,
        'firstName' => $user['first_name'] ?? null,
        'lastName' => $user['last_name'] ?? null,
        'languageCode' => $user['language_code'] ?? null,
        'isBot' => isset($user['is_bot']) ? (bool) $user['is_bot'] : null,
    ], static function ($value) {
        return $value !== null && $value !== '';
    }) : null;

    $cached['valid'] = true;

    $logContext = [
        'source' => $sourceType,
        'initDataLength' => strlen($initData),
        'authDate' => $authDate,
        'userId' => $source['telegram_user_id'],
        'usernameProvided' => isset($source['telegram_username']) && $source['telegram_username'] !== '',
        'fullNameProvided' => isset($source['telegram_full_name']) && $source['telegram_full_name'] !== '',
    ];

    if (isset($fields['query_id']) && $fields['query_id'] !== '') {
        $logContext['queryIdPresent'] = true;
    }

    log_docs_event('Telegram init data verified successfully', $logContext);

    return $cached;
}

function docs_current_action(): string
{
    global $docsCurrentAction;

    return isset($docsCurrentAction) && is_string($docsCurrentAction) ? $docsCurrentAction : '';
}

function summarize_response_payload(array $payload): array
{
    $summary = [];

    foreach ($payload as $key => $value) {
        if ($key === 'documents' && is_array($value)) {
            $ids = [];
            foreach (array_slice($value, 0, 5) as $item) {
                if (is_array($item) && isset($item['id'])) {
                    $ids[] = (string) $item['id'];
                }
            }

            $summary[$key] = [
                'count' => count($value),
                'ids' => $ids,
            ];
            continue;
        }

        $summary[$key] = normalize_log_value($value);
    }

    return $summary;
}

function summarize_document_record_for_log(array $record): array
{
    $summary = [];

    if (isset($record['id']) && $record['id'] !== '') {
        $summary['id'] = (string) $record['id'];
    }

    if (isset($record['entryNumber']) && $record['entryNumber'] !== '') {
        $summary['entryNumber'] = (string) $record['entryNumber'];
    }

    if (isset($record['status']) && $record['status'] !== '') {
        $summary['status'] = (string) $record['status'];
    }

    if (isset($record['dueDate']) && $record['dueDate'] !== '') {
        $summary['dueDate'] = (string) $record['dueDate'];
    }

    if (isset($record['organization']) && $record['organization'] !== '') {
        $summary['organization'] = (string) $record['organization'];
    }

    $assignees = docs_extract_assignees($record);
    $primaryAssignee = $assignees[0] ?? [];

    $assigneeName = $primaryAssignee['name'] ?? $primaryAssignee['responsible'] ?? ($record['responsible'] ?? null);
    if (!empty($assigneeName)) {
        $summary['assigneeName'] = (string) $assigneeName;
    }

    if (!empty($assignees)) {
        $summary['assigneesCount'] = count($assignees);
    }

    $assigneeId = null;
    foreach (['id', 'telegram', 'chatId'] as $field) {
        if (!empty($primaryAssignee[$field])) {
            $assigneeId = (string) $primaryAssignee[$field];
            break;
        }
    }

    if ($assigneeId === null && !empty($record['assigneeId'])) {
        $assigneeId = (string) $record['assigneeId'];
    }

    if ($assigneeId !== null) {
        $summary['assigneeId'] = $assigneeId;
    }

    if (isset($record['updatedAt']) && $record['updatedAt'] !== '') {
        $summary['updatedAt'] = (string) $record['updatedAt'];
    }

    if (isset($record['files']) && is_array($record['files'])) {
        $summary['filesCount'] = count($record['files']);
    }

    return $summary;
}

function summarize_documents_collection_for_log(array $records, int $limit = 10): array
{
    $samples = [];
    $total = 0;

    foreach ($records as $record) {
        if (!is_array($record)) {
            continue;
        }

        $total++;
        if (count($samples) < $limit) {
            $samples[] = summarize_document_record_for_log($record);
        }
    }

    return [
        'count' => $total,
        'samples' => $samples,
    ];
}

function build_document_record_key(array $record): string
{
    if (isset($record['id']) && $record['id'] !== '') {
        return 'id:' . (string) $record['id'];
    }

    if (isset($record['entryNumber']) && $record['entryNumber'] !== '') {
        return 'entry:' . (string) $record['entryNumber'];
    }

    return 'hash:' . md5(json_encode($record, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES));
}

function get_raw_input(): string
{
    static $cached = null;

    if ($cached !== null) {
        return $cached;
    }

    $raw = file_get_contents('php://input');
    if ($raw === false) {
        $raw = '';
    }

    $cached = $raw;

    return $cached;
}

require_once __DIR__ . '/sanitize.php';

if (session_status() === PHP_SESSION_NONE) {
    session_start();
}

$sessionActionForLock = $preloadedAction;
if ($sessionActionForLock === '' && ($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'POST') {
    $sessionActionPayload = load_json_payload();
    if (isset($sessionActionPayload['action']) && is_string($sessionActionPayload['action'])) {
        $sessionActionForLock = trim($sessionActionPayload['action']);
    }
}

$GLOBALS['DOCS_SESSION_AUTH_SNAPSHOT_SET'] = true;
$GLOBALS['DOCS_SESSION_AUTH_SNAPSHOT'] = isset($_SESSION[DOCS_SESSION_KEY]) && is_array($_SESSION[DOCS_SESSION_KEY])
    ? $_SESSION[DOCS_SESSION_KEY]
    : null;

$sessionWriteActions = [
    'login' => true,
    'logout' => true,
];
if (!isset($sessionWriteActions[$sessionActionForLock]) && session_status() === PHP_SESSION_ACTIVE) {
    session_write_close();
}

register_shutdown_function(static function () use ($preloadedAction): void {
    $error = error_get_last();
    if (!is_array($error)) {
        return;
    }

    $getAction = $_GET['action'] ?? '';
    if (!is_string($getAction)) {
        $getAction = '';
    }

    $resolvedAction = $preloadedAction;
    if ($resolvedAction === '') {
        $resolvedAction = $getAction;
    }

    if ($resolvedAction === '' && isset($_POST['action']) && is_string($_POST['action'])) {
        $resolvedAction = trim($_POST['action']);
    }

    $jsonPayload = [];
    if (($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'POST') {
        $jsonPayload = load_json_payload();
    }

    if ($resolvedAction === '' && isset($jsonPayload['action']) && is_string($jsonPayload['action'])) {
        $resolvedAction = trim($jsonPayload['action']);
    }

    $sessionAuth = docs_get_session_auth();
    $login = is_array($sessionAuth) ? ($sessionAuth['login'] ?? null) : null;
    $organization = is_array($sessionAuth) ? ($sessionAuth['organization'] ?? null) : null;

    $stage = null;
    if (isset($jsonPayload['stage']) && is_string($jsonPayload['stage'])) {
        $stage = $jsonPayload['stage'];
    } elseif (isset($_POST['stage']) && is_string($_POST['stage'])) {
        $stage = $_POST['stage'];
    } elseif (isset($_GET['stage']) && is_string($_GET['stage'])) {
        $stage = $_GET['stage'];
    }

    $context = [
        'message' => $error['message'] ?? 'unknown_error',
        'type' => $error['type'] ?? null,
        'file' => $error['file'] ?? null,
        'line' => $error['line'] ?? null,
        'action' => $resolvedAction,
        'login' => $login,
        'organization' => $organization,
        'getAction' => $getAction,
        'session' => $_SESSION ?? [],
        'post' => is_array($_POST) ? $_POST : [],
        'json' => $jsonPayload,
    ];

    if ($stage !== null && $stage !== '') {
        $context['stage'] = $stage;
    }

    docs_log_auth_attempt('shutdown_error', $context);
});

header('Content-Type: application/json; charset=utf-8');
header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');
header('Pragma: no-cache');
header('Expires: 0');

if (!is_dir(DOCUMENTS_ROOT)) {
    mkdir(DOCUMENTS_ROOT, 0775, true);
}

$action = $preloadedAction;
$method = $_SERVER['REQUEST_METHOD'] ?? 'GET';

$contentType = (string) ($_SERVER['CONTENT_TYPE'] ?? $_SERVER['HTTP_CONTENT_TYPE'] ?? '');
$rawBodyForLog = '';
if ($action === '' && stripos($contentType, 'application/json') !== false) {
    $rawBodyForLog = get_raw_input();
    if ((!is_string($action) || $action === '') && $rawBodyForLog !== '') {
        $decodedForAction = json_decode($rawBodyForLog, true);
        if (is_array($decodedForAction) && isset($decodedForAction['action'])) {
            $action = (string) $decodedForAction['action'];
        }
    }
}

if (!is_string($action)) {
    $action = '';
} else {
    $action = trim($action);
}

$docsCurrentAction = $action;

$filesSummary = [];
if (!empty($_FILES) && is_array($_FILES)) {
    foreach ($_FILES as $key => $fileInfo) {
        if (!is_array($fileInfo)) {
            continue;
        }

        $filesSummary[$key] = [
            'name' => $fileInfo['name'] ?? null,
            'type' => $fileInfo['type'] ?? null,
            'error' => $fileInfo['error'] ?? null,
            'size' => $fileInfo['size'] ?? null,
        ];
    }
}

$requestOverview = function_exists('bot_auth_get_request_overview')
    ? bot_auth_get_request_overview()
    : null;

$logContext = [
    'action' => $action,
    'method' => $method,
    'ip' => $_SERVER['REMOTE_ADDR'] ?? null,
    'user' => $_SERVER['PHP_AUTH_USER'] ?? null,
    'query' => $_GET,
    'post' => $_POST,
    'rawBody' => $rawBodyForLog,
    'files' => $filesSummary,
    'contentType' => $contentType,
];

if (is_array($requestOverview)) {
    $logContext['requestOverview'] = $requestOverview;
}

log_docs_event('Request received', $logContext);

function respond(array $payload, int $status = 200): void
{
    http_response_code($status);
    docs_send_json_payload($payload);
    exit;
}

function docs_client_accepts_gzip(): bool
{
    $encoding = $_SERVER['HTTP_ACCEPT_ENCODING'] ?? '';
    if (!is_string($encoding) || stripos($encoding, 'gzip') === false) {
        return false;
    }

    if (ini_get('zlib.output_compression')) {
        return false;
    }

    return !headers_sent();
}

function docs_send_json_payload(array $payload): void
{
    $json = json_encode($payload, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    if ($json === false) {
        http_response_code(500);
        $json = '{"success":false,"error":"json_encode_failed"}';
    }

    header('Content-Type: application/json; charset=UTF-8');
    header('Vary: Accept-Encoding', false);

    if (strlen($json) >= 1024 && docs_client_accepts_gzip() && function_exists('gzencode')) {
        $compressed = gzencode($json, 5);
        if (is_string($compressed) && $compressed !== '') {
            header('Content-Encoding: gzip');
            header('Content-Length: ' . strlen($compressed));
            echo $compressed;
            return;
        }
    }

    header('Content-Length: ' . strlen($json));
    echo $json;
}

function respond_error(string $message, int $status = 400, array $extra = []): void
{
    log_docs_event('Error response', [
        'status' => $status,
        'message' => $message,
        'extra' => $extra,
        'action' => docs_current_action(),
    ]);
    $action = docs_current_action();
    if ($action === 'mini_app_update_task' || $action === 'mini_app_log') {
        docs_log_file_debug('Mini app error response', [
            'status' => $status,
            'message' => $message,
            'extra' => $extra,
            'action' => $action,
        ]);
    }

    respond(array_merge(['success' => false, 'error' => $message], $extra), $status);
}

function respond_success(array $payload = []): void
{
    log_docs_event('Success response', [
        'status' => 200,
        'action' => docs_current_action(),
        'payload' => summarize_response_payload($payload),
    ]);

    respond(array_merge(['success' => true], $payload));
}

function respond_success_with_background_task(array $payload, callable $backgroundTask): void
{
    log_docs_event('Success response', [
        'status' => 200,
        'action' => docs_current_action(),
        'payload' => summarize_response_payload($payload),
    ]);

    if (!function_exists('fastcgi_finish_request')) {
        log_docs_event('Background task skipped: fastcgi_finish_request unavailable', [
            'action' => docs_current_action(),
        ]);
        respond(array_merge(['success' => true], $payload));
    }

    http_response_code(200);
    docs_send_json_payload(array_merge(['success' => true], $payload));

    fastcgi_finish_request();
    $backgroundTask();
    exit;
}

function docs_collect_login_response_diagnostics(array $sessionSummary, string $stage): array
{
    $setCookieHeader = null;
    if (function_exists('headers_list')) {
        foreach (headers_list() as $header) {
            if (stripos($header, 'Set-Cookie:') === 0) {
                $setCookieHeader = $header;
                break;
            }
        }
    }

    return [
        'stage' => $stage,
        'sessionId' => session_id(),
        'sessionStatus' => session_status(),
        'sessionAuthenticated' => $sessionSummary['authenticated'] ?? null,
        'sessionAccessGranted' => $sessionSummary['accessGranted'] ?? null,
        'sessionRole' => $sessionSummary['role'] ?? null,
        'sessionOrganization' => $sessionSummary['organization'] ?? null,
        'setCookiePresent' => $setCookieHeader !== null,
        'setCookieHeader' => $setCookieHeader,
    ];
}

function load_json_payload(): array
{
    $raw = get_raw_input();
    if (trim($raw) === '') {
        return [];
    }

    $data = json_decode($raw, true);
    if (!is_array($data)) {
        return [];
    }

    return $data;
}

function sanitize_text_field(?string $value, int $maxLength = 500): string
{
    if ($value === null) {
        return '';
    }

    $value = trim($value);
    if ($value === '') {
        return '';
    }

    $value = preg_replace('/[\x00-\x1F\x7F]+/u', ' ', $value);
    $value = preg_replace('/\s+/u', ' ', $value);

    if ($maxLength > 0 && mb_strlen($value) > $maxLength) {
        $value = mb_substr($value, 0, $maxLength);
    }

    return $value;
}

function sanitize_date_field(?string $value): string
{
    if ($value === null) {
        return '';
    }

    $value = trim($value);
    if ($value === '') {
        return '';
    }

    $date = DateTime::createFromFormat('Y-m-d', $value);
    if ($date === false) {
        return '';
    }

    return $date->format('Y-m-d');
}

function docs_normalize_uploaded_filename(?string $name): string
{
    if ($name === null) {
        return 'attachment';
    }

    $normalized = trim((string) $name);
    if ($normalized === '') {
        return 'attachment';
    }

    $converted = @iconv('UTF-8', 'UTF-8//IGNORE', $normalized);
    if (is_string($converted)) {
        $normalized = $converted;
    }

    $normalized = preg_replace('/[\x00-\x1F\x7F]+/u', ' ', $normalized) ?? '';
    $normalized = preg_replace('/\s+/u', ' ', $normalized) ?? '';
    $normalized = trim($normalized);

    return $normalized !== '' ? $normalized : 'attachment';
}

function docs_format_file_size(int $size): string
{
    if ($size >= 1024 * 1024) {
        $value = $size / (1024 * 1024);
        return rtrim(rtrim(number_format($value, $value >= 10 ? 0 : 1, '.', ''), '0'), '.') . ' МБ';
    }

    if ($size >= 1024) {
        return (string) ceil($size / 1024) . ' КБ';
    }

    return $size . ' Б';
}

function docs_collect_directory_size_summary(string $directory): array
{
    $summary = [
        'bytes' => 0,
        'files' => 0,
        'directories' => 0,
        'extensions' => [],
        'topDirectories' => [],
        'largestFiles' => [],
        'archiveBytes' => 0,
        'testArchiveBytes' => 0,
        'registryBytes' => 0,
    ];

    if (!is_dir($directory)) {
        return $summary;
    }

    $root = rtrim(str_replace('\\', '/', $directory), '/');
    $extensionBuckets = [];
    $directoryBuckets = [];
    $largestFiles = [];

    try {
        $iterator = new RecursiveIteratorIterator(
            new RecursiveDirectoryIterator($directory, FilesystemIterator::SKIP_DOTS),
            RecursiveIteratorIterator::SELF_FIRST
        );
    } catch (Throwable $exception) {
        return $summary;
    }

    foreach ($iterator as $entry) {
        if (!$entry instanceof SplFileInfo) {
            continue;
        }
        if ($entry->isDir()) {
            $summary['directories']++;
            continue;
        }
        if (!$entry->isFile()) {
            continue;
        }

        $path = str_replace('\\', '/', $entry->getPathname());
        $relativePath = strpos($path, $root . '/') === 0 ? substr($path, strlen($root) + 1) : $entry->getFilename();
        $relativePath = ltrim($relativePath, '/');
        $firstSegment = $relativePath !== '' && strpos($relativePath, '/') !== false
            ? substr($relativePath, 0, strpos($relativePath, '/'))
            : '(root)';
        $extension = strtolower((string) pathinfo($entry->getFilename(), PATHINFO_EXTENSION));
        if ($extension === '') {
            $extension = '[no_ext]';
        }
        $fileSize = max(0, (int) ($entry->getSize() ?: 0));

        $summary['files']++;
        $summary['bytes'] += $fileSize;

        if (!isset($extensionBuckets[$extension])) {
            $extensionBuckets[$extension] = ['extension' => $extension, 'files' => 0, 'bytes' => 0];
        }
        $extensionBuckets[$extension]['files']++;
        $extensionBuckets[$extension]['bytes'] += $fileSize;

        if (!isset($directoryBuckets[$firstSegment])) {
            $directoryBuckets[$firstSegment] = ['directory' => $firstSegment, 'files' => 0, 'bytes' => 0];
        }
        $directoryBuckets[$firstSegment]['files']++;
        $directoryBuckets[$firstSegment]['bytes'] += $fileSize;

        if ($firstSegment === DOCS_ATTACHMENT_ARCHIVE_DIRECTORY || $extension === 'zip') {
            $summary['archiveBytes'] += $fileSize;
        }
        if ($firstSegment === DOCS_ATTACHMENT_ARCHIVE_TEST_DIRECTORY) {
            $summary['testArchiveBytes'] += $fileSize;
        }
        if (in_array($entry->getFilename(), [REGISTRY_FILENAME, OUTGOING_REGISTRY_FILENAME, ORDERS_REGISTRY_FILENAME, SETTINGS_FILENAME], true)) {
            $summary['registryBytes'] += $fileSize;
        }

        $largestFiles[] = [
            'path' => $relativePath,
            'extension' => $extension,
            'bytes' => $fileSize,
        ];
    }

    usort($extensionBuckets, static function (array $left, array $right): int {
        return ($right['bytes'] <=> $left['bytes']) ?: strcmp($left['extension'], $right['extension']);
    });
    usort($directoryBuckets, static function (array $left, array $right): int {
        return ($right['bytes'] <=> $left['bytes']) ?: strcmp($left['directory'], $right['directory']);
    });
    usort($largestFiles, static function (array $left, array $right): int {
        return ($right['bytes'] <=> $left['bytes']) ?: strcmp($left['path'], $right['path']);
    });

    $summary['extensions'] = array_map(static function (array $bucket): array {
        $bucket['label'] = docs_format_file_size((int) $bucket['bytes']);
        return $bucket;
    }, array_slice($extensionBuckets, 0, 15));
    $summary['topDirectories'] = array_map(static function (array $bucket): array {
        $bucket['label'] = docs_format_file_size((int) $bucket['bytes']);
        return $bucket;
    }, array_slice($directoryBuckets, 0, 15));
    $summary['largestFiles'] = array_map(static function (array $file): array {
        $file['label'] = docs_format_file_size((int) $file['bytes']);
        return $file;
    }, array_slice($largestFiles, 0, 15));

    return $summary;
}

function docs_collect_storage_size_summary(?string $requestedOrganization = null): array
{
    $documentsRoot = realpath(DOCUMENTS_ROOT);
    $folder = '';
    $targetPath = $documentsRoot;
    if (is_string($requestedOrganization) && trim($requestedOrganization) !== '') {
        $folder = sanitize_folder_name($requestedOrganization);
        $targetPath = is_string($documentsRoot) && $documentsRoot !== ''
            ? $documentsRoot . '/' . $folder
            : DOCUMENTS_ROOT . '/' . $folder;
    }

    $targetPath = is_string($targetPath) ? $targetPath : '';
    $summary = docs_collect_directory_size_summary($targetPath);
    $summary['label'] = docs_format_file_size((int) $summary['bytes']);
    $summary['archiveLabel'] = docs_format_file_size((int) ($summary['archiveBytes'] ?? 0));
    $summary['testArchiveLabel'] = docs_format_file_size((int) ($summary['testArchiveBytes'] ?? 0));
    $summary['registryLabel'] = docs_format_file_size((int) ($summary['registryBytes'] ?? 0));
    $summary['path'] = $folder !== '' ? 'documents/' . $folder : 'documents';
    $summary['organization'] = $folder !== '' ? $requestedOrganization : null;
    $summary['checkedAt'] = date('c');

    return $summary;
}

function docs_validate_uploaded_attachment(string $originalName, int $size): ?string
{
    if ($size <= 0) {
        return 'Файл «' . $originalName . '» пустой или повреждён.';
    }

    if ($size > DOCS_ATTACHMENT_MAX_FILE_SIZE) {
        return 'Файл «' . $originalName . '» слишком большой: ' . docs_format_file_size($size)
            . '. Максимум для одного файла — ' . docs_format_file_size(DOCS_ATTACHMENT_MAX_FILE_SIZE) . '.';
    }

    $extension = strtolower((string) pathinfo($originalName, PATHINFO_EXTENSION));
    if ($extension !== '' && isset(DOCS_ATTACHMENT_BLOCKED_EXTENSIONS[$extension])) {
        return 'Файл «' . $originalName . '» не похож на документ. Загрузите PDF, изображение, DOCX/XLSX или архив.';
    }

    return null;
}

function docs_find_attachment_storage_root(string $path): ?string
{
    $documentsRoot = realpath(DOCUMENTS_ROOT);
    $filePath = realpath($path);
    if (!is_string($documentsRoot) || $documentsRoot === '' || !is_string($filePath) || $filePath === '') {
        return null;
    }

    $documentsRoot = rtrim(str_replace('\\', '/', $documentsRoot), '/');
    $filePath = str_replace('\\', '/', $filePath);
    if (strpos($filePath, $documentsRoot . '/') !== 0) {
        return null;
    }

    $relative = substr($filePath, strlen($documentsRoot) + 1);
    $segments = explode('/', $relative);
    if (empty($segments[0]) || $segments[0] === '.' || $segments[0] === '..') {
        return null;
    }

    $storageRoot = $documentsRoot . '/' . $segments[0];
    return is_dir($storageRoot) ? $storageRoot : null;
}

function docs_files_share_inode(string $firstPath, string $secondPath): bool
{
    $firstInode = @fileinode($firstPath);
    $secondInode = @fileinode($secondPath);

    return is_int($firstInode) && is_int($secondInode) && $firstInode === $secondInode;
}

function docs_attachment_file_can_deduplicate(string $path): bool
{
    $extension = strtolower((string) pathinfo($path, PATHINFO_EXTENSION));
    if ($extension === '') {
        return false;
    }

    static $allowedExtensions = [
        'pdf' => true,
        'jpg' => true,
        'jpeg' => true,
        'png' => true,
        'gif' => true,
        'webp' => true,
        'heic' => true,
        'doc' => true,
        'docx' => true,
        'xls' => true,
        'xlsx' => true,
        'txt' => true,
        'rtf' => true,
        'odt' => true,
        'ods' => true,
        'dwg' => true,
        'bin' => true,
        'rar' => true,
        '7z' => true,
    ];

    return isset($allowedExtensions[$extension]);
}

function docs_attachment_file_can_archive(string $path): bool
{
    if (!docs_attachment_file_can_deduplicate($path)) {
        return false;
    }

    $extension = strtolower((string) pathinfo($path, PATHINFO_EXTENSION));
    return $extension !== 'zip';
}

function docs_prepare_archived_attachment_meta($value): array
{
    if (!is_array($value)) {
        return [];
    }

    $zip = sanitize_text_field((string) ($value['zip'] ?? ''), 255);
    $entry = sanitize_text_field((string) ($value['entry'] ?? ''), 500);
    if ($zip === '' || $entry === '') {
        return [];
    }

    $zip = str_replace('\\', '/', $zip);
    $entry = str_replace('\\', '/', $entry);
    if (strpos($zip, '..') !== false || strpos($entry, '..') !== false || strpos($zip, '/') !== false) {
        return [];
    }

    return array_filter([
        'zip' => $zip,
        'entry' => ltrim($entry, '/'),
        'size' => isset($value['size']) ? max(0, (int) $value['size']) : 0,
        'archivedAt' => docs_normalize_datetime_iso(isset($value['archivedAt']) ? (string) $value['archivedAt'] : null) ?? '',
    ], static function ($item) {
        return $item !== '' && $item !== 0;
    });
}

function docs_build_archived_attachment_url(string $folder, array $archive, string $fileName = ''): string
{
    $params = [
        'action' => 'archived_attachment',
        'organization' => $folder,
        'archive' => (string) ($archive['zip'] ?? ''),
        'entry' => (string) ($archive['entry'] ?? ''),
    ];
    if (!empty($archive['test'])) {
        $params['test'] = '1';
    }
    if ($fileName !== '') {
        $params['name'] = $fileName;
    }

    return '/docs.php?' . http_build_query($params, '', '&', PHP_QUERY_RFC3986);
}

function docs_file_matches_uploaded_attachment(string $candidatePath, string $path, int $size, string $hash): bool
{
    if ($candidatePath === $path || !is_file($candidatePath)) {
        return false;
    }
    if (!docs_attachment_file_can_deduplicate($candidatePath)) {
        return false;
    }
    if (docs_files_share_inode($candidatePath, $path)) {
        return false;
    }
    if ((int) (@filesize($candidatePath) ?: 0) !== $size) {
        return false;
    }

    $candidateHash = @hash_file('sha256', $candidatePath);
    return is_string($candidateHash) && $candidateHash !== '' && hash_equals($hash, $candidateHash);
}

function docs_find_duplicate_attachment_file(string $path, int $size, string $hash): ?string
{
    $storageRoot = docs_find_attachment_storage_root($path);
    if ($storageRoot === null || !is_dir($storageRoot)) {
        return null;
    }

    try {
        $iterator = new RecursiveIteratorIterator(
            new RecursiveDirectoryIterator($storageRoot, FilesystemIterator::SKIP_DOTS),
            RecursiveIteratorIterator::LEAVES_ONLY
        );
    } catch (Throwable $exception) {
        return null;
    }

    foreach ($iterator as $entry) {
        if (!$entry instanceof SplFileInfo || !$entry->isFile()) {
            continue;
        }

        $candidatePath = $entry->getPathname();
        if (docs_file_matches_uploaded_attachment($candidatePath, $path, $size, $hash)) {
            return $candidatePath;
        }
    }

    return null;
}

function docs_replace_duplicate_attachment_with_hardlink(string $path, string $duplicatePath): bool
{
    if (!function_exists('link') || !is_file($path) || !is_file($duplicatePath)) {
        return false;
    }

    $temporaryPath = $path . '.dedup-' . str_replace('.', '', uniqid('', true));
    if (!@rename($path, $temporaryPath)) {
        return false;
    }

    if (@link($duplicatePath, $path)) {
        @unlink($temporaryPath);
        return true;
    }

    @rename($temporaryPath, $path);
    return false;
}

function docs_optimize_uploaded_attachment_file(string $path, string $originalName, int $originalSize = 0): array
{
    $result = [
        'optimized' => false,
        'size' => is_file($path) ? (int) (@filesize($path) ?: 0) : 0,
        'originalSize' => max(0, $originalSize),
    ];

    if (!is_file($path) || !docs_attachment_file_can_deduplicate($path)) {
        return $result;
    }

    $actualSize = (int) (@filesize($path) ?: 0);
    if ($actualSize <= 0) {
        return $result;
    }
    $result['size'] = $actualSize;
    if ($result['originalSize'] <= 0) {
        $result['originalSize'] = $actualSize;
    }
    return $result;
}

function docs_deduplicate_attachment_storage(?string $requestedOrganization = null): array
{
    $documentsRoot = realpath(DOCUMENTS_ROOT);
    if (!is_string($documentsRoot) || $documentsRoot === '' || !is_dir($documentsRoot)) {
        return [
            'success' => false,
            'reason' => 'documents_root_missing',
            'filesScanned' => 0,
            'duplicatesLinked' => 0,
            'savedBytes' => 0,
        ];
    }

    $organizationFolders = [];
    if (is_string($requestedOrganization) && trim($requestedOrganization) !== '') {
        $folder = sanitize_folder_name($requestedOrganization);
        if ($folder !== '') {
            $organizationFolders[] = $folder;
        }
    } else {
        $items = @scandir($documentsRoot);
        if (is_array($items)) {
            foreach ($items as $item) {
                if ($item === '.' || $item === '..') {
                    continue;
                }
                $candidate = $documentsRoot . '/' . $item;
                if (is_dir($candidate)) {
                    $organizationFolders[] = $item;
                }
            }
        }
    }

    $organizationFolders = array_values(array_unique(array_filter($organizationFolders, static function ($folder): bool {
        return is_string($folder) && $folder !== '' && $folder !== '.' && $folder !== '..';
    })));

    $seen = [];
    $summary = [
        'success' => true,
        'organizations' => 0,
        'filesScanned' => 0,
        'duplicatesLinked' => 0,
        'savedBytes' => 0,
        'skippedSmall' => 0,
        'linkFailed' => 0,
    ];

    foreach ($organizationFolders as $folder) {
        $storageRoot = $documentsRoot . '/' . $folder;
        if (!is_dir($storageRoot)) {
            continue;
        }
        $summary['organizations']++;

        try {
            $iterator = new RecursiveIteratorIterator(
                new RecursiveDirectoryIterator($storageRoot, FilesystemIterator::SKIP_DOTS),
                RecursiveIteratorIterator::LEAVES_ONLY
            );
        } catch (Throwable $exception) {
            continue;
        }

        foreach ($iterator as $entry) {
            if (!$entry instanceof SplFileInfo || !$entry->isFile()) {
                continue;
            }

            $path = $entry->getPathname();
            if (!docs_attachment_file_can_deduplicate($path)) {
                continue;
            }

            $size = (int) ($entry->getSize() ?: 0);
            if ($size < DOCS_ATTACHMENT_DEDUP_MIN_BYTES) {
                $summary['skippedSmall']++;
                continue;
            }

            $summary['filesScanned']++;
            $hash = @hash_file('sha256', $path);
            if (!is_string($hash) || $hash === '') {
                continue;
            }

            $key = $size . ':' . $hash;
            if (!isset($seen[$key])) {
                $seen[$key] = $path;
                continue;
            }

            $duplicatePath = $seen[$key];
            if (docs_files_share_inode($duplicatePath, $path)) {
                continue;
            }

            if (docs_replace_duplicate_attachment_with_hardlink($path, $duplicatePath)) {
                $summary['duplicatesLinked']++;
                $summary['savedBytes'] += $size;
            } else {
                $summary['linkFailed']++;
            }
        }
    }

    return $summary;
}

function docs_get_attachment_archive_root(string $folder, bool $create = true): string
{
    $dir = ensure_organization_directory($folder) . '/' . DOCS_ATTACHMENT_ARCHIVE_DIRECTORY;
    if ($create && !is_dir($dir)) {
        @mkdir($dir, 0775, true);
    }

    return $dir;
}

function docs_get_attachment_archive_test_root(string $folder, bool $create = true): string
{
    $dir = ensure_organization_directory($folder) . '/' . DOCS_ATTACHMENT_ARCHIVE_TEST_DIRECTORY;
    if ($create && !is_dir($dir)) {
        @mkdir($dir, 0775, true);
    }

    return $dir;
}

function docs_get_attachment_archive_test_manifest_path(string $folder): string
{
    return docs_get_attachment_archive_test_root($folder, true) . '/' . DOCS_ATTACHMENT_ARCHIVE_TEST_MANIFEST;
}

function docs_attachment_archive_test_month_from_values(array $values, string $path): string
{
    foreach ($values as $value) {
        if (!is_scalar($value)) {
            continue;
        }

        $timestamp = @strtotime((string) $value);
        if ($timestamp !== false) {
            return date('Y-m', $timestamp);
        }
    }

    $mtime = is_file($path) ? @filemtime($path) : false;
    if ($mtime !== false) {
        return date('Y-m', (int) $mtime);
    }

    return date('Y-m');
}

function docs_collect_attachment_archive_test_entries(string $folder): array
{
    $entries = [];
    $seen = [];
    $organizationRoot = ensure_organization_directory($folder);
    $organizationRealRoot = realpath($organizationRoot);
    if (!is_string($organizationRealRoot) || $organizationRealRoot === '') {
        return [];
    }
    $organizationRealRoot = rtrim(str_replace('\\', '/', $organizationRealRoot), '/');

    $pushEntry = static function (string $path, string $relativePath, array $file, array $record, string $source) use (&$entries, &$seen, $folder, $organizationRealRoot): void {
        if ($path === '' || !is_file($path) || !is_readable($path) || !docs_attachment_file_can_archive($path)) {
            return;
        }

        $realPath = realpath($path);
        if (!is_string($realPath) || $realPath === '') {
            return;
        }
        $normalizedRealPath = str_replace('\\', '/', $realPath);
        if (strpos($normalizedRealPath, $organizationRealRoot . '/') !== 0) {
            return;
        }
        if (strpos($normalizedRealPath, '/' . DOCS_ATTACHMENT_ARCHIVE_DIRECTORY . '/') !== false
            || strpos($normalizedRealPath, '/' . DOCS_ATTACHMENT_ARCHIVE_TEST_DIRECTORY . '/') !== false) {
            return;
        }
        if (isset($seen[$normalizedRealPath])) {
            return;
        }

        $relativePath = docs_normalize_archive_entry_name($relativePath !== '' ? $relativePath : substr($normalizedRealPath, strlen($organizationRealRoot) + 1));
        if ($relativePath === '') {
            return;
        }

        $size = (int) (@filesize($realPath) ?: 0);
        if ($size <= 0) {
            return;
        }

        $month = docs_attachment_archive_test_month_from_values([
            $file['uploadedAt'] ?? null,
            $file['createdAt'] ?? null,
            $record['registrationDate'] ?? null,
            $record['documentDate'] ?? null,
            $record['createdAt'] ?? null,
            $record['updatedAt'] ?? null,
        ], $realPath);

        $originalName = sanitize_text_field((string) ($file['originalName'] ?? ($file['name'] ?? ($file['storedName'] ?? basename($relativePath)))), 255);
        if ($originalName === '') {
            $originalName = basename($relativePath);
        }

        $seen[$normalizedRealPath] = true;
        $entries[] = [
            'path' => $realPath,
            'relativePath' => $relativePath,
            'entry' => $relativePath,
            'month' => $month,
            'archive' => $month . '.test.zip',
            'originalName' => $originalName,
            'size' => $size,
            'source' => $source,
            'documentId' => sanitize_text_field((string) ($record['id'] ?? ''), 200),
            'registryNumber' => sanitize_text_field((string) ($record['registryNumber'] ?? ''), 120),
        ];
    };

    foreach (load_registry($folder) as $record) {
        if (!is_array($record)) {
            continue;
        }

        if (isset($record['files']) && is_array($record['files'])) {
            foreach ($record['files'] as $file) {
                if (!is_array($file)) {
                    continue;
                }
                $storedName = sanitize_text_field((string) ($file['storedName'] ?? ''), 255);
                if ($storedName === '') {
                    continue;
                }
                $pushEntry($organizationRoot . '/' . $storedName, $storedName, $file, $record, 'registry_file');
            }
        }

        if (isset($record['responses']) && is_array($record['responses'])) {
            $documentId = sanitize_text_field((string) ($record['id'] ?? ''), 200);
            if ($documentId === '') {
                continue;
            }
            foreach ($record['responses'] as $response) {
                if (!is_array($response)) {
                    continue;
                }
                $storedName = sanitize_text_field((string) ($response['storedName'] ?? ''), 255);
                if ($storedName === '') {
                    continue;
                }
                $relativePath = 'Ответы/' . $documentId . '/' . $storedName;
                $pushEntry(docs_get_document_responses_dir($folder, $documentId, false) . '/' . $storedName, $relativePath, $response, $record, 'response_file');
            }
        }
    }

    foreach (docs_load_outgoing_registry($folder) as $record) {
        if (!is_array($record) || !isset($record['files']) || !is_array($record['files'])) {
            continue;
        }
        foreach ($record['files'] as $file) {
            if (!is_array($file)) {
                continue;
            }
            foreach (docs_get_outgoing_file_path_candidates($folder, $file) as $pathCandidate) {
                $storedName = sanitize_text_field((string) ($file['storedName'] ?? basename($pathCandidate)), 255);
                $relativePath = 'Исходящие/' . ($storedName !== '' ? $storedName : basename($pathCandidate));
                $pushEntry($pathCandidate, $relativePath, $file, $record, 'outgoing_file');
            }
        }
    }

    usort($entries, static function (array $left, array $right): int {
        return strcmp((string) ($left['month'] ?? ''), (string) ($right['month'] ?? ''))
            ?: strcmp((string) ($left['relativePath'] ?? ''), (string) ($right['relativePath'] ?? ''));
    });

    return $entries;
}

function docs_delete_attachment_archive_test_files(string $folder, string $archiveName = ''): array
{
    $archiveRoot = docs_get_attachment_archive_test_root($folder, true);
    $deleted = 0;
    $bytesDeleted = 0;
    $archiveName = sanitize_text_field($archiveName, 255);
    $archiveName = str_replace('\\', '/', $archiveName);
    if (strpos($archiveName, '..') !== false || strpos($archiveName, '/') !== false) {
        $archiveName = '';
    }

    $items = @scandir($archiveRoot);
    if (is_array($items)) {
        foreach ($items as $item) {
            if ($item === '.' || $item === '..') {
                continue;
            }
            if ($archiveName !== '' && $item !== $archiveName) {
                continue;
            }
            if ($item !== DOCS_ATTACHMENT_ARCHIVE_TEST_MANIFEST && substr($item, -9) !== '.test.zip') {
                continue;
            }
            $path = $archiveRoot . '/' . $item;
            if (!is_file($path)) {
                continue;
            }
            $size = (int) (@filesize($path) ?: 0);
            if (@unlink($path)) {
                $deleted++;
                $bytesDeleted += $size;
            }
        }
    }

    if ($archiveName !== '') {
        docs_refresh_attachment_archive_test_manifest($folder);
    }

    return [
        'deleted' => $deleted,
        'bytesDeleted' => $bytesDeleted,
        'bytesDeletedLabel' => docs_format_file_size($bytesDeleted),
    ];
}

function docs_refresh_attachment_archive_test_manifest(string $folder, array $manifest = []): array
{
    if (empty($manifest)) {
        $manifest = docs_collect_attachment_archive_test_summary($folder, false);
    }

    $path = docs_get_attachment_archive_test_manifest_path($folder);
    $encoded = json_encode($manifest, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    if ($encoded !== false) {
        @file_put_contents($path, $encoded . PHP_EOL, LOCK_EX);
        @chmod($path, 0644);
    }

    return $manifest;
}

function docs_generate_attachment_archive_test(string $folder, bool $replace = true): array
{
    if (!class_exists('ZipArchive')) {
        return [
            'success' => false,
            'message' => 'На сервере недоступен ZipArchive.',
        ];
    }

    if ($replace) {
        docs_delete_attachment_archive_test_files($folder);
    }

    $archiveRoot = docs_get_attachment_archive_test_root($folder, true);
    if (!is_dir($archiveRoot) || !is_writable($archiveRoot)) {
        return [
            'success' => false,
            'message' => 'Не удалось подготовить папку тестовых архивов.',
        ];
    }

    $entries = docs_collect_attachment_archive_test_entries($folder);
    $zips = [];
    $filesAdded = 0;
    $sourceBytes = 0;
    $skipped = 0;
    $manifestEntries = [];

    foreach ($entries as $entry) {
        $archiveName = sanitize_text_field((string) ($entry['archive'] ?? ''), 255);
        $sourcePath = (string) ($entry['path'] ?? '');
        $entryName = docs_normalize_archive_entry_name((string) ($entry['entry'] ?? ''));
        if ($archiveName === '' || $sourcePath === '' || $entryName === '') {
            $skipped++;
            continue;
        }

        $archivePath = $archiveRoot . '/' . $archiveName;
        $zip = new ZipArchive();
        $openResult = $zip->open($archivePath, ZipArchive::CREATE);
        if ($openResult !== true) {
            $skipped++;
            continue;
        }

        $entryCandidate = $entryName;
        $duplicateIndex = 2;
        while ($zip->locateName($entryCandidate) !== false) {
            $pathInfo = pathinfo($entryName);
            $extension = isset($pathInfo['extension']) && $pathInfo['extension'] !== '' ? '.' . $pathInfo['extension'] : '';
            $filename = $pathInfo['filename'] ?? $entryName;
            $dirname = isset($pathInfo['dirname']) && $pathInfo['dirname'] !== '.' ? $pathInfo['dirname'] . '/' : '';
            $entryCandidate = $dirname . $filename . '_' . $duplicateIndex . $extension;
            $duplicateIndex++;
        }

        $added = $zip->addFile($sourcePath, $entryCandidate);
        if ($added && method_exists($zip, 'setCompressionName')) {
            @$zip->setCompressionName($entryCandidate, ZipArchive::CM_DEFLATE, 6);
        }
        $closed = $zip->close();
        if (!$added || !$closed) {
            $skipped++;
            continue;
        }

        $size = (int) ($entry['size'] ?? 0);
        $filesAdded++;
        $sourceBytes += $size;
        $zips[$archiveName] = true;
        $archiveMeta = [
            'zip' => $archiveName,
            'entry' => $entryCandidate,
            'test' => true,
        ];
        $manifestEntry = [
            'archive' => $archiveName,
            'entry' => $entryCandidate,
            'originalName' => $entry['originalName'] ?? basename($entryCandidate),
            'size' => $size,
            'sizeLabel' => docs_format_file_size($size),
            'source' => $entry['source'] ?? '',
            'documentId' => $entry['documentId'] ?? '',
            'registryNumber' => $entry['registryNumber'] ?? '',
            'url' => docs_build_archived_attachment_url($folder, $archiveMeta, (string) ($entry['originalName'] ?? basename($entryCandidate))),
        ];
        $manifestEntries[] = array_filter($manifestEntry, static function ($value) {
            return $value !== '' && $value !== 0;
        });
    }

    $archives = docs_collect_attachment_archive_test_summary($folder, false)['archives'] ?? [];
    $zipBytes = 0;
    foreach ($archives as $archive) {
        $zipBytes += (int) ($archive['bytes'] ?? 0);
    }

    $manifest = [
        'success' => true,
        'generatedAt' => date('c'),
        'filesAdded' => $filesAdded,
        'sourceBytes' => $sourceBytes,
        'sourceLabel' => docs_format_file_size($sourceBytes),
        'zipBytes' => $zipBytes,
        'zipLabel' => docs_format_file_size($zipBytes),
        'archivesCount' => count($zips),
        'skipped' => $skipped,
        'entries' => array_slice($manifestEntries, 0, 200),
        'archives' => $archives,
    ];
    docs_refresh_attachment_archive_test_manifest($folder, $manifest);

    return $manifest;
}

function docs_collect_attachment_archive_test_summary(string $folder, bool $includeManifest = true): array
{
    $archiveRoot = docs_get_attachment_archive_test_root($folder, true);
    $archives = [];
    $totalBytes = 0;
    $totalEntries = 0;

    $items = @scandir($archiveRoot);
    if (is_array($items)) {
        foreach ($items as $item) {
            if ($item === '.' || $item === '..' || substr($item, -9) !== '.test.zip') {
                continue;
            }
            $path = $archiveRoot . '/' . $item;
            if (!is_file($path)) {
                continue;
            }
            $bytes = (int) (@filesize($path) ?: 0);
            $entriesCount = 0;
            if (class_exists('ZipArchive')) {
                $zip = new ZipArchive();
                if ($zip->open($path) === true) {
                    $entriesCount = max(0, (int) $zip->numFiles);
                    $zip->close();
                }
            }
            $archives[] = [
                'name' => $item,
                'bytes' => $bytes,
                'label' => docs_format_file_size($bytes),
                'entries' => $entriesCount,
                'updatedAt' => date('c', (int) (@filemtime($path) ?: time())),
            ];
            $totalBytes += $bytes;
            $totalEntries += $entriesCount;
        }
    }

    usort($archives, static function (array $left, array $right): int {
        return strcmp((string) ($right['name'] ?? ''), (string) ($left['name'] ?? ''));
    });

    $manifestEntries = [];
    $manifestPath = docs_get_attachment_archive_test_manifest_path($folder);
    if ($includeManifest && is_file($manifestPath)) {
        $raw = @file_get_contents($manifestPath);
        $decoded = is_string($raw) && $raw !== '' ? json_decode($raw, true) : null;
        if (is_array($decoded) && isset($decoded['entries']) && is_array($decoded['entries'])) {
            $manifestEntries = array_values(array_filter($decoded['entries'], static function ($entry): bool {
                return is_array($entry);
            }));
        }
    }

    return [
        'success' => true,
        'path' => 'documents/' . $folder . '/' . DOCS_ATTACHMENT_ARCHIVE_TEST_DIRECTORY,
        'archives' => $archives,
        'archivesCount' => count($archives),
        'totalBytes' => $totalBytes,
        'totalLabel' => docs_format_file_size($totalBytes),
        'totalEntries' => $totalEntries,
        'samples' => array_slice($manifestEntries, 0, 12),
        'checkedAt' => date('c'),
    ];
}

function docs_build_attachment_archive_name(array $file, array $record): string
{
    $dateCandidate = '';
    foreach ([$file['uploadedAt'] ?? null, $record['registrationDate'] ?? null, $record['createdAt'] ?? null, $record['updatedAt'] ?? null] as $value) {
        $timestamp = is_scalar($value) ? @strtotime((string) $value) : false;
        if ($timestamp !== false) {
            $dateCandidate = date('Y-m', $timestamp);
            break;
        }
    }
    if ($dateCandidate === '') {
        $dateCandidate = date('Y-m');
    }

    return $dateCandidate . '.zip';
}

function docs_normalize_archive_entry_name(string $relativePath): string
{
    $relativePath = str_replace('\\', '/', $relativePath);
    $segments = preg_split('#/+#', $relativePath, -1, PREG_SPLIT_NO_EMPTY);
    if (!is_array($segments)) {
        return '';
    }

    $safeSegments = [];
    foreach ($segments as $segment) {
        $segment = trim((string) $segment);
        if ($segment === '' || $segment === '.' || $segment === '..') {
            continue;
        }
        $safeSegments[] = docs_sanitize_filename($segment, 'file');
    }

    return implode('/', $safeSegments);
}

function docs_archive_attachment_file(string $folder, string $path, string $relativePath, array $file, array $record): ?array
{
    if (!class_exists('ZipArchive') || !is_file($path) || !is_readable($path) || !docs_attachment_file_can_archive($path)) {
        return null;
    }

    $size = (int) (@filesize($path) ?: 0);
    if ($size < DOCS_ATTACHMENT_ARCHIVE_MIN_BYTES) {
        return null;
    }

    $archiveRoot = docs_get_attachment_archive_root($folder, true);
    if (!is_dir($archiveRoot) || !is_writable($archiveRoot)) {
        return null;
    }

    $archiveName = docs_build_attachment_archive_name($file, $record);
    $archivePath = $archiveRoot . '/' . $archiveName;
    $entryName = docs_normalize_archive_entry_name($relativePath);
    if ($entryName === '') {
        return null;
    }

    $zip = new ZipArchive();
    $openResult = $zip->open($archivePath, ZipArchive::CREATE);
    if ($openResult !== true) {
        return null;
    }

    $entryCandidate = $entryName;
    $duplicateIndex = 2;
    while ($zip->locateName($entryCandidate) !== false) {
        $pathInfo = pathinfo($entryName);
        $extension = isset($pathInfo['extension']) && $pathInfo['extension'] !== '' ? '.' . $pathInfo['extension'] : '';
        $filename = $pathInfo['filename'] ?? $entryName;
        $dirname = isset($pathInfo['dirname']) && $pathInfo['dirname'] !== '.' ? $pathInfo['dirname'] . '/' : '';
        $entryCandidate = $dirname . $filename . '_' . $duplicateIndex . $extension;
        $duplicateIndex++;
    }

    $added = $zip->addFile($path, $entryCandidate);
    if ($added && method_exists($zip, 'setCompressionName')) {
        @$zip->setCompressionName($entryCandidate, ZipArchive::CM_DEFLATE, 6);
    }
    $closed = $zip->close();
    if (!$added || !$closed) {
        return null;
    }

    if (!@unlink($path)) {
        return null;
    }

    return [
        'zip' => $archiveName,
        'entry' => $entryCandidate,
        'size' => $size,
        'archivedAt' => date('c'),
    ];
}

function docs_archive_record_file_entry(array &$file, string $folder, string $path, string $relativePath, array $record): bool
{
    if (!is_array($file) || !empty($file['archive'])) {
        return false;
    }

    $archive = docs_archive_attachment_file($folder, $path, $relativePath, $file, $record);
    if (!is_array($archive)) {
        return false;
    }

    $file['archive'] = $archive;
    $file['url'] = docs_build_archived_attachment_url(
        $folder,
        $archive,
        sanitize_text_field((string) ($file['originalName'] ?? ($file['storedName'] ?? 'document')), 255)
    );

    return true;
}

function docs_archive_registry_attachments(string $folder): array
{
    [$registryHandle, $records] = docs_lock_registry($folder);
    if ($registryHandle === null) {
        $records = load_registry($folder);
    }

    $summary = [
        'filesArchived' => 0,
        'bytesArchived' => 0,
        'recordsChanged' => 0,
    ];
    $changed = false;
    $dir = ensure_organization_directory($folder);

    foreach ($records as &$record) {
        if (!is_array($record)) {
            continue;
        }
        $recordChanged = false;

        if (isset($record['files']) && is_array($record['files'])) {
            foreach ($record['files'] as &$file) {
                if (!is_array($file)) {
                    continue;
                }
                $storedName = sanitize_text_field((string) ($file['storedName'] ?? ''), 255);
                if ($storedName === '') {
                    continue;
                }
                $path = $dir . '/' . $storedName;
                $size = is_file($path) ? (int) (@filesize($path) ?: 0) : 0;
                if (docs_archive_record_file_entry($file, $folder, $path, $storedName, $record)) {
                    $summary['filesArchived']++;
                    $summary['bytesArchived'] += $size;
                    $recordChanged = true;
                    $changed = true;
                }
            }
            unset($file);
        }

        if (isset($record['responses']) && is_array($record['responses'])) {
            $documentId = sanitize_text_field((string) ($record['id'] ?? ''), 200);
            foreach ($record['responses'] as &$response) {
                if (!is_array($response)) {
                    continue;
                }
                $storedName = sanitize_text_field((string) ($response['storedName'] ?? ''), 255);
                if ($storedName === '' || $documentId === '') {
                    continue;
                }
                $relativePath = 'Ответы/' . $documentId . '/' . $storedName;
                $path = docs_get_document_responses_dir($folder, $documentId, false) . '/' . $storedName;
                $size = is_file($path) ? (int) (@filesize($path) ?: 0) : 0;
                if (docs_archive_record_file_entry($response, $folder, $path, $relativePath, $record)) {
                    $summary['filesArchived']++;
                    $summary['bytesArchived'] += $size;
                    $recordChanged = true;
                    $changed = true;
                }
            }
            unset($response);
        }

        if ($recordChanged) {
            $summary['recordsChanged']++;
        }
    }
    unset($record);

    if ($changed) {
        if ($registryHandle !== null) {
            docs_save_registry_locked($registryHandle, $records);
            docs_unlock_registry($registryHandle);
        } else {
            save_registry($folder, $records);
        }
    } elseif ($registryHandle !== null) {
        docs_unlock_registry($registryHandle);
    }

    return $summary;
}

function docs_archive_attachment_storage(?string $requestedOrganization = null): array
{
    $organizations = [];
    if (is_string($requestedOrganization) && trim($requestedOrganization) !== '') {
        $organizations[] = $requestedOrganization;
    } else {
        $organizations = load_organizations();
    }

    $summary = [
        'success' => true,
        'organizations' => 0,
        'filesArchived' => 0,
        'bytesArchived' => 0,
        'recordsChanged' => 0,
    ];

    foreach ($organizations as $organization) {
        $folder = sanitize_folder_name((string) $organization);
        if ($folder === '') {
            continue;
        }
        $organizationSummary = docs_archive_registry_attachments($folder);
        $summary['organizations']++;
        $summary['filesArchived'] += (int) ($organizationSummary['filesArchived'] ?? 0);
        $summary['bytesArchived'] += (int) ($organizationSummary['bytesArchived'] ?? 0);
        $summary['recordsChanged'] += (int) ($organizationSummary['recordsChanged'] ?? 0);
    }

    return $summary;
}

function docs_optimize_attachment_storage(?string $requestedOrganization = null): array
{
    $before = docs_collect_storage_size_summary($requestedOrganization);
    $archiveSummary = docs_archive_attachment_storage($requestedOrganization);
    $dedupeSummary = docs_deduplicate_attachment_storage($requestedOrganization);
    $after = docs_collect_storage_size_summary($requestedOrganization);

    return [
        'success' => true,
        'organization' => is_string($requestedOrganization) && trim($requestedOrganization) !== '' ? $requestedOrganization : null,
        'before' => $before,
        'after' => $after,
        'archive' => $archiveSummary,
        'dedupe' => $dedupeSummary,
        'savedBytes' => max(0, (int) ($before['bytes'] ?? 0) - (int) ($after['bytes'] ?? 0)),
        'savedLabel' => docs_format_file_size(max(0, (int) ($before['bytes'] ?? 0) - (int) ($after['bytes'] ?? 0))),
    ];
}

function sanitize_status(?string $value, bool $useDefault = false): string
{
    $value = sanitize_text_field($value, 80);
    if ($value === '') {
        return $useDefault ? 'Принято в работу' : '';
    }

    $normalized = mb_strtolower($value);
    $map = [
        'в работе'        => 'Принято в работу',
        'принято в работу'=> 'Принято в работу',
        'принято вработу' => 'Принято в работу',
        'принято в работ' => 'Принято в работу',
        'распределено'    => 'Распределено',
        'распределен'     => 'Распределено',
        'распределена'    => 'Распределено',
        'распределены'    => 'Распределено',
        'на контроле'     => 'На проверке',
        'на проверке'     => 'На проверке',
        'на проверку'     => 'На проверке',
        'завершено'       => 'Выполнено',
        'выполнено'       => 'Выполнено',
        'отменено'        => 'Отменено',
    ];

    if (isset($map[$normalized])) {
        return $map[$normalized];
    }

    return mb_convert_case($normalized, MB_CASE_TITLE, 'UTF-8');
}

function docs_init_status_counters(): array
{
    return [
        'distributed' => 0,
        'accepted' => 0,
        'review' => 0,
        'done' => 0,
        'cancelled' => 0,
    ];
}

function docs_status_key_from_status($status): ?string
{
    if ($status === null) {
        return null;
    }

    $raw = trim((string) $status);
    if ($raw === '') {
        return null;
    }

    $sanitized = sanitize_status($raw);
    $normalized = mb_strtolower($sanitized, 'UTF-8');

    switch ($normalized) {
        case 'распределено':
            return 'distributed';
        case 'принято в работу':
            return 'accepted';
        case 'на проверке':
            return 'review';
        case 'выполнено':
            return 'done';
        case 'отменено':
            return 'cancelled';
        default:
            return null;
    }
}

function docs_normalize_datetime_iso(?string $value): ?string
{
    if ($value === null) {
        return null;
    }

    $raw = trim((string) $value);
    if ($raw === '') {
        return null;
    }

    try {
        $date = new DateTime($raw);
        return $date->format(DateTime::ATOM);
    } catch (Exception $exception) {
        return null;
    }
}

function docs_sanitize_filename(string $name, string $default = 'document.pdf'): string
{
    $candidate = trim($name);
    if ($candidate === '') {
        $candidate = $default;
    }

    $candidate = preg_replace('/[\x00-\x1F\x7F]+/u', '', $candidate);
    $candidate = str_replace(['\\', '/', ':', '*', '?', '"', '<', '>', '|'], '_', $candidate);
    $candidate = preg_replace('/\s+/u', '_', $candidate);

    if ($candidate === '' || $candidate === '_') {
        $candidate = $default;
    }

    if (mb_strlen($candidate, 'UTF-8') > 200) {
        $candidate = mb_substr($candidate, 0, 200, 'UTF-8');
    }

    return $candidate;
}

function docs_get_pdf_cache_directory(): string
{
    static $ensured = false;

    if (!is_dir(MINI_APP_PDF_CACHE_DIRECTORY)) {
        $created = @mkdir(MINI_APP_PDF_CACHE_DIRECTORY, 0775, true);
        if (!$created) {
            log_docs_event('Mini app PDF cache directory unavailable', [
                'directory' => MINI_APP_PDF_CACHE_DIRECTORY,
                'exists' => is_dir(MINI_APP_PDF_CACHE_DIRECTORY),
                'writable' => is_writable(dirname(MINI_APP_PDF_CACHE_DIRECTORY)),
            ]);
        }
    }

    if (!$ensured && is_dir(MINI_APP_PDF_CACHE_DIRECTORY)) {
        $ensured = true;
        log_docs_event('Mini app PDF cache directory ready', [
            'directory' => MINI_APP_PDF_CACHE_DIRECTORY,
        ]);
    }

    return MINI_APP_PDF_CACHE_DIRECTORY;
}

function docs_cleanup_pdf_cache(string $directory, int $maxAge = MINI_APP_PDF_CACHE_TTL): void
{
    if (!is_dir($directory)) {
        return;
    }

    $now = time();
    $handle = @opendir($directory);
    if ($handle === false) {
        return;
    }

    while (($entry = readdir($handle)) !== false) {
        if ($entry === '.' || $entry === '..') {
            continue;
        }

        $path = $directory . '/' . $entry;
        if (!is_file($path)) {
            continue;
        }

        $mtime = @filemtime($path);
        if ($mtime === false) {
            continue;
        }

        if ($now - $mtime > $maxAge) {
            @unlink($path);
        }
    }

    closedir($handle);
}

function docs_build_public_pdf_url(string $fileName): string
{
    $safeName = ltrim($fileName, '/');

    return '/cache/miniapp_pdf/' . rawurlencode($safeName);
}

function docs_build_public_pdf_delivery_url(string $storedFileName, string $fileName): string
{
    $safeStoredName = basename(ltrim($storedFileName, '/'));
    $safeFileName = docs_sanitize_filename($fileName, 'document.pdf');

    return '/docs.php?' . http_build_query([
        'action' => 'mini_app_cached_pdf',
        'file' => $safeStoredName,
        'name' => $safeFileName,
        'disposition' => 'inline',
    ], '', '&', PHP_QUERY_RFC3986);
}

function docs_handle_mini_app_cached_pdf(string $method): void
{
    $method = strtoupper($method);
    if ($method !== 'GET' && $method !== 'HEAD') {
        respond_error('Некорректный метод запроса.', 405, ['allowedMethod' => 'GET']);
    }

    $storedFileName = isset($_GET['file']) && is_string($_GET['file'])
        ? basename(sanitize_text_field($_GET['file'], 255))
        : '';
    if ($storedFileName === '' || !preg_match('/^miniapp_\d{8}_\d{6}_[a-f0-9]{16}\.pdf$/i', $storedFileName)) {
        respond_error('Файл не найден.', 404);
    }

    $cacheDirectory = docs_get_pdf_cache_directory();
    $cacheRoot = realpath($cacheDirectory);
    if (!is_string($cacheRoot) || $cacheRoot === '') {
        respond_error('Файл не найден.', 404);
    }

    $filePath = rtrim($cacheRoot, DIRECTORY_SEPARATOR) . DIRECTORY_SEPARATOR . $storedFileName;
    $realPath = realpath($filePath);
    $rootPrefix = rtrim($cacheRoot, DIRECTORY_SEPARATOR) . DIRECTORY_SEPARATOR;
    if (!is_string($realPath) || !is_file($realPath) || strpos($realPath, $rootPrefix) !== 0) {
        respond_error('Файл не найден.', 404);
    }

    $fileName = isset($_GET['name']) && is_string($_GET['name'])
        ? docs_sanitize_filename($_GET['name'], 'document.pdf')
        : 'document.pdf';
    if ($fileName === '') {
        $fileName = 'document.pdf';
    }

    $disposition = isset($_GET['disposition']) && is_string($_GET['disposition'])
        ? $_GET['disposition']
        : 'inline';
    $disposition = strtolower(trim($disposition)) === 'attachment' ? 'attachment' : 'inline';

    docs_stream_file_response($realPath, $fileName, $disposition, $method);
}

function sanitize_folder_name(string $name): string
{
    $candidate = preg_replace('/[^\p{L}\p{N}\s._-]/u', '', $name);
    $candidate = preg_replace('/\s+/u', '_', trim((string) $candidate));

    if ($candidate === '') {
        $candidate = 'organization_' . substr(sha1($name), 0, 8);
    }

    return $candidate;
}

function get_registry_path(string $folder): string
{
    return DOCUMENTS_ROOT . '/' . $folder . '/' . REGISTRY_FILENAME;
}

function get_outgoing_registry_path(string $folder): string
{
    return DOCUMENTS_ROOT . '/' . $folder . '/' . OUTGOING_REGISTRY_FILENAME;
}

function get_orders_registry_path(string $folder): string
{
    return DOCUMENTS_ROOT . '/' . $folder . '/' . ORDERS_REGISTRY_FILENAME;
}

function get_settings_path(string $folder): string
{
    return DOCUMENTS_ROOT . '/' . $folder . '/' . SETTINGS_FILENAME;
}

function docs_outgoing_pick_first(array $record, array $fields, int $maxLength = 220): string
{
    foreach ($fields as $field) {
        if (!is_string($field) || $field === '' || !array_key_exists($field, $record)) {
            continue;
        }

        $value = sanitize_text_field((string) $record[$field], $maxLength);
        if ($value !== '') {
            return $value;
        }
    }

    return '';
}

function docs_prepare_outgoing_record(array $record, string $source = 'outgoing', bool $includeInternal = false): array
{
    $files = docs_prepare_outgoing_files_payload($record['files'] ?? []);
    $fileNames = [];
    foreach ($files as $file) {
        $fileName = sanitize_text_field((string) ($file['originalName'] ?? ($file['storedName'] ?? '')), 220);
        if ($fileName !== '') {
            $fileNames[] = $fileName;
        }
    }

    $prepared = [
        'id' => sanitize_text_field((string) ($record['id'] ?? ''), 160),
        'source' => sanitize_text_field($source, 40),
        'outgoingNumber' => sanitize_text_field((string) ($record['outgoingNumber'] ?? ''), 160),
        'sendingDate' => sanitize_date_field(isset($record['sendingDate']) ? (string) $record['sendingDate'] : ''),
        'documentIndexNumber' => sanitize_text_field((string) ($record['documentIndexNumber'] ?? ''), 220),
        'documentType' => sanitize_text_field((string) ($record['documentType'] ?? 'Исходящий'), 80),
        'addressee' => sanitize_text_field((string) ($record['addressee'] ?? ''), 260),
        'summary' => sanitize_text_field((string) ($record['summary'] ?? ''), 1000),
        'files' => $files,
        'filesLabel' => !empty($fileNames)
            ? sanitize_text_field(implode(', ', $fileNames), 500)
            : sanitize_text_field((string) ($record['filesLabel'] ?? ''), 500),
        'filesCount' => count($files),
        'executor' => sanitize_text_field((string) ($record['executor'] ?? ''), 220),
        'note' => sanitize_text_field((string) ($record['note'] ?? ''), 500),
        'registeredBy' => sanitize_text_field((string) ($record['registeredBy'] ?? ''), 220),
        'registeredAt' => docs_normalize_datetime_iso(isset($record['registeredAt']) ? (string) $record['registeredAt'] : null) ?? '',
        'createdBy' => sanitize_text_field((string) ($record['createdBy'] ?? ''), 220),
        'createdByKey' => sanitize_text_field((string) ($record['createdByKey'] ?? ''), 200),
        'createdAt' => docs_normalize_datetime_iso(isset($record['createdAt']) ? (string) $record['createdAt'] : null) ?? '',
        'updatedBy' => sanitize_text_field((string) ($record['updatedBy'] ?? ''), 220),
        'updatedByKey' => sanitize_text_field((string) ($record['updatedByKey'] ?? ''), 200),
        'updatedAt' => docs_normalize_datetime_iso(isset($record['updatedAt']) ? (string) $record['updatedAt'] : null) ?? '',
        'deleted' => !empty($record['deleted']),
    ];

    if ($prepared['id'] === '') {
        $prepared['id'] = docs_create_outgoing_record_id();
    }

    if ($prepared['documentType'] === '') {
        $prepared['documentType'] = 'Исходящий';
    }

    if ($includeInternal) {
        $editLock = docs_prepare_outgoing_edit_lock($record['editLock'] ?? null);
        if (!empty($editLock) && docs_outgoing_edit_lock_is_active($editLock)) {
            $prepared['editLock'] = $editLock;
        }
    }

    return $prepared;
}

function docs_payload_first_text(array $payload, array $fields, int $maxLength = 220): string
{
    foreach ($fields as $field) {
        if (!is_string($field) || $field === '' || !array_key_exists($field, $payload)) {
            continue;
        }

        $value = sanitize_text_field((string) $payload[$field], $maxLength);
        if ($value !== '') {
            return $value;
        }
    }

    return '';
}

function docs_payload_first_date(array $payload, array $fields): string
{
    foreach ($fields as $field) {
        if (!is_string($field) || $field === '' || !array_key_exists($field, $payload)) {
            continue;
        }

        $value = sanitize_date_field((string) $payload[$field]);
        if ($value !== '') {
            return $value;
        }
    }

    return '';
}

function docs_normalize_outgoing_save_payload(array $payload): array
{
    foreach (['payload', 'fields', 'record', 'data'] as $field) {
        if (!isset($payload[$field])) {
            continue;
        }

        $nested = $payload[$field];
        if (is_string($nested)) {
            $decoded = json_decode($nested, true);
            $nested = is_array($decoded) ? $decoded : [];
        }

        if (!is_array($nested) || empty($nested)) {
            continue;
        }

        unset($payload[$field]);
        foreach ($nested as $key => $value) {
            if (!is_string($key) && !is_int($key)) {
                continue;
            }

            $key = (string) $key;
            $currentValue = $payload[$key] ?? null;
            $currentIsEmpty = $currentValue === null
                || (is_string($currentValue) && trim($currentValue) === '')
                || (is_array($currentValue) && empty($currentValue));

            $nestedArrayShouldWin = is_array($value)
                && in_array($key, ['filesToDelete', 'filesRemaining'], true);

            if ($nestedArrayShouldWin || !array_key_exists($key, $payload) || $currentIsEmpty) {
                $payload[$key] = $value;
            }
        }
    }

    return $payload;
}

function docs_payload_first_scalar_text(array $payload, array $fields, int $maxLength = 220): string
{
    foreach ($fields as $field) {
        if (!is_string($field) || $field === '' || !array_key_exists($field, $payload)) {
            continue;
        }

        $value = $payload[$field];
        if (is_array($value)) {
            $value = reset($value);
        }
        if (is_object($value) || is_array($value)) {
            continue;
        }

        $value = sanitize_text_field((string) $value, $maxLength);
        if ($value !== '') {
            return $value;
        }
    }

    return '';
}

function docs_payload_has_any_field(array $payload, array $fields): bool
{
    foreach ($fields as $field) {
        if (is_string($field) && $field !== '' && array_key_exists($field, $payload)) {
            return true;
        }
    }

    return false;
}

function docs_create_outgoing_record_id(): string
{
    try {
        return 'outgoing_' . bin2hex(random_bytes(8));
    } catch (Throwable $exception) {
        return 'outgoing_' . str_replace('.', '', uniqid('', true));
    }
}

function docs_prepare_outgoing_files_payload($value): array
{
    if (!is_array($value)) {
        return [];
    }

    $files = [];
    foreach ($value as $file) {
        if (!is_array($file)) {
            continue;
        }

        $storedName = sanitize_text_field((string) ($file['storedName'] ?? ''), 255);
        $url = sanitize_text_field((string) ($file['url'] ?? ''), 500);
        if ($storedName === '' && $url === '') {
            continue;
        }

        $visibility = docs_normalize_outgoing_file_visibility($file['visibility'] ?? '');

        $files[] = array_filter([
            'originalName' => sanitize_text_field((string) ($file['originalName'] ?? ($file['name'] ?? $storedName)), 255),
            'storedName' => $storedName,
            'size' => isset($file['size']) ? max(0, (int) $file['size']) : 0,
            'uploadedAt' => docs_normalize_datetime_iso(isset($file['uploadedAt']) ? (string) $file['uploadedAt'] : null) ?? '',
            'url' => $url,
            'accessKey' => sanitize_text_field((string) ($file['accessKey'] ?? ''), 200),
            'visibility' => $visibility,
            'uploadedBy' => sanitize_text_field((string) ($file['uploadedBy'] ?? ''), 220),
            'uploadedByKey' => sanitize_text_field((string) ($file['uploadedByKey'] ?? ''), 200),
        ], static function ($item) {
            return $item !== '' && $item !== 0;
        });
    }

    return $files;
}

function docs_normalize_outgoing_file_visibility($value): string
{
    $normalized = mb_strtolower(trim((string) $value), 'UTF-8');
    if (in_array($normalized, ['private', 'privat', '1', 'true', 'yes', 'on', 'приватный', 'личный'], true)) {
        return 'private';
    }

    return 'public';
}

function docs_payload_requests_private_outgoing_files(array $payload): bool
{
    foreach (['outgoingFilesPrivate', 'filesPrivate', 'privateFiles', 'isPrivate'] as $key) {
        if (!array_key_exists($key, $payload)) {
            continue;
        }
        $value = is_array($payload[$key]) ? reset($payload[$key]) : $payload[$key];
        $normalized = mb_strtolower(trim((string) $value), 'UTF-8');
        if (in_array($normalized, ['1', 'true', 'yes', 'on', 'private', 'приватный'], true)) {
            return true;
        }
    }

    $visibility = docs_normalize_outgoing_file_visibility($payload['filesVisibility'] ?? ($payload['visibility'] ?? ''));

    return $visibility === 'private';
}

function docs_is_outgoing_file_private(array $file): bool
{
    return docs_normalize_outgoing_file_visibility($file['visibility'] ?? '') === 'private';
}

function docs_normalize_outgoing_user_key(string $value): string
{
    $value = sanitize_text_field($value, 200);
    $value = trim($value);

    return $value !== '' ? mb_strtolower($value, 'UTF-8') : '';
}

function docs_normalize_outgoing_user_keys($value): array
{
    $values = is_array($value) ? $value : [$value];
    $keys = [];
    foreach ($values as $item) {
        if (is_array($item)) {
            foreach (docs_normalize_outgoing_user_keys($item) as $nestedKey) {
                $keys[$nestedKey] = true;
            }
            continue;
        }

        $key = docs_normalize_outgoing_user_key((string) $item);
        if ($key !== '') {
            $keys[$key] = true;
        }
    }

    return array_keys($keys);
}

function docs_outgoing_file_user_can_access(array $file, bool $canManageOutgoing, $currentUserKeys): bool
{
    if (!docs_is_outgoing_file_private($file)) {
        return true;
    }

    if ($canManageOutgoing) {
        return true;
    }

    $ownerKey = docs_normalize_outgoing_user_key((string) ($file['uploadedByKey'] ?? ''));
    if ($ownerKey === '') {
        return false;
    }

    foreach (docs_normalize_outgoing_user_keys($currentUserKeys) as $viewerKey) {
        if (hash_equals($ownerKey, $viewerKey)) {
            return true;
        }
    }

    return false;
}

function docs_outgoing_record_user_can_edit(array $record, bool $_canManageOutgoing, $currentUserKeys): bool
{
    $ownerKey = docs_normalize_outgoing_user_key((string) ($record['createdByKey'] ?? ''));
    if ($ownerKey === '') {
        return false;
    }

    foreach (docs_normalize_outgoing_user_keys($currentUserKeys) as $userKey) {
        if (hash_equals($ownerKey, $userKey)) {
            return true;
        }
    }

    return false;
}

function docs_normalize_outgoing_owner_label($value): string
{
    $label = sanitize_text_field((string) $value, 220);
    $label = preg_replace('/\s+/u', ' ', trim($label));
    if (!is_string($label) || $label === '') {
        return '';
    }

    return mb_strtolower($label, 'UTF-8');
}

function docs_outgoing_file_has_inherited_private_owner(array $file, array $record): bool
{
    if (!docs_is_outgoing_file_private($file)) {
        return false;
    }

    $ownerKey = docs_normalize_outgoing_user_key((string) ($file['uploadedByKey'] ?? ''));
    $uploaderLabel = docs_normalize_outgoing_owner_label($file['uploadedBy'] ?? '');
    if ($ownerKey === '' || $uploaderLabel === '') {
        return false;
    }

    $recordOwners = [
        [
            'key' => $record['createdByKey'] ?? '',
            'label' => $record['createdBy'] ?? '',
        ],
        [
            'key' => $record['updatedByKey'] ?? '',
            'label' => $record['updatedBy'] ?? '',
        ],
    ];

    foreach ($recordOwners as $recordOwner) {
        $recordKey = docs_normalize_outgoing_user_key((string) ($recordOwner['key'] ?? ''));
        if ($recordKey === '' || !hash_equals($ownerKey, $recordKey)) {
            continue;
        }

        $recordLabel = docs_normalize_outgoing_owner_label($recordOwner['label'] ?? '');
        if ($recordLabel !== '' && !hash_equals($uploaderLabel, $recordLabel)) {
            return true;
        }
    }

    return false;
}

function docs_ensure_private_outgoing_storage_guard(string $directory): void
{
    if ($directory === '' || !is_dir($directory)) {
        return;
    }

    $htaccessPath = rtrim($directory, '/\\') . '/.htaccess';
    if (!is_file($htaccessPath)) {
        @file_put_contents($htaccessPath, "Require all denied\nDeny from all\n", LOCK_EX);
        @chmod($htaccessPath, 0644);
    }

    $indexPath = rtrim($directory, '/\\') . '/index.html';
    if (!is_file($indexPath)) {
        @file_put_contents($indexPath, '', LOCK_EX);
        @chmod($indexPath, 0644);
    }
}

function docs_build_private_outgoing_file_url(string $folder, string $recordId, string $fileKey): string
{
    $params = [
        'action' => 'outgoing_file',
        'organization' => $folder,
        'record_id' => $recordId,
        'file' => $fileKey,
    ];

    return '/docs.php?' . http_build_query($params, '', '&', PHP_QUERY_RFC3986);
}

function docs_create_outgoing_private_file_access_key(): string
{
    try {
        return 'opf_' . bin2hex(random_bytes(16));
    } catch (Throwable $exception) {
        return 'opf_' . str_replace('.', '', uniqid('', true));
    }
}

function docs_outgoing_file_key_is_signed_access(array $file, string $fileKey): bool
{
    if (!docs_is_outgoing_file_private($file)) {
        return false;
    }

    $accessKey = sanitize_text_field((string) ($file['accessKey'] ?? ''), 200);
    if ($accessKey === '' || $fileKey === '') {
        return false;
    }

    return hash_equals($accessKey, $fileKey);
}

function docs_prepare_outgoing_record_response(array $record, bool $canManageOutgoing = false, $currentUserKeys = '', string $folder = ''): array
{
    $prepared = docs_prepare_outgoing_record($record);
    $recordId = sanitize_text_field((string) ($prepared['id'] ?? ''), 160);
    $canEditRecord = docs_outgoing_record_user_can_edit($prepared, $canManageOutgoing, $currentUserKeys);
    $visibleFiles = [];
    foreach (($prepared['files'] ?? []) as $file) {
        if (!is_array($file)) {
            continue;
        }

        if (docs_is_outgoing_file_private($file)) {
            $hasInheritedOwner = docs_outgoing_file_has_inherited_private_owner($file, $record);
            if (($hasInheritedOwner && !$canManageOutgoing) || !docs_outgoing_file_user_can_access($file, $canManageOutgoing, $currentUserKeys)) {
                $visibleFiles[] = array_filter([
                    'originalName' => 'Приватный файл',
                    'visibility' => 'private',
                    'accessDenied' => true,
                    'restricted' => true,
                    'uploadedBy' => sanitize_text_field((string) ($file['uploadedBy'] ?? ''), 220),
                    'uploadedAt' => sanitize_text_field((string) ($file['uploadedAt'] ?? ''), 80),
                    'size' => isset($file['size']) ? max(0, (int) $file['size']) : 0,
                ], static function ($item) {
                    return $item !== '' && $item !== 0;
                });
                continue;
            }

            $fileKey = sanitize_text_field((string) ($file['accessKey'] ?? ''), 200);
            if ($fileKey === '') {
                $fileKey = sanitize_text_field((string) ($file['storedName'] ?? ($file['originalName'] ?? '')), 255);
            }
            if ($folder !== '' && $recordId !== '' && $fileKey !== '') {
                $file['url'] = docs_build_private_outgoing_file_url($folder, $recordId, $fileKey);
            }
        }

        $visibleFiles[] = $file;
    }

    $prepared['files'] = $visibleFiles;
    $prepared['filesCount'] = count($visibleFiles);
    $fileNames = [];
    foreach ($visibleFiles as $file) {
        $fileName = sanitize_text_field((string) ($file['originalName'] ?? ($file['storedName'] ?? '')), 220);
        if ($fileName !== '') {
            $fileNames[] = $fileName;
        }
    }
    $prepared['filesLabel'] = !empty($fileNames) ? sanitize_text_field(implode(', ', $fileNames), 500) : '';
    $prepared['canEdit'] = $canEditRecord;
    $prepared['canAttach'] = true;
    $prepared['canDelete'] = $canManageOutgoing;

    return $prepared;
}

function docs_decode_outgoing_file_key_list($value): array
{
    if (is_string($value)) {
        $decoded = json_decode($value, true);
        if (is_array($decoded)) {
            $value = $decoded;
        } elseif (trim($value) !== '') {
            $value = [$value];
        } else {
            $value = [];
        }
    }

    if (!is_array($value)) {
        return [];
    }

    $keys = [];
    foreach ($value as $item) {
        if (is_array($item)) {
            foreach (docs_collect_outgoing_file_keys($item) as $key) {
                $keys[$key] = true;
            }
            continue;
        }

        $key = sanitize_text_field((string) $item, 500);
        if ($key !== '') {
            $keys[$key] = true;
        }
    }

    return array_keys($keys);
}

function docs_collect_outgoing_file_keys(array $file): array
{
    $candidates = [
        $file['accessKey'] ?? '',
        $file['storedName'] ?? '',
        $file['originalName'] ?? '',
        $file['url'] ?? '',
    ];

    $url = sanitize_text_field((string) ($file['url'] ?? ''), 500);
    if ($url !== '') {
        $path = parse_url($url, PHP_URL_PATH);
        if (is_string($path) && $path !== '') {
            $basename = rawurldecode((string) basename($path));
            if ($basename !== '') {
                $candidates[] = $basename;
            }
        }
    }

    $keys = [];
    foreach ($candidates as $candidate) {
        $key = sanitize_text_field((string) $candidate, 500);
        if ($key !== '') {
            $keys[$key] = true;
        }
    }

    return array_keys($keys);
}

function docs_outgoing_file_matches_keys(array $file, array $lookup): bool
{
    if (empty($lookup)) {
        return false;
    }

    foreach (docs_collect_outgoing_file_keys($file) as $key) {
        if (isset($lookup[$key])) {
            return true;
        }
    }

    return false;
}

function docs_get_outgoing_file_path_candidates(string $folder, array $file): array
{
    $paths = [];
    $storedName = sanitize_text_field((string) ($file['storedName'] ?? ''), 255);
    if ($storedName !== '') {
        $paths[] = docs_get_outgoing_files_root($folder, false, true) . '/' . $storedName;
        $paths[] = ensure_organization_directory($folder) . '/' . $storedName;
        $paths[] = ensure_organization_directory($folder) . '/Исходящие/' . $storedName;
    }

    $url = sanitize_text_field((string) ($file['url'] ?? ''), 500);
    if ($url !== '') {
        $path = parse_url($url, PHP_URL_PATH);
        if (is_string($path) && $path !== '') {
            $decodedPath = rawurldecode($path);
            $marker = '/documents/' . $folder . '/';
            $position = strpos($decodedPath, $marker);
            if ($position !== false) {
                $relative = substr($decodedPath, $position + strlen($marker));
                $relative = str_replace(['../', '..\\'], '', ltrim($relative, '/\\'));
                if ($relative !== '') {
                    $paths[] = ensure_organization_directory($folder) . '/' . $relative;
                }
            }
        }
    }

    return array_values(array_unique(array_filter($paths, static function ($path): bool {
        return is_string($path) && $path !== '';
    })));
}

function docs_find_private_outgoing_file_by_real_path(string $folder, string $realPath): ?array
{
    $folder = sanitize_folder_name($folder);
    $targetPath = realpath($realPath);
    if ($folder === '' || !is_string($targetPath) || $targetPath === '') {
        return null;
    }

    foreach (docs_load_outgoing_registry($folder) as $record) {
        if (!is_array($record) || empty($record['files']) || !is_array($record['files'])) {
            continue;
        }

        foreach ($record['files'] as $file) {
            if (!is_array($file) || !docs_is_outgoing_file_private($file)) {
                continue;
            }

            foreach (docs_get_outgoing_file_path_candidates($folder, $file) as $pathCandidate) {
                $candidateRealPath = realpath($pathCandidate);
                if (is_string($candidateRealPath) && $candidateRealPath !== '' && hash_equals($targetPath, $candidateRealPath)) {
                    return [
                        'record' => $record,
                        'file' => $file,
                    ];
                }
            }
        }
    }

    return null;
}

function docs_delete_outgoing_file_from_storage(string $folder, array $file): void
{
    foreach (docs_get_outgoing_file_path_candidates($folder, $file) as $path) {
        if (is_file($path)) {
            @unlink($path);
        }
    }
}

function docs_get_document_file_path_candidates(string $folder, array $file): array
{
    $paths = [];
    $storedName = sanitize_text_field((string) ($file['storedName'] ?? ''), 255);
    if ($storedName !== '') {
        $paths[] = ensure_organization_directory($folder) . '/' . $storedName;
    }

    $url = sanitize_text_field((string) ($file['url'] ?? ''), 500);
    if ($url !== '') {
        $path = parse_url($url, PHP_URL_PATH);
        if (is_string($path) && $path !== '') {
            $decodedPath = rawurldecode($path);
            $marker = '/documents/' . $folder . '/';
            $position = strpos($decodedPath, $marker);
            if ($position !== false) {
                $relative = substr($decodedPath, $position + strlen($marker));
                $relative = str_replace(['../', '..\\'], '', ltrim($relative, '/\\'));
                if ($relative !== '') {
                    $paths[] = ensure_organization_directory($folder) . '/' . $relative;
                }
            }
        }
    }

    return array_values(array_unique(array_filter($paths, static function ($path): bool {
        return is_string($path) && $path !== '';
    })));
}

function docs_delete_document_file_from_storage(string $folder, array $file): void
{
    foreach (docs_get_document_file_path_candidates($folder, $file) as $path) {
        if (is_file($path)) {
            @unlink($path);
        }
    }
}

function docs_resolve_unique_storage_target(string $directory, string $storedName): array
{
    $storedName = docs_sanitize_filename($storedName, 'attachment');
    $target = rtrim($directory, '/\\') . '/' . $storedName;
    $duplicateIndex = 2;

    while (is_file($target)) {
        $pathInfo = pathinfo($storedName);
        $extension = isset($pathInfo['extension']) && $pathInfo['extension'] !== '' ? '.' . $pathInfo['extension'] : '';
        $filename = $pathInfo['filename'] ?? $storedName;
        $storedName = $filename . '_' . $duplicateIndex . $extension;
        $target = rtrim($directory, '/\\') . '/' . $storedName;
        $duplicateIndex++;
    }

    return [$storedName, $target];
}

function docs_user_can_manage_outgoing_records(array $accessContext, ?array $sessionAuth = null): bool
{
    if (!is_array($sessionAuth)) {
        return false;
    }

    $role = docs_normalize_assignment_role((string) ($sessionAuth['role'] ?? ''));
    if ($role === 'admin') {
        return true;
    }

    $responsibleRole = docs_normalize_assignment_role((string) ($sessionAuth['responsibleRole'] ?? ''));

    return $responsibleRole === 'admin';
}

function docs_load_outgoing_registry(string $folder): array
{
    $file = get_outgoing_registry_path($folder);
    if (!is_file($file)) {
        return [];
    }

    $raw = @file_get_contents($file);
    if (!is_string($raw) || trim($raw) === '') {
        return [];
    }

    $decoded = json_decode($raw, true);
    if (!is_array($decoded)) {
        log_docs_event('Outgoing registry decode error', [
            'folder' => $folder,
            'path' => $file,
            'jsonError' => json_last_error_msg(),
        ]);
        return [];
    }

    $records = [];
    foreach ($decoded as $record) {
        if (is_array($record)) {
            $records[] = docs_prepare_outgoing_record($record);
        }
    }

    return $records;
}

function docs_save_outgoing_registry(string $folder, array $records): void
{
    $dir = ensure_organization_directory($folder);
    $file = $dir . '/' . OUTGOING_REGISTRY_FILENAME;
    $json = docs_encode_outgoing_registry_records($records);
    if ($json === null) {
        return;
    }

    @file_put_contents($file, $json . PHP_EOL, LOCK_EX);
    @chmod($file, 0644);
}

function docs_encode_outgoing_registry_records(array $records): ?string
{
    $prepared = [];
    foreach ($records as $record) {
        if (is_array($record)) {
            $prepared[] = docs_prepare_outgoing_record($record, 'outgoing', true);
        }
    }

    $json = json_encode(array_values($prepared), JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    if ($json === false) {
        return null;
    }

    return $json;
}

function docs_lock_outgoing_registry(string $folder): array
{
    $dir = ensure_organization_directory($folder);
    $file = $dir . '/' . OUTGOING_REGISTRY_FILENAME;
    $handle = @fopen($file, 'c+');
    if ($handle === false) {
        log_docs_event('Outgoing registry file open failed', [
            'file' => $file,
            'folder' => $folder,
        ]);
        return [null, []];
    }

    if (!flock($handle, LOCK_EX)) {
        log_docs_event('Outgoing registry file lock failed', [
            'file' => $file,
            'folder' => $folder,
        ]);
        fclose($handle);
        return [null, []];
    }

    rewind($handle);
    $raw = stream_get_contents($handle);
    if ($raw === false || trim($raw) === '') {
        $records = [];
    } else {
        $decoded = json_decode($raw, true);
        if (!is_array($decoded)) {
            log_docs_event('Outgoing registry decode error (locked)', [
                'file' => $file,
                'folder' => $folder,
                'jsonError' => json_last_error_msg(),
            ]);
            $records = [];
        } else {
            $records = [];
            foreach ($decoded as $record) {
                if (is_array($record)) {
                    $records[] = docs_prepare_outgoing_record($record, 'outgoing', true);
                }
            }
        }
    }

    register_shutdown_function(function () use ($handle) {
        if (is_resource($handle)) {
            flock($handle, LOCK_UN);
            fclose($handle);
        }
    });

    return [$handle, $records];
}

function docs_save_outgoing_registry_locked($handle, array $records): bool
{
    if (!is_resource($handle)) {
        return false;
    }

    $json = docs_encode_outgoing_registry_records($records);
    if ($json === null) {
        return false;
    }

    rewind($handle);
    if (!ftruncate($handle, 0)) {
        return false;
    }

    $written = fwrite($handle, $json . PHP_EOL);
    if ($written === false) {
        return false;
    }

    if (!fflush($handle)) {
        return false;
    }

    return true;
}

function docs_unlock_outgoing_registry($handle): void
{
    if (!is_resource($handle)) {
        return;
    }

    flock($handle, LOCK_UN);
    fclose($handle);
}

function docs_normalize_outgoing_number_for_unique(string $value): string
{
    $normalized = sanitize_text_field($value, 160);
    $normalized = preg_replace('/\s+/u', ' ', trim($normalized));
    if (!is_string($normalized) || $normalized === '') {
        return '';
    }

    return function_exists('mb_strtolower') ? mb_strtolower($normalized, 'UTF-8') : strtolower($normalized);
}

function docs_outgoing_number_exists(array $records, string $outgoingNumber, string $excludeId = ''): bool
{
    $normalizedNumber = docs_normalize_outgoing_number_for_unique($outgoingNumber);
    if ($normalizedNumber === '') {
        return false;
    }

    foreach ($records as $record) {
        if (!is_array($record)) {
            continue;
        }

        $recordId = sanitize_text_field((string) ($record['id'] ?? ''), 160);
        if ($excludeId !== '' && $recordId === $excludeId) {
            continue;
        }

        $candidate = docs_normalize_outgoing_number_for_unique((string) ($record['outgoingNumber'] ?? ''));
        if ($candidate !== '' && $candidate === $normalizedNumber) {
            return true;
        }
    }

    return false;
}

function docs_prepare_outgoing_records_response(array $records, bool $canManageOutgoing = false, $currentUserKeys = '', string $folder = ''): array
{
    $prepared = [];
    foreach ($records as $record) {
        if (is_array($record)) {
            $prepared[] = docs_prepare_outgoing_record_response($record, $canManageOutgoing, $currentUserKeys, $folder);
        }
    }

    return $prepared;
}

function docs_prepare_outgoing_edit_lock($value): array
{
    if (!is_array($value)) {
        return [];
    }

    $token = sanitize_text_field((string) ($value['token'] ?? ''), 120);
    $userLabel = sanitize_text_field((string) ($value['userLabel'] ?? ''), 220);
    $userKey = sanitize_text_field((string) ($value['userKey'] ?? ''), 200);
    $lockedAt = docs_normalize_datetime_iso(isset($value['lockedAt']) ? (string) $value['lockedAt'] : null) ?? '';
    $expiresAt = isset($value['expiresAt']) ? (int) $value['expiresAt'] : 0;

    if ($token === '' || $userKey === '' || $expiresAt <= 0) {
        return [];
    }

    return array_filter([
        'token' => $token,
        'userLabel' => $userLabel !== '' ? $userLabel : 'другой пользователь',
        'userKey' => $userKey,
        'lockedAt' => $lockedAt,
        'expiresAt' => $expiresAt,
    ], static function ($item) {
        return $item !== '';
    });
}

function docs_create_outgoing_edit_lock_token(): string
{
    try {
        return bin2hex(random_bytes(16));
    } catch (Throwable $exception) {
        return str_replace('.', '', uniqid('', true));
    }
}

function docs_outgoing_edit_lock_is_active(array $lock): bool
{
    $prepared = docs_prepare_outgoing_edit_lock($lock);

    return !empty($prepared) && (int) ($prepared['expiresAt'] ?? 0) > time();
}

function docs_outgoing_edit_lock_matches(array $lock, string $token): bool
{
    $prepared = docs_prepare_outgoing_edit_lock($lock);
    if ($token === '' || empty($prepared) || !docs_outgoing_edit_lock_is_active($prepared)) {
        return false;
    }

    return hash_equals((string) ($prepared['token'] ?? ''), $token);
}

function docs_acquire_outgoing_record_edit_lock(
    string $folder,
    string $recordId,
    string $userLabel,
    string $userKey,
    bool $canManageOutgoing = false,
    $currentUserKeys = ''
): array
{
    [$handle, $records] = docs_lock_outgoing_registry($folder);
    if ($handle === null) {
        return [
            'ok' => false,
            'status' => 503,
            'message' => 'Не удалось проверить блокировку записи. Повторите действие.',
            'reason' => 'outgoing_registry_lock_failed',
        ];
    }

    $recordIndex = null;
    foreach ($records as $index => $record) {
        if (is_array($record) && (string) ($record['id'] ?? '') === $recordId) {
            $recordIndex = $index;
            break;
        }
    }

    if ($recordIndex === null) {
        docs_unlock_outgoing_registry($handle);
        return [
            'ok' => false,
            'status' => 404,
            'message' => 'Запись исходящей корреспонденции не найдена.',
            'reason' => 'outgoing_record_not_found',
        ];
    }

    if (!docs_outgoing_record_user_can_edit($records[$recordIndex], $canManageOutgoing, $currentUserKeys)) {
        docs_unlock_outgoing_registry($handle);
        return [
            'ok' => false,
            'status' => 403,
            'message' => 'Редактировать можно только записи, которые вы добавили.',
            'reason' => 'outgoing_update_forbidden',
        ];
    }

    $existingLock = docs_prepare_outgoing_edit_lock($records[$recordIndex]['editLock'] ?? null);
    if (!empty($existingLock) && docs_outgoing_edit_lock_is_active($existingLock)) {
        $normalizedExistingUserKey = mb_strtolower(trim((string) ($existingLock['userKey'] ?? '')), 'UTF-8');
        $normalizedUserKey = mb_strtolower(trim($userKey), 'UTF-8');
        if ($normalizedExistingUserKey !== '' && $normalizedExistingUserKey === $normalizedUserKey) {
            $records[$recordIndex]['editLock']['expiresAt'] = time() + DOCS_OUTGOING_EDIT_LOCK_TTL;
            docs_save_outgoing_registry_locked($handle, $records);
            docs_unlock_outgoing_registry($handle);

            return [
                'ok' => true,
                'token' => (string) ($existingLock['token'] ?? ''),
                'expiresAt' => $records[$recordIndex]['editLock']['expiresAt'],
            ];
        }

        $lockedBy = sanitize_text_field((string) ($existingLock['userLabel'] ?? 'другой пользователь'), 220);
        docs_unlock_outgoing_registry($handle);

        return [
            'ok' => false,
            'status' => 409,
            'message' => 'Эту строку сейчас редактирует ' . $lockedBy . '. Подождите.',
            'reason' => 'outgoing_record_locked',
            'lockedBy' => $lockedBy,
        ];
    }

    $now = time();
    $token = docs_create_outgoing_edit_lock_token();
    $records[$recordIndex]['editLock'] = [
        'token' => $token,
        'userLabel' => $userLabel,
        'userKey' => $userKey,
        'lockedAt' => date('c', $now),
        'expiresAt' => $now + DOCS_OUTGOING_EDIT_LOCK_TTL,
    ];

    if (!docs_save_outgoing_registry_locked($handle, $records)) {
        docs_unlock_outgoing_registry($handle);
        return [
            'ok' => false,
            'status' => 500,
            'message' => 'Не удалось заблокировать запись для редактирования. Повторите действие.',
            'reason' => 'outgoing_registry_save_failed',
        ];
    }

    docs_unlock_outgoing_registry($handle);

    return [
        'ok' => true,
        'token' => $token,
        'expiresAt' => $records[$recordIndex]['editLock']['expiresAt'],
    ];
}

function docs_release_outgoing_record_edit_lock(string $folder, string $recordId, string $token): void
{
    if ($recordId === '' || $token === '') {
        return;
    }

    [$handle, $records] = docs_lock_outgoing_registry($folder);
    if ($handle === null) {
        return;
    }

    foreach ($records as $index => $record) {
        if (!is_array($record) || (string) ($record['id'] ?? '') !== $recordId) {
            continue;
        }

        if (docs_outgoing_edit_lock_matches($record['editLock'] ?? [], $token)) {
            unset($records[$index]['editLock']);
            docs_save_outgoing_registry_locked($handle, $records);
        }
        break;
    }

    docs_unlock_outgoing_registry($handle);
}

function docs_build_outgoing_number_sort_key(string $value): array
{
    $normalized = docs_normalize_outgoing_number_for_unique($value);
    if ($normalized === '') {
        return [
            'hasNumber' => false,
            'base' => 0,
            'hasSuffix' => false,
            'suffix' => 0,
            'text' => '',
        ];
    }

    if (preg_match('/^(\d+)(?:\D+(\d+))?/u', $normalized, $matches) === 1) {
        $suffix = isset($matches[2]) && $matches[2] !== '' ? (int) $matches[2] : 0;

        return [
            'hasNumber' => true,
            'base' => (int) $matches[1],
            'hasSuffix' => isset($matches[2]) && $matches[2] !== '',
            'suffix' => $suffix,
            'text' => $normalized,
        ];
    }

    return [
        'hasNumber' => false,
        'base' => 0,
        'hasSuffix' => false,
        'suffix' => 0,
        'text' => $normalized,
    ];
}

function docs_compare_outgoing_numbers_desc(string $left, string $right): int
{
    $leftKey = docs_build_outgoing_number_sort_key($left);
    $rightKey = docs_build_outgoing_number_sort_key($right);

    if ($leftKey['hasNumber'] !== $rightKey['hasNumber']) {
        return $leftKey['hasNumber'] ? -1 : 1;
    }

    if ($leftKey['hasNumber'] && $rightKey['hasNumber']) {
        $baseCompare = $rightKey['base'] <=> $leftKey['base'];
        if ($baseCompare !== 0) {
            return $baseCompare;
        }

        if ($leftKey['hasSuffix'] !== $rightKey['hasSuffix']) {
            return $leftKey['hasSuffix'] ? 1 : -1;
        }

        $suffixCompare = $leftKey['suffix'] <=> $rightKey['suffix'];
        if ($suffixCompare !== 0) {
            return $suffixCompare;
        }
    }

    return strcmp((string) $rightKey['text'], (string) $leftKey['text']);
}

function docs_sort_outgoing_records(array $records): array
{
    usort($records, static function (array $a, array $b): int {
        $numberCompare = docs_compare_outgoing_numbers_desc(
            (string) ($a['outgoingNumber'] ?? ''),
            (string) ($b['outgoingNumber'] ?? '')
        );
        if ($numberCompare !== 0) {
            return $numberCompare;
        }

        $dateA = !empty($a['registeredAt']) ? (string) $a['registeredAt'] : (string) ($a['sendingDate'] ?? '');
        $dateB = !empty($b['registeredAt']) ? (string) $b['registeredAt'] : (string) ($b['sendingDate'] ?? '');

        return strcmp($dateB, $dateA);
    });

    return $records;
}

function docs_sanitize_outgoing_record_payload(array $payload, ?array $existing, string $authorLabel, string $authorKey): array
{
    $now = date('c');
    $base = is_array($existing) ? $existing : [];
    $isNew = empty($base['id']);
    $outgoingNumberFields = ['registryNumber', 'registry_number', 'outgoingNumber', 'outgoing_number'];
    $sendingDateFields = ['registrationDate', 'registration_date', 'sendingDate'];
    $documentIndexFields = ['documentNumber', 'document_number', 'documentIndexNumber', 'document_index_number'];
    $addresseeFields = ['addressee', 'correspondent', 'sender', 'recipient', 'adresat', 'address'];
    $summaryFields = ['summary', 'content', 'description'];
    $executorFields = ['executor'];
    $noteFields = ['note'];

    $record = [
        'id' => $isNew ? docs_create_outgoing_record_id() : sanitize_text_field((string) $base['id'], 160),
        'source' => 'outgoing',
        'outgoingNumber' => docs_payload_first_scalar_text($payload, $outgoingNumberFields, 160),
        'sendingDate' => docs_payload_first_date($payload, $sendingDateFields),
        'documentIndexNumber' => docs_payload_first_scalar_text($payload, $documentIndexFields, 220),
        'documentType' => 'Исходящий',
        'addressee' => docs_payload_first_scalar_text($payload, $addresseeFields, 260),
        'summary' => docs_payload_first_scalar_text($payload, $summaryFields, 1000),
        'files' => docs_prepare_outgoing_files_payload($base['files'] ?? []),
        'executor' => docs_payload_first_scalar_text($payload, $executorFields, 220),
        'note' => docs_payload_first_scalar_text($payload, $noteFields, 500),
        'registeredBy' => $base['registeredBy'] ?? $authorLabel,
        'registeredAt' => $base['registeredAt'] ?? $now,
        'createdBy' => $base['createdBy'] ?? $authorLabel,
        'createdByKey' => $base['createdByKey'] ?? $authorKey,
        'createdAt' => $base['createdAt'] ?? $now,
        'updatedBy' => $authorLabel,
        'updatedByKey' => $authorKey,
        'updatedAt' => $now,
        'deleted' => false,
    ];

    if (!$isNew) {
        $fallbackFields = [
            'outgoingNumber' => [$outgoingNumberFields, 160],
            'sendingDate' => [$sendingDateFields, 0],
            'documentIndexNumber' => [$documentIndexFields, 220],
            'addressee' => [$addresseeFields, 260],
            'summary' => [$summaryFields, 1000],
            'executor' => [$executorFields, 220],
            'note' => [$noteFields, 500],
        ];

        foreach ($fallbackFields as $recordField => $config) {
            [$fields, $maxLength] = $config;
            if (!docs_payload_has_any_field($payload, $fields) && array_key_exists($recordField, $base)) {
                $record[$recordField] = $recordField === 'sendingDate'
                    ? sanitize_date_field((string) $base[$recordField])
                    : sanitize_text_field((string) $base[$recordField], (int) $maxLength);
            }
        }
    }

    return docs_prepare_outgoing_record($record);
}

function docs_validate_outgoing_record(array $record): ?string
{
    if (sanitize_text_field((string) ($record['outgoingNumber'] ?? ''), 160) === '') {
        return 'Поле «Исходящий номер» обязательно для заполнения.';
    }

    if (sanitize_date_field((string) ($record['sendingDate'] ?? '')) === '') {
        return 'Поле «Дата регистрации» обязательно для заполнения.';
    }

    if (sanitize_text_field((string) ($record['addressee'] ?? ''), 260) === '') {
        return 'Поле «Адресат» обязательно для заполнения.';
    }

    return null;
}

function docs_outgoing_validation_reason(string $message): string
{
    if (strpos($message, 'Исходящий номер') !== false) {
        return 'outgoing_number_required';
    }

    if (strpos($message, 'Дата регистрации') !== false) {
        return 'outgoing_sending_date_required';
    }

    if (strpos($message, 'Адресат') !== false) {
        return 'outgoing_addressee_required';
    }

    return 'outgoing_validation_failed';
}

function docs_get_outgoing_files_root(string $folder, bool $create = true, bool $private = false): string
{
    $dir = ensure_organization_directory($folder);
    if ($private) {
        $dir .= '/.outgoing-private';
    }
    if ($create && !is_dir($dir)) {
        @mkdir($dir, 0775, true);
    }
    if ($private && $create) {
        docs_ensure_private_outgoing_storage_guard($dir);
    }

    return $dir;
}

function docs_build_outgoing_file_public_path(string $folder, string $storedName): string
{
    return build_public_path($folder, $storedName);
}

function docs_normalize_outgoing_file_name(string $originalName, array $record, int $sequence, string $folder = ''): string
{
    return normalize_file_name($originalName, [
        'organization' => (string) ($record['organization'] ?? $folder),
        'registryNumber' => (string) ($record['outgoingNumber'] ?? $record['id'] ?? 'outgoing'),
        'registrationDate' => (string) ($record['sendingDate'] ?? ''),
        'createdAt' => (string) ($record['createdAt'] ?? ''),
    ], $sequence);
}

function docs_apply_outgoing_file_mutation(array &$record, string $folder, array $payload, ?array &$filesPendingDeletion = null): void
{
    if (!isset($record['files']) || !is_array($record['files'])) {
        $record['files'] = [];
    }

    $deleteKeys = docs_decode_outgoing_file_key_list($payload['filesToDelete'] ?? []);
    $hasRemainingPayload = array_key_exists('filesRemaining', $payload);
    $remainingKeys = docs_decode_outgoing_file_key_list($payload['filesRemaining'] ?? []);
    if (empty($deleteKeys) && !$hasRemainingPayload) {
        return;
    }

    $deleteLookup = array_fill_keys($deleteKeys, true);
    $remainingLookup = array_fill_keys($remainingKeys, true);
    $nextFiles = [];

    foreach ($record['files'] as $file) {
        if (!is_array($file)) {
            continue;
        }

        $shouldDelete = docs_outgoing_file_matches_keys($file, $deleteLookup);
        if ($hasRemainingPayload && !docs_outgoing_file_matches_keys($file, $remainingLookup)) {
            $shouldDelete = true;
        }

        if ($shouldDelete) {
            if (is_array($filesPendingDeletion)) {
                $filesPendingDeletion[] = $file;
            } else {
                docs_delete_outgoing_file_from_storage($folder, $file);
            }
            continue;
        }

        $nextFiles[] = $file;
    }

    $record['files'] = $nextFiles;
}

function docs_attach_uploaded_outgoing_files_to_record(array &$record, string $folder, string $errorPrefix, string $authorLabel = '', string $authorKey = '', bool $privateFiles = false): void
{
    if (empty($_FILES['attachments']) || !isset($_FILES['attachments']['name'])) {
        return;
    }

    if (!isset($record['files']) || !is_array($record['files'])) {
        $record['files'] = [];
    }

    if ($privateFiles && docs_normalize_outgoing_user_key($authorKey) === '') {
        respond_error('Приватные файлы нельзя сохранить без идентификатора пользователя.', 403, [
            'reason' => 'outgoing_private_owner_required',
        ]);
    }

    $dir = docs_get_outgoing_files_root($folder, true, $privateFiles);
    $names = $_FILES['attachments']['name'];
    $tmpNames = $_FILES['attachments']['tmp_name'];
    $errors = $_FILES['attachments']['error'];
    $sizes = $_FILES['attachments']['size'];
    $createdUploadTargets = [];

    $failUpload = static function (string $message, int $status = 500, array $details = []) use (&$createdUploadTargets): void {
        foreach ($createdUploadTargets as $createdUploadTarget) {
            if (is_string($createdUploadTarget) && $createdUploadTarget !== '' && is_file($createdUploadTarget)) {
                @unlink($createdUploadTarget);
            }
        }
        respond_error($message, $status, $details);
    };

    $storeFile = static function (string $originalName, string $tmpPath, int $size) use (&$record, $folder, $dir, &$createdUploadTargets, $failUpload, $errorPrefix, $authorLabel, $authorKey, $privateFiles): void {
        $validationError = docs_validate_uploaded_attachment($originalName, $size);
        if ($validationError !== null) {
            $failUpload($errorPrefix . ': ' . $validationError, 422, ['reason' => 'invalid_attachment']);
        }

        if (!is_uploaded_file($tmpPath)) {
            $failUpload(
                $errorPrefix . ': сервер не получил файл «' . $originalName . '». Повторите сохранение.',
                500,
                ['reason' => 'upload_tmp_missing']
            );
        }

        [$storedName, $target] = docs_resolve_unique_storage_target(
            $dir,
            docs_normalize_outgoing_file_name($originalName, $record, count($record['files']) + 1, $folder)
        );

        if (!move_uploaded_file($tmpPath, $target)) {
            $failUpload(
                $errorPrefix . ': не удалось сохранить файл «' . $originalName . '» в хранилище.',
                500,
                ['reason' => 'upload_move_failed']
            );
        }

        $createdUploadTargets[] = $target;
        $fileOptimization = docs_optimize_uploaded_attachment_file($target, $originalName, $size);
        $visibility = $privateFiles ? 'private' : 'public';
        $recordId = sanitize_text_field((string) ($record['id'] ?? ''), 160);
        $accessKey = $privateFiles ? docs_create_outgoing_private_file_access_key() : '';
        $record['files'][] = [
            'originalName' => $originalName,
            'storedName' => $storedName,
            'size' => (int) ($fileOptimization['size'] ?? ($size > 0 ? $size : (filesize($target) ?: 0))),
            'uploadedAt' => date('c'),
            'url' => $privateFiles && $recordId !== ''
                ? docs_build_private_outgoing_file_url($folder, $recordId, $accessKey)
                : docs_build_outgoing_file_public_path($folder, $storedName),
            'accessKey' => $accessKey,
            'visibility' => $visibility,
            'uploadedBy' => $authorLabel !== '' ? $authorLabel : sanitize_text_field((string) ($record['updatedBy'] ?? ($record['createdBy'] ?? '')), 220),
            'uploadedByKey' => $privateFiles ? $authorKey : ($authorKey !== '' ? $authorKey : sanitize_text_field((string) ($record['updatedByKey'] ?? ($record['createdByKey'] ?? '')), 200)),
        ];
    };

    if (is_array($names)) {
        $count = count($names);
        for ($i = 0; $i < $count; $i++) {
            $uploadError = isset($errors[$i]) ? (int) $errors[$i] : UPLOAD_ERR_NO_FILE;
            $uploadName = isset($names[$i]) ? docs_normalize_uploaded_filename((string) $names[$i]) : 'Файл';
            if ($uploadError !== UPLOAD_ERR_OK) {
                if ($uploadError === UPLOAD_ERR_NO_FILE && trim((string) ($names[$i] ?? '')) === '') {
                    continue;
                }
                $failUpload(
                    $errorPrefix . ': не удалось загрузить файл «' . $uploadName . '». Повторите сохранение.',
                    500,
                    ['reason' => 'upload_error', 'uploadError' => $uploadError]
                );
            }

            $storeFile($uploadName, (string) ($tmpNames[$i] ?? ''), (int) ($sizes[$i] ?? 0));
        }
        return;
    }

    $uploadError = (int) $errors;
    $uploadName = is_string($names) && trim($names) !== ''
        ? docs_normalize_uploaded_filename($names)
        : 'Файл';
    if ($uploadError === UPLOAD_ERR_NO_FILE && (!is_string($names) || trim($names) === '')) {
        return;
    }
    if ($uploadError !== UPLOAD_ERR_OK) {
        $failUpload(
            $errorPrefix . ': не удалось загрузить файл «' . $uploadName . '». Повторите сохранение.',
            500,
            ['reason' => 'upload_error', 'uploadError' => $uploadError]
        );
    }

    $storeFile($uploadName, (string) $tmpNames, (int) $sizes);
}

function docs_delete_outgoing_record_files(string $folder, array $record): void
{
    if (empty($record['files']) || !is_array($record['files'])) {
        return;
    }

    foreach ($record['files'] as $file) {
        if (!is_array($file)) {
            continue;
        }
        docs_delete_outgoing_file_from_storage($folder, $file);
    }
}

function docs_user_can_manage_orders(array $accessContext, ?array $sessionAuth = null): bool
{
    return docs_user_can_manage_outgoing_records($accessContext, $sessionAuth);
}

function docs_create_order_record_id(): string
{
    try {
        return 'order_' . bin2hex(random_bytes(8));
    } catch (Throwable $exception) {
        return 'order_' . str_replace('.', '', uniqid('', true));
    }
}

function docs_build_order_file_url(string $folder, string $recordId, string $fileKey): string
{
    $params = [
        'action' => 'orders_file',
        'organization' => $folder,
        'record_id' => $recordId,
        'file' => $fileKey,
    ];

    return '/docs.php?' . http_build_query($params, '', '&', PHP_QUERY_RFC3986);
}

function docs_prepare_order_files_payload($value): array
{
    if (!is_array($value)) {
        return [];
    }

    $files = [];
    foreach ($value as $file) {
        if (!is_array($file)) {
            continue;
        }

        $storedName = sanitize_text_field((string) ($file['storedName'] ?? ''), 255);
        $url = sanitize_text_field((string) ($file['url'] ?? ''), 500);
        if ($storedName === '' && $url === '') {
            continue;
        }

        $files[] = array_filter([
            'originalName' => sanitize_text_field((string) ($file['originalName'] ?? ($file['name'] ?? $storedName)), 255),
            'storedName' => $storedName,
            'size' => isset($file['size']) ? max(0, (int) $file['size']) : 0,
            'uploadedAt' => docs_normalize_datetime_iso(isset($file['uploadedAt']) ? (string) $file['uploadedAt'] : null) ?? '',
            'url' => $url,
            'uploadedBy' => sanitize_text_field((string) ($file['uploadedBy'] ?? ''), 220),
            'uploadedByKey' => sanitize_text_field((string) ($file['uploadedByKey'] ?? ''), 200),
        ], static function ($item) {
            return $item !== '' && $item !== 0;
        });
    }

    return $files;
}

function docs_prepare_order_record(array $record, bool $includeInternal = false): array
{
    $files = docs_prepare_order_files_payload($record['files'] ?? []);
    $fileNames = [];
    foreach ($files as $file) {
        $fileName = sanitize_text_field((string) ($file['originalName'] ?? ($file['storedName'] ?? '')), 220);
        if ($fileName !== '') {
            $fileNames[] = $fileName;
        }
    }

    $prepared = [
        'id' => sanitize_text_field((string) ($record['id'] ?? ''), 160),
        'source' => 'orders',
        'orderNumber' => sanitize_text_field((string) ($record['orderNumber'] ?? ''), 160),
        'orderDate' => sanitize_date_field(isset($record['orderDate']) ? (string) $record['orderDate'] : ''),
        'summary' => sanitize_text_field((string) ($record['summary'] ?? ''), 1000),
        'executor' => sanitize_text_field((string) ($record['executor'] ?? ''), 220),
        'files' => $files,
        'filesLabel' => !empty($fileNames)
            ? sanitize_text_field(implode(', ', $fileNames), 500)
            : sanitize_text_field((string) ($record['filesLabel'] ?? ''), 500),
        'filesCount' => count($files),
        'createdBy' => sanitize_text_field((string) ($record['createdBy'] ?? ''), 220),
        'createdByKey' => sanitize_text_field((string) ($record['createdByKey'] ?? ''), 200),
        'createdAt' => docs_normalize_datetime_iso(isset($record['createdAt']) ? (string) $record['createdAt'] : null) ?? '',
        'updatedBy' => sanitize_text_field((string) ($record['updatedBy'] ?? ''), 220),
        'updatedByKey' => sanitize_text_field((string) ($record['updatedByKey'] ?? ''), 200),
        'updatedAt' => docs_normalize_datetime_iso(isset($record['updatedAt']) ? (string) $record['updatedAt'] : null) ?? '',
        'deleted' => !empty($record['deleted']),
    ];

    if ($prepared['id'] === '') {
        $prepared['id'] = docs_create_order_record_id();
    }

    if ($includeInternal && isset($record['editLock']) && is_array($record['editLock'])) {
        $prepared['editLock'] = $record['editLock'];
    }

    return $prepared;
}

function docs_prepare_order_record_response(array $record, bool $canManageOrders, string $folder = ''): array
{
    $prepared = docs_prepare_order_record($record);
    $recordId = sanitize_text_field((string) ($prepared['id'] ?? ''), 160);
    $visibleFiles = [];

    foreach (($prepared['files'] ?? []) as $file) {
        if (!is_array($file)) {
            continue;
        }

        $fileKey = sanitize_text_field((string) ($file['storedName'] ?? ($file['originalName'] ?? '')), 255);
        if ($folder !== '' && $recordId !== '' && $fileKey !== '') {
            $file['url'] = docs_build_order_file_url($folder, $recordId, $fileKey);
        }
        $file['visibility'] = 'public';
        $visibleFiles[] = $file;
    }

    $prepared['files'] = $visibleFiles;
    $prepared['filesCount'] = count($visibleFiles);
    $fileNames = [];
    foreach ($visibleFiles as $file) {
        $fileName = sanitize_text_field((string) ($file['originalName'] ?? ($file['storedName'] ?? '')), 220);
        if ($fileName !== '') {
            $fileNames[] = $fileName;
        }
    }
    $prepared['filesLabel'] = !empty($fileNames) ? sanitize_text_field(implode(', ', $fileNames), 500) : '';
    $prepared['canEdit'] = $canManageOrders;
    $prepared['canAttach'] = $canManageOrders;
    $prepared['canDelete'] = $canManageOrders;

    return $prepared;
}

function docs_prepare_order_records_response(array $records, bool $canManageOrders, string $folder = ''): array
{
    $prepared = [];
    foreach ($records as $record) {
        if (is_array($record)) {
            $prepared[] = docs_prepare_order_record_response($record, $canManageOrders, $folder);
        }
    }

    return $prepared;
}

function docs_load_orders_registry(string $folder): array
{
    $file = get_orders_registry_path($folder);
    if (!is_file($file)) {
        return [];
    }

    $raw = @file_get_contents($file);
    if (!is_string($raw) || trim($raw) === '') {
        return [];
    }

    $decoded = json_decode($raw, true);
    if (!is_array($decoded)) {
        log_docs_event('Orders registry decode error', [
            'folder' => $folder,
            'path' => $file,
            'jsonError' => json_last_error_msg(),
        ]);
        return [];
    }

    $records = [];
    foreach ($decoded as $record) {
        if (is_array($record)) {
            $records[] = docs_prepare_order_record($record);
        }
    }

    return $records;
}

function docs_encode_orders_registry_records(array $records): ?string
{
    $prepared = [];
    foreach ($records as $record) {
        if (is_array($record)) {
            $prepared[] = docs_prepare_order_record($record, true);
        }
    }

    $json = json_encode(array_values($prepared), JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);

    return $json === false ? null : $json;
}

function docs_lock_orders_registry(string $folder): array
{
    $dir = ensure_organization_directory($folder);
    $file = $dir . '/' . ORDERS_REGISTRY_FILENAME;
    $handle = @fopen($file, 'c+');
    if ($handle === false) {
        log_docs_event('Orders registry file open failed', [
            'file' => $file,
            'folder' => $folder,
        ]);
        return [null, []];
    }

    if (!flock($handle, LOCK_EX)) {
        log_docs_event('Orders registry file lock failed', [
            'file' => $file,
            'folder' => $folder,
        ]);
        fclose($handle);
        return [null, []];
    }

    rewind($handle);
    $raw = stream_get_contents($handle);
    if ($raw === false || trim($raw) === '') {
        $records = [];
    } else {
        $decoded = json_decode($raw, true);
        if (!is_array($decoded)) {
            log_docs_event('Orders registry decode error (locked)', [
                'file' => $file,
                'folder' => $folder,
                'jsonError' => json_last_error_msg(),
            ]);
            $records = [];
        } else {
            $records = [];
            foreach ($decoded as $record) {
                if (is_array($record)) {
                    $records[] = docs_prepare_order_record($record, true);
                }
            }
        }
    }

    register_shutdown_function(function () use ($handle) {
        if (is_resource($handle)) {
            flock($handle, LOCK_UN);
            fclose($handle);
        }
    });

    return [$handle, $records];
}

function docs_save_orders_registry_locked($handle, array $records): bool
{
    if (!is_resource($handle)) {
        return false;
    }

    $json = docs_encode_orders_registry_records($records);
    if ($json === null) {
        return false;
    }

    rewind($handle);
    if (!ftruncate($handle, 0)) {
        return false;
    }

    $written = fwrite($handle, $json . PHP_EOL);
    if ($written === false) {
        return false;
    }

    return fflush($handle);
}

function docs_unlock_orders_registry($handle): void
{
    if (!is_resource($handle)) {
        return;
    }

    flock($handle, LOCK_UN);
    fclose($handle);
}

function docs_normalize_order_number_for_unique(string $value): string
{
    $normalized = sanitize_text_field($value, 160);
    $normalized = preg_replace('/\s+/u', ' ', trim($normalized));
    if (!is_string($normalized) || $normalized === '') {
        return '';
    }

    return function_exists('mb_strtolower') ? mb_strtolower($normalized, 'UTF-8') : strtolower($normalized);
}

function docs_order_number_exists(array $records, string $orderNumber, string $excludeId = ''): bool
{
    $normalizedNumber = docs_normalize_order_number_for_unique($orderNumber);
    if ($normalizedNumber === '') {
        return false;
    }

    foreach ($records as $record) {
        if (!is_array($record)) {
            continue;
        }

        $recordId = sanitize_text_field((string) ($record['id'] ?? ''), 160);
        if ($excludeId !== '' && $recordId === $excludeId) {
            continue;
        }

        $candidate = docs_normalize_order_number_for_unique((string) ($record['orderNumber'] ?? ''));
        if ($candidate !== '' && $candidate === $normalizedNumber) {
            return true;
        }
    }

    return false;
}

function docs_build_order_number_sort_key(string $value): array
{
    $normalized = docs_normalize_order_number_for_unique($value);
    if ($normalized === '') {
        return [
            'hasNumber' => false,
            'base' => 0,
            'suffix' => 0,
            'text' => '',
        ];
    }

    if (preg_match('/^(\d+)(?:\D+(\d+))?/u', $normalized, $matches) === 1) {
        return [
            'hasNumber' => true,
            'base' => (int) $matches[1],
            'suffix' => isset($matches[2]) && $matches[2] !== '' ? (int) $matches[2] : 0,
            'text' => $normalized,
        ];
    }

    return [
        'hasNumber' => false,
        'base' => 0,
        'suffix' => 0,
        'text' => $normalized,
    ];
}

function docs_compare_order_numbers_desc(string $left, string $right): int
{
    $leftKey = docs_build_order_number_sort_key($left);
    $rightKey = docs_build_order_number_sort_key($right);

    if ($leftKey['hasNumber'] !== $rightKey['hasNumber']) {
        return $leftKey['hasNumber'] ? -1 : 1;
    }

    if ($leftKey['hasNumber'] && $rightKey['hasNumber']) {
        $baseCompare = $rightKey['base'] <=> $leftKey['base'];
        if ($baseCompare !== 0) {
            return $baseCompare;
        }
        $suffixCompare = $rightKey['suffix'] <=> $leftKey['suffix'];
        if ($suffixCompare !== 0) {
            return $suffixCompare;
        }
    }

    return strcmp((string) $rightKey['text'], (string) $leftKey['text']);
}

function docs_sort_order_records(array $records): array
{
    usort($records, static function (array $a, array $b): int {
        $dateCompare = strcmp((string) ($b['orderDate'] ?? ''), (string) ($a['orderDate'] ?? ''));
        if ($dateCompare !== 0) {
            return $dateCompare;
        }

        return docs_compare_order_numbers_desc(
            (string) ($a['orderNumber'] ?? ''),
            (string) ($b['orderNumber'] ?? '')
        );
    });

    return $records;
}

function docs_sanitize_order_record_payload(array $payload, ?array $existing, string $authorLabel, string $authorKey): array
{
    $now = date('c');
    $base = is_array($existing) ? $existing : [];
    $isNew = empty($base['id']);
    $orderNumberFields = ['orderNumber', 'order_number', 'registryNumber', 'number'];
    $orderDateFields = ['orderDate', 'order_date', 'registrationDate', 'date'];
    $summaryFields = ['summary', 'content', 'description'];
    $executorFields = ['executor'];

    $record = [
        'id' => $isNew ? docs_create_order_record_id() : sanitize_text_field((string) $base['id'], 160),
        'source' => 'orders',
        'orderNumber' => docs_payload_first_scalar_text($payload, $orderNumberFields, 160),
        'orderDate' => docs_payload_first_date($payload, $orderDateFields),
        'summary' => docs_payload_first_scalar_text($payload, $summaryFields, 1000),
        'executor' => docs_payload_first_scalar_text($payload, $executorFields, 220),
        'files' => docs_prepare_order_files_payload($base['files'] ?? []),
        'createdBy' => $base['createdBy'] ?? $authorLabel,
        'createdByKey' => $base['createdByKey'] ?? $authorKey,
        'createdAt' => $base['createdAt'] ?? $now,
        'updatedBy' => $authorLabel,
        'updatedByKey' => $authorKey,
        'updatedAt' => $now,
        'deleted' => false,
    ];

    if (!$isNew) {
        $fallbackFields = [
            'orderNumber' => [$orderNumberFields, 160],
            'orderDate' => [$orderDateFields, 0],
            'summary' => [$summaryFields, 1000],
            'executor' => [$executorFields, 220],
        ];

        foreach ($fallbackFields as $recordField => $config) {
            [$fields, $maxLength] = $config;
            if (!docs_payload_has_any_field($payload, $fields) && array_key_exists($recordField, $base)) {
                $record[$recordField] = $recordField === 'orderDate'
                    ? sanitize_date_field((string) $base[$recordField])
                    : sanitize_text_field((string) $base[$recordField], (int) $maxLength);
            }
        }
    }

    return docs_prepare_order_record($record);
}

function docs_validate_order_record(array $record): ?string
{
    if (sanitize_text_field((string) ($record['orderNumber'] ?? ''), 160) === '') {
        return 'Поле «№ приказа» обязательно для заполнения.';
    }

    if (sanitize_date_field((string) ($record['orderDate'] ?? '')) === '') {
        return 'Поле «Дата» обязательно для заполнения.';
    }

    if (sanitize_text_field((string) ($record['summary'] ?? ''), 1000) === '') {
        return 'Поле «Краткое содержание» обязательно для заполнения.';
    }

    return null;
}

function docs_order_validation_reason(string $message): string
{
    if (strpos($message, '№ приказа') !== false) {
        return 'order_number_required';
    }

    if (strpos($message, 'Дата') !== false) {
        return 'order_date_required';
    }

    if (strpos($message, 'Краткое содержание') !== false) {
        return 'order_summary_required';
    }

    return 'order_validation_failed';
}

function docs_get_order_files_root(string $folder, bool $create = true): string
{
    $dir = ensure_organization_directory($folder) . '/Приказы';
    if ($create && !is_dir($dir)) {
        @mkdir($dir, 0775, true);
    }

    return $dir;
}

function docs_build_order_file_public_path(string $folder, string $storedName): string
{
    return build_public_path($folder, 'Приказы/' . $storedName);
}

function docs_normalize_order_file_name(string $originalName, array $record, int $sequence, string $folder = ''): string
{
    return normalize_file_name($originalName, [
        'organization' => (string) ($record['organization'] ?? $folder),
        'registryNumber' => (string) ($record['orderNumber'] ?? $record['id'] ?? 'order'),
        'registrationDate' => (string) ($record['orderDate'] ?? ''),
        'createdAt' => (string) ($record['createdAt'] ?? ''),
    ], $sequence);
}

function docs_get_order_file_path_candidates(string $folder, array $file): array
{
    $paths = [];
    $storedName = sanitize_text_field((string) ($file['storedName'] ?? ''), 255);
    if ($storedName !== '') {
        $paths[] = docs_get_order_files_root($folder, false) . '/' . $storedName;
        $paths[] = ensure_organization_directory($folder) . '/Приказы/' . $storedName;
    }

    $url = sanitize_text_field((string) ($file['url'] ?? ''), 500);
    if ($url !== '') {
        $path = parse_url($url, PHP_URL_PATH);
        if (is_string($path) && $path !== '') {
            $decodedPath = rawurldecode($path);
            $marker = '/documents/' . $folder . '/';
            $position = strpos($decodedPath, $marker);
            if ($position !== false) {
                $relative = substr($decodedPath, $position + strlen($marker));
                $relative = str_replace(['../', '..\\'], '', ltrim($relative, '/\\'));
                if ($relative !== '') {
                    $paths[] = ensure_organization_directory($folder) . '/' . $relative;
                }
            }
        }
    }

    return array_values(array_unique(array_filter($paths, static function ($path): bool {
        return is_string($path) && $path !== '';
    })));
}

function docs_delete_order_file_from_storage(string $folder, array $file): void
{
    foreach (docs_get_order_file_path_candidates($folder, $file) as $path) {
        if (is_file($path)) {
            @unlink($path);
        }
    }
}

function docs_delete_order_record_files(string $folder, array $record): void
{
    if (empty($record['files']) || !is_array($record['files'])) {
        return;
    }

    foreach ($record['files'] as $file) {
        if (is_array($file)) {
            docs_delete_order_file_from_storage($folder, $file);
        }
    }
}

function docs_apply_order_file_mutation(array &$record, string $folder, array $payload, ?array &$filesPendingDeletion = null): void
{
    if (!isset($record['files']) || !is_array($record['files'])) {
        $record['files'] = [];
    }

    $deleteKeys = docs_decode_outgoing_file_key_list($payload['filesToDelete'] ?? []);
    $hasRemainingPayload = array_key_exists('filesRemaining', $payload);
    $remainingKeys = docs_decode_outgoing_file_key_list($payload['filesRemaining'] ?? []);
    if (empty($deleteKeys) && !$hasRemainingPayload) {
        return;
    }

    $deleteLookup = array_fill_keys($deleteKeys, true);
    $remainingLookup = array_fill_keys($remainingKeys, true);
    $nextFiles = [];

    foreach ($record['files'] as $file) {
        if (!is_array($file)) {
            continue;
        }

        $shouldDelete = docs_outgoing_file_matches_keys($file, $deleteLookup);
        if ($hasRemainingPayload && !docs_outgoing_file_matches_keys($file, $remainingLookup)) {
            $shouldDelete = true;
        }

        if ($shouldDelete) {
            if (is_array($filesPendingDeletion)) {
                $filesPendingDeletion[] = $file;
            } else {
                docs_delete_order_file_from_storage($folder, $file);
            }
            continue;
        }

        $nextFiles[] = $file;
    }

    $record['files'] = $nextFiles;
}

function docs_attach_uploaded_order_files_to_record(array &$record, string $folder, string $errorPrefix, string $authorLabel = '', string $authorKey = ''): void
{
    if (empty($_FILES['attachments']) || !isset($_FILES['attachments']['name'])) {
        return;
    }

    if (!isset($record['files']) || !is_array($record['files'])) {
        $record['files'] = [];
    }

    $dir = docs_get_order_files_root($folder, true);
    $names = $_FILES['attachments']['name'];
    $tmpNames = $_FILES['attachments']['tmp_name'];
    $errors = $_FILES['attachments']['error'];
    $sizes = $_FILES['attachments']['size'];
    $createdUploadTargets = [];

    $failUpload = static function (string $message, int $status = 500, array $details = []) use (&$createdUploadTargets): void {
        foreach ($createdUploadTargets as $createdUploadTarget) {
            if (is_string($createdUploadTarget) && $createdUploadTarget !== '' && is_file($createdUploadTarget)) {
                @unlink($createdUploadTarget);
            }
        }
        respond_error($message, $status, $details);
    };

    $storeFile = static function (string $originalName, string $tmpPath, int $size) use (&$record, $folder, $dir, &$createdUploadTargets, $failUpload, $errorPrefix, $authorLabel, $authorKey): void {
        $validationError = docs_validate_uploaded_attachment($originalName, $size);
        if ($validationError !== null) {
            $failUpload($errorPrefix . ': ' . $validationError, 422, ['reason' => 'invalid_attachment']);
        }

        if (!is_uploaded_file($tmpPath)) {
            $failUpload(
                $errorPrefix . ': сервер не получил файл «' . $originalName . '». Повторите сохранение.',
                500,
                ['reason' => 'upload_tmp_missing']
            );
        }

        [$storedName, $target] = docs_resolve_unique_storage_target(
            $dir,
            docs_normalize_order_file_name($originalName, $record, count($record['files']) + 1, $folder)
        );

        if (!move_uploaded_file($tmpPath, $target)) {
            $failUpload(
                $errorPrefix . ': не удалось сохранить файл «' . $originalName . '» в хранилище.',
                500,
                ['reason' => 'upload_move_failed']
            );
        }

        $createdUploadTargets[] = $target;
        $fileOptimization = docs_optimize_uploaded_attachment_file($target, $originalName, $size);
        $recordId = sanitize_text_field((string) ($record['id'] ?? ''), 160);
        $record['files'][] = [
            'originalName' => $originalName,
            'storedName' => $storedName,
            'size' => (int) ($fileOptimization['size'] ?? ($size > 0 ? $size : (filesize($target) ?: 0))),
            'uploadedAt' => date('c'),
            'url' => $recordId !== ''
                ? docs_build_order_file_url($folder, $recordId, $storedName)
                : docs_build_order_file_public_path($folder, $storedName),
            'uploadedBy' => $authorLabel !== '' ? $authorLabel : sanitize_text_field((string) ($record['updatedBy'] ?? ($record['createdBy'] ?? '')), 220),
            'uploadedByKey' => $authorKey !== '' ? $authorKey : sanitize_text_field((string) ($record['updatedByKey'] ?? ($record['createdByKey'] ?? '')), 200),
        ];
    };

    if (is_array($names)) {
        $count = count($names);
        for ($i = 0; $i < $count; $i++) {
            $uploadError = isset($errors[$i]) ? (int) $errors[$i] : UPLOAD_ERR_NO_FILE;
            $uploadName = isset($names[$i]) ? docs_normalize_uploaded_filename((string) $names[$i]) : 'Файл';
            if ($uploadError !== UPLOAD_ERR_OK) {
                if ($uploadError === UPLOAD_ERR_NO_FILE && trim((string) ($names[$i] ?? '')) === '') {
                    continue;
                }
                $failUpload(
                    $errorPrefix . ': не удалось загрузить файл «' . $uploadName . '». Повторите сохранение.',
                    500,
                    ['reason' => 'upload_error', 'uploadError' => $uploadError]
                );
            }

            $storeFile($uploadName, (string) ($tmpNames[$i] ?? ''), (int) ($sizes[$i] ?? 0));
        }
        return;
    }

    $uploadError = (int) $errors;
    $uploadName = is_string($names) && trim($names) !== ''
        ? docs_normalize_uploaded_filename($names)
        : 'Файл';
    if ($uploadError === UPLOAD_ERR_NO_FILE && (!is_string($names) || trim($names) === '')) {
        return;
    }
    if ($uploadError !== UPLOAD_ERR_OK) {
        $failUpload(
            $errorPrefix . ': не удалось загрузить файл «' . $uploadName . '». Повторите сохранение.',
            500,
            ['reason' => 'upload_error', 'uploadError' => $uploadError]
        );
    }

    $storeFile($uploadName, (string) $tmpNames, (int) $sizes);
}

function docs_get_organization_template_filename(string $folder): string
{
    return $folder . '_template.docx';
}

function docs_get_organization_template_path(string $folder): string
{
    return DOCUMENTS_ROOT . '/' . $folder . '/' . docs_get_organization_template_filename($folder);
}

function docs_sanitize_admin_object_name(string $organization): string
{
    $sanitized = preg_replace('/[^a-zA-Z0-9А-Яа-яЁё._-]/u', '_', $organization);

    if (!is_string($sanitized) || $sanitized === '') {
        $sanitized = sanitize_folder_name($organization);
    }

    return $sanitized;
}

function ensure_organization_directory(string $folder): string
{
    $dir = DOCUMENTS_ROOT . '/' . $folder;
    if (!is_dir($dir)) {
        mkdir($dir, 0775, true);
    }

    return $dir;
}


function docs_get_responses_root(string $folder, bool $create = true): string
{
    $dir = ensure_organization_directory($folder) . '/Ответы';
    if ($create && !is_dir($dir)) {
        @mkdir($dir, 0775, true);
    }

    return $dir;
}

function docs_get_document_responses_dir(string $folder, string $documentId, bool $create = true): string
{
    $safeDocumentId = preg_replace('/[^A-Za-z0-9._-]/', '_', trim($documentId));
    if (!is_string($safeDocumentId) || $safeDocumentId === '') {
        $safeDocumentId = 'document';
    }

    $dir = docs_get_responses_root($folder, $create) . '/' . $safeDocumentId;
    if ($create && !is_dir($dir)) {
        @mkdir($dir, 0775, true);
    }

    return $dir;
}

function docs_delete_directory_recursive(string $path): void
{
    if ($path === '' || !file_exists($path)) {
        return;
    }

    if (is_file($path) || is_link($path)) {
        @unlink($path);
        return;
    }

    $items = @scandir($path);
    if (is_array($items)) {
        foreach ($items as $item) {
            if ($item === '.' || $item === '..') {
                continue;
            }
            docs_delete_directory_recursive($path . '/' . $item);
        }
    }

    @rmdir($path);
}

function docs_resolve_current_user_key(array $requestContext, ?array $sessionAuth = null): string
{
    $user = isset($requestContext['user']) && is_array($requestContext['user']) ? $requestContext['user'] : [];
    $candidates = [
        ['id', $user['id'] ?? ($requestContext['primaryId'] ?? null)],
        ['login', $user['login'] ?? ($sessionAuth['login'] ?? null)],
        ['username', $user['username'] ?? null],
        ['name', $user['fullName'] ?? ($sessionAuth['fullName'] ?? null)],
    ];

    foreach ($candidates as [$prefix, $value]) {
        if ($value === null) {
            continue;
        }
        $normalized = trim((string) $value);
        if ($normalized !== '') {
            return $prefix . ':' . mb_strtolower($normalized, 'UTF-8');
        }
    }

    return '';
}

function docs_resolve_outgoing_private_user_key(array $requestContext, ?array $sessionAuth = null): string
{
    if (is_array($sessionAuth)) {
        $sessionCandidates = [
            ['login', $sessionAuth['login'] ?? null],
            ['id', $sessionAuth['telegramId'] ?? ($sessionAuth['telegram'] ?? ($sessionAuth['chatId'] ?? null))],
            ['name', $sessionAuth['fullName'] ?? null],
        ];

        foreach ($sessionCandidates as [$prefix, $value]) {
            if ($value === null) {
                continue;
            }
            $normalized = trim((string) $value);
            if ($normalized !== '') {
                return $prefix . ':' . mb_strtolower($normalized, 'UTF-8');
            }
        }
    }

    return docs_resolve_current_user_key($requestContext, null);
}

function docs_resolve_outgoing_private_user_keys(array $requestContext, ?array $sessionAuth = null): array
{
    $keys = [];
    $pushKey = static function (string $prefix, $value) use (&$keys): void {
        if ($value === null) {
            return;
        }
        $normalized = trim((string) $value);
        if ($normalized !== '') {
            $keys[] = $prefix . ':' . mb_strtolower($normalized, 'UTF-8');
        }
    };

    if (is_array($sessionAuth)) {
        $pushKey('login', $sessionAuth['login'] ?? null);
        $pushKey('id', $sessionAuth['telegramId'] ?? null);
        $pushKey('id', $sessionAuth['telegram'] ?? null);
        $pushKey('id', $sessionAuth['chatId'] ?? null);
        $pushKey('name', $sessionAuth['fullName'] ?? null);
    }

    $user = isset($requestContext['user']) && is_array($requestContext['user']) ? $requestContext['user'] : [];
    $pushKey('id', $user['id'] ?? ($requestContext['primaryId'] ?? null));
    $pushKey('username', $user['username'] ?? null);
    $pushKey('name', $user['fullName'] ?? null);
    $pushKey('login', $user['login'] ?? null);

    $primaryKey = docs_resolve_outgoing_private_user_key($requestContext, $sessionAuth);
    if ($primaryKey !== '') {
        $keys[] = $primaryKey;
    }

    return docs_normalize_outgoing_user_keys($keys);
}

function docs_resolve_site_user_identity_for_responses(string $folder, array $requestContext, ?array $sessionAuth = null): array
{
    $telegramUserId = normalize_identifier_value($requestContext['raw']['telegram_user_id'] ?? '');
    if ($telegramUserId === '') {
        $telegramUserId = normalize_identifier_value($requestContext['primaryId'] ?? '');
    }
    if ($telegramUserId === '' && isset($requestContext['user']) && is_array($requestContext['user'])) {
        $telegramUserId = normalize_identifier_value($requestContext['user']['id'] ?? '');
    }

    if ($telegramUserId !== '') {
        $settings = load_admin_settings($folder);
        $searchPools = [];
        if (isset($settings['block3']) && is_array($settings['block3'])) {
            $searchPools[] = $settings['block3'];
        }
        if (isset($settings['responsibles']) && is_array($settings['responsibles'])) {
            $searchPools[] = $settings['responsibles'];
        }

        foreach ($searchPools as $pool) {
            foreach ($pool as $entry) {
                if (!is_array($entry)) {
                    continue;
                }

                $entryTelegramId = normalize_identifier_value($entry['telegram_user_id'] ?? ($entry['telegram'] ?? ($entry['chatId'] ?? '')));
                if ($entryTelegramId === '' || $entryTelegramId !== $telegramUserId) {
                    continue;
                }

                $label = sanitize_text_field((string) ($entry['subordinate'] ?? ($entry['responsible'] ?? ($entry['name'] ?? ''))), 200);
                if ($label === '') {
                    continue;
                }

                return [
                    'label' => $label,
                    'key' => 'name:' . mb_strtolower($label, 'UTF-8'),
                    'source' => 'settingsdocs',
                ];
            }
        }
    }

    $fallbackLabel = docs_resolve_current_user_label($requestContext, $sessionAuth);
    if ($fallbackLabel === '') {
        $fallbackLabel = 'Пользователь';
    }
    $fallbackKey = docs_resolve_current_user_key($requestContext, $sessionAuth);

    return [
        'label' => $fallbackLabel,
        'key' => $fallbackKey !== '' ? $fallbackKey : ('name:' . mb_strtolower($fallbackLabel, 'UTF-8')),
        'source' => 'fallback',
    ];
}

function docs_is_current_user_response_owner(array $response, string $folder, array $requestContext, ?array $sessionAuth = null): bool
{
    $siteIdentity = docs_resolve_site_user_identity_for_responses($folder, $requestContext, $sessionAuth);
    $siteKeyNormalized = mb_strtolower(trim((string) ($siteIdentity['key'] ?? '')), 'UTF-8');
    $siteLabelNormalized = docs_normalize_name_candidate_value($siteIdentity['label'] ?? '');

    $ownerKey = sanitize_text_field((string) ($response['uploadedByKey'] ?? ''), 200);
    $ownerKeyNormalized = $ownerKey !== '' ? mb_strtolower(trim($ownerKey), 'UTF-8') : '';
    if ($ownerKeyNormalized !== '' && $siteKeyNormalized !== '' && $ownerKeyNormalized === $siteKeyNormalized) {
        return true;
    }

    $ownerName = docs_normalize_name_candidate_value($response['uploadedBy'] ?? '');
    return $ownerName !== '' && $siteLabelNormalized !== '' && $ownerName === $siteLabelNormalized;
}

function docs_resolve_current_user_label(array $requestContext, ?array $sessionAuth = null): string
{
    $user = isset($requestContext['user']) && is_array($requestContext['user']) ? $requestContext['user'] : [];
    $candidates = [
        $user['fullName'] ?? null,
        $sessionAuth['fullName'] ?? null,
        $user['login'] ?? null,
        $sessionAuth['login'] ?? null,
        $user['username'] ?? null,
        $requestContext['primaryId'] ?? null,
    ];

    foreach ($candidates as $candidate) {
        $value = trim((string) ($candidate ?? ''));
        if ($value !== '') {
            return sanitize_text_field($value, 200);
        }
    }

    return 'Пользователь';
}

function docs_resolve_response_upload_author(string $folder, array $requestContext, ?array $sessionAuth = null): array
{
    $fallbackLabel = docs_resolve_current_user_label($requestContext, $sessionAuth);
    $fallbackKey = docs_resolve_current_user_key($requestContext, $sessionAuth);

    $postLabel = sanitize_text_field((string) ($_POST['uploadedBy'] ?? ''), 200);
    if ($postLabel !== '') {
        $postKey = sanitize_text_field((string) ($_POST['uploadedByKey'] ?? ''), 200);

        return [
            'label' => $postLabel,
            'key' => $postKey !== '' ? $postKey : ('name:' . mb_strtolower($postLabel, 'UTF-8')),
            'source' => 'post',
            'telegramUserId' => '',
            'matchedResponsible' => null,
        ];
    }

    $telegramUserId = normalize_identifier_value($requestContext['raw']['telegram_user_id'] ?? '');
    if ($telegramUserId === '') {
        $telegramUserId = normalize_identifier_value($requestContext['primaryId'] ?? '');
    }
    if ($telegramUserId === '' && isset($requestContext['user']) && is_array($requestContext['user'])) {
        $telegramUserId = normalize_identifier_value($requestContext['user']['id'] ?? '');
    }

    if ($telegramUserId !== '') {
        $settings = load_admin_settings($folder);
        $searchPools = [];
        if (isset($settings['block3']) && is_array($settings['block3'])) {
            $searchPools[] = $settings['block3'];
        }
        if (isset($settings['responsibles']) && is_array($settings['responsibles'])) {
            $searchPools[] = $settings['responsibles'];
        }

        foreach ($searchPools as $pool) {
            foreach ($pool as $entry) {
                if (!is_array($entry)) {
                    continue;
                }

                $entryTelegramId = normalize_identifier_value($entry['telegram_user_id'] ?? ($entry['telegram'] ?? ($entry['chatId'] ?? '')));
                if ($entryTelegramId === '' || $entryTelegramId !== $telegramUserId) {
                    continue;
                }

                $responsible = sanitize_text_field((string) ($entry['subordinate'] ?? ($entry['responsible'] ?? ($entry['name'] ?? ''))), 200);
                if ($responsible === '') {
                    continue;
                }

                return [
                    'label' => $responsible,
                    'key' => 'name:' . mb_strtolower($responsible, 'UTF-8'),
                    'source' => 'settingsdocs',
                    'telegramUserId' => $telegramUserId,
                    'matchedResponsible' => $responsible,
                ];
            }
        }
    }

    if ($fallbackLabel === '') {
        $fallbackLabel = 'Пользователь';
    }

    return [
        'label' => $fallbackLabel,
        'key' => $fallbackKey !== '' ? $fallbackKey : ('name:' . mb_strtolower($fallbackLabel, 'UTF-8')),
        'source' => 'fallback',
        'telegramUserId' => $telegramUserId,
        'matchedResponsible' => null,
    ];
}

function docs_normalize_response_file_name(string $original, array $record, int $sequence = 1): string
{
    $base = normalize_file_name($original, $record, $sequence);
    return 'answer.' . $base;
}

function docs_is_text_response_file(string $fileName): bool
{
    $extension = mb_strtolower((string) pathinfo($fileName, PATHINFO_EXTENSION), 'UTF-8');
    return $extension === 'txt';
}

function docs_extract_pure_response_text(string $rawText): string
{
    $normalized = str_replace("\r\n", "\n", str_replace("\r", "\n", $rawText));
    $normalized = preg_replace('/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/u', '', $normalized) ?? '';
    if ($normalized === '') {
        return '';
    }

    $trimmed = trim($normalized);
    if ($trimmed === '') {
        return '';
    }

    $parts = preg_split('/\nОтвет к задаче\s*\n/u', "\n" . $trimmed, -1, PREG_SPLIT_NO_EMPTY);
    $candidate = is_array($parts) && !empty($parts)
        ? (string) $parts[count($parts) - 1]
        : $trimmed;

    $candidate = preg_replace('/^\s*Ответ к задаче\s*\n/u', '', $candidate) ?? $candidate;
    $candidate = preg_replace('/^\s*Дата:\s*.*\n/u', '', $candidate) ?? $candidate;
    $candidate = preg_replace('/^\s*Пользователь:\s*.*\n/u', '', $candidate) ?? $candidate;
    $candidate = preg_replace('/^\s*-{3,}\s*\n/u', '', $candidate) ?? $candidate;
    $candidate = trim((string) $candidate);

    return $candidate !== '' ? $candidate : $trimmed;
}

function docs_read_response_text_content(string $folder, string $documentId, string $storedName): string
{
    if ($documentId === '' || $storedName === '' || !docs_is_text_response_file($storedName)) {
        return '';
    }

    $path = docs_get_document_responses_dir($folder, $documentId, false) . '/' . $storedName;
    if (!is_file($path)) {
        return '';
    }

    $maxBytes = 262144;
    $raw = @file_get_contents($path, false, null, 0, $maxBytes);
    if (!is_string($raw) || $raw === '') {
        return '';
    }

    $clean = docs_extract_pure_response_text($raw);
    if ($clean === '') {
        return '';
    }

    if (mb_strlen($clean, 'UTF-8') > 12000) {
        $clean = mb_substr($clean, 0, 12000, 'UTF-8');
    }

    return $clean;
}

function docs_prepare_responses_for_record(array &$record, string $folder): void
{
    if (!isset($record['responses']) || !is_array($record['responses'])) {
        $record['responses'] = [];
        return;
    }

    $documentId = isset($record['id']) ? trim((string) $record['id']) : '';
    $prepared = [];

    foreach ($record['responses'] as $response) {
        if (!is_array($response)) {
            continue;
        }

        $storedName = isset($response['storedName']) ? sanitize_text_field((string) $response['storedName'], 255) : '';
        if ($storedName === '') {
            continue;
        }

        $item = [
            'originalName' => sanitize_text_field((string) ($response['originalName'] ?? $storedName), 255),
            'storedName' => $storedName,
            'size' => isset($response['size']) ? (int) $response['size'] : 0,
            'uploadedAt' => isset($response['uploadedAt']) ? (string) $response['uploadedAt'] : '',
            'uploadedBy' => sanitize_text_field((string) ($response['uploadedBy'] ?? ''), 200),
            'uploadedByKey' => sanitize_text_field((string) ($response['uploadedByKey'] ?? ''), 200),
            'uploadedByName' => sanitize_text_field((string) ($response['uploadedByName'] ?? ($response['uploadedBy'] ?? '')), 200),
            'uploadedByTelegram' => sanitize_text_field((string) ($response['uploadedByTelegram'] ?? ''), 120),
            'uploadedById' => sanitize_text_field((string) ($response['uploadedById'] ?? ''), 120),
            'uploadedByLogin' => sanitize_text_field((string) ($response['uploadedByLogin'] ?? ''), 120),
        ];

        $archive = docs_prepare_archived_attachment_meta($response['archive'] ?? null);
        if (!empty($archive)) {
            $item['archive'] = $archive;
            $item['url'] = docs_build_archived_attachment_url($folder, $archive, $item['originalName']);
        }

        if ($documentId !== '') {
            if (empty($item['url'])) {
                $item['url'] = build_public_path($folder, 'Ответы/' . $documentId . '/' . $storedName);
            }
        }
        if (docs_is_text_response_file($storedName)) {
            $item['isTextFile'] = true;
            if (empty($archive)) {
                $item['textContent'] = docs_read_response_text_content($folder, $documentId, $storedName);
            }
        }

        $prepared[] = $item;
    }

    $record['responses'] = array_values($prepared);
}

function docs_get_mini_app_user_log_path(string $folder): string
{
    return DOCUMENTS_ROOT . '/' . $folder . '/' . MINI_APP_USER_LOG_FILENAME;
}

function docs_load_mini_app_user_log(string $folder): array
{
    $path = docs_get_mini_app_user_log_path($folder);
    $entries = [];
    $updatedAt = null;

    if (is_file($path)) {
        $raw = @file_get_contents($path);
        if (is_string($raw) && trim($raw) !== '') {
            $decoded = json_decode($raw, true);
            if (is_array($decoded)) {
                foreach ($decoded as $entry) {
                    if (!is_array($entry)) {
                        continue;
                    }

                    $id = normalize_identifier_value($entry['id'] ?? '');
                    if ($id === '') {
                        continue;
                    }

                    $entries[] = array_filter([
                        'id' => $id,
                        'fullName' => sanitize_text_field($entry['fullName'] ?? '', 200),
                        'username' => sanitize_text_field($entry['username'] ?? '', 100),
                        'lastSeen' => isset($entry['lastSeen']) ? (string) $entry['lastSeen'] : '',
                    ], static function ($value) {
                        return $value !== '';
                    });
                }
            }
        }

        $mtime = @filemtime($path);
        if ($mtime !== false) {
            $updatedAt = date('c', $mtime);
        }
    }

    return [
        'entries' => $entries,
        'updatedAt' => $updatedAt,
        'path' => $path,
    ];
}

function docs_write_mini_app_user_log(string $folder, array $entries): void
{
    $directory = ensure_organization_directory($folder);
    $path = rtrim($directory, '/\\') . '/' . MINI_APP_USER_LOG_FILENAME;
    $encoded = json_encode($entries, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_PRETTY_PRINT);
    if ($encoded === false) {
        return;
    }

    @file_put_contents($path, $encoded . PHP_EOL, LOCK_EX);
    @chmod($path, 0644);
}

function docs_register_mini_app_user_visit(string $organizationName, string $folder, array $requestContext): void
{
    $userId = '';
    $fullName = '';
    $username = '';

    if (isset($requestContext['user']) && is_array($requestContext['user'])) {
        $userId = normalize_identifier_value($requestContext['user']['id'] ?? '');
        $fullName = sanitize_text_field($requestContext['user']['fullName'] ?? '', 200);
        $firstName = sanitize_text_field($requestContext['user']['firstName'] ?? '', 120);
        $lastName = sanitize_text_field($requestContext['user']['lastName'] ?? '', 120);
        if ($fullName === '' && ($firstName !== '' || $lastName !== '')) {
            $parts = array_filter([$lastName, $firstName], static function ($value): bool {
                return $value !== '';
            });
            $fullName = implode(' ', $parts);
        }
        $username = sanitize_text_field($requestContext['user']['username'] ?? '', 120);
    }

    if ($userId === '' && !empty($requestContext['primaryId'])) {
        $userId = normalize_identifier_value((string) $requestContext['primaryId']);
    }

    if ($fullName === '' && isset($requestContext['raw']['telegram_full_name'])) {
        $fullName = sanitize_text_field((string) $requestContext['raw']['telegram_full_name'], 200);
    }

    if ($username === '' && isset($requestContext['raw']['telegram_username'])) {
        $username = sanitize_text_field((string) $requestContext['raw']['telegram_username'], 120);
    }

    if ($userId === '') {
        return;
    }

    if ($fullName === '') {
        $fullName = 'Без имени';
    }

    $log = docs_load_mini_app_user_log($folder);
    $entries = [];
    foreach ($log['entries'] as $entry) {
        if (!is_array($entry)) {
            continue;
        }

        $entryId = normalize_identifier_value($entry['id'] ?? '');
        if ($entryId === '') {
            continue;
        }

        $existing = ['id' => $entryId];
        $existingName = sanitize_text_field($entry['fullName'] ?? '', 200);
        if ($existingName !== '') {
            $existing['fullName'] = $existingName;
        }
        $existingUsername = sanitize_text_field($entry['username'] ?? '', 120);
        if ($existingUsername !== '') {
            $existing['username'] = ltrim($existingUsername, '@');
        }
        if (!empty($entry['lastSeen'])) {
            $existing['lastSeen'] = (string) $entry['lastSeen'];
        }

        $entries[$entryId] = $existing;
    }

    $now = date('c');
    $current = $entries[$userId] ?? ['id' => $userId];
    if ($fullName !== '' && $fullName !== 'Без имени') {
        $current['fullName'] = $fullName;
    } elseif (empty($current['fullName'])) {
        $current['fullName'] = 'Без имени';
    }
    if ($username !== '') {
        $current['username'] = ltrim($username, '@');
    } elseif (isset($current['username']) && $current['username'] === '') {
        unset($current['username']);
    }
    $current['lastSeen'] = $now;

    $entries[$userId] = $current;

    $sorted = array_values($entries);
    usort($sorted, static function (array $a, array $b): int {
        $nameA = mb_strtolower((string) ($a['fullName'] ?? ''), 'UTF-8');
        $nameB = mb_strtolower((string) ($b['fullName'] ?? ''), 'UTF-8');

        if ($nameA === $nameB) {
            return strcmp((string) ($a['id'] ?? ''), (string) ($b['id'] ?? ''));
        }

        if ($nameA === '') {
            return 1;
        }

        if ($nameB === '') {
            return -1;
        }

        return strcmp($nameA, $nameB);
    });

    docs_write_mini_app_user_log($folder, $sorted);

    log_docs_event('Mini app user visit recorded', [
        'organization' => $organizationName,
        'folder' => $folder,
        'userId' => $userId,
        'fullName' => $fullName,
        'username' => $username,
        'entriesCount' => count($sorted),
    ]);
}

function docs_collect_view_candidate_keys(array $requestContext, array $details): array
{
    $idCandidates = [];
    $nameCandidates = [];

    $addIdCandidate = static function ($value) use (&$idCandidates): void {
        $normalized = docs_normalize_identifier_candidate_value($value ?? '');
        if ($normalized !== '') {
            $idCandidates[$normalized] = true;
        }
    };

    $addNameCandidate = static function ($value) use (&$nameCandidates): void {
        $normalized = docs_normalize_name_candidate_value($value ?? '');
        if ($normalized !== '') {
            $nameCandidates[$normalized] = true;
        }
    };

    $addIdCandidate($requestContext['primaryId'] ?? '');
    $addNameCandidate($requestContext['primaryId'] ?? '');
    $addIdCandidate($requestContext['identity'] ?? '');

    if (isset($requestContext['user']) && is_array($requestContext['user'])) {
        $addIdCandidate($requestContext['user']['id'] ?? '');
        $addIdCandidate($requestContext['user']['username'] ?? '');
        $addNameCandidate($requestContext['user']['fullName'] ?? '');
        $addNameCandidate($requestContext['user']['firstName'] ?? '');
        $addNameCandidate($requestContext['user']['lastName'] ?? '');
    }

    if (isset($requestContext['raw']) && is_array($requestContext['raw'])) {
        $addIdCandidate($requestContext['raw']['telegram_user_id'] ?? '');
        $addIdCandidate($requestContext['raw']['telegram_username'] ?? '');
        $addIdCandidate($requestContext['raw']['telegram_chat_id'] ?? '');
        $addNameCandidate($requestContext['raw']['telegram_full_name'] ?? '');
    }

    $addIdCandidate($details['assigneeId'] ?? '');
    $addIdCandidate($details['viewerId'] ?? '');
    $addIdCandidate($details['id'] ?? '');
    $addIdCandidate($details['userId'] ?? '');
    $addIdCandidate($details['user_id'] ?? '');
    $addIdCandidate($details['telegram'] ?? '');
    $addIdCandidate($details['telegramId'] ?? '');
    $addIdCandidate($details['telegram_id'] ?? '');
    $addIdCandidate($details['telegram_user_id'] ?? '');
    $addIdCandidate($details['chatId'] ?? '');
    $addIdCandidate($details['chat_id'] ?? '');
    $addIdCandidate($details['responsibleNumber'] ?? '');
    $addIdCandidate($details['responsible_number'] ?? '');
    $addIdCandidate($details['login'] ?? '');
    $addIdCandidate($details['username'] ?? '');
    $addIdCandidate($details['email'] ?? '');
    $addNameCandidate($details['viewerName'] ?? '');
    $addNameCandidate($details['name'] ?? '');
    $addNameCandidate($details['fullName'] ?? '');
    $addNameCandidate($details['fio'] ?? '');
    $addNameCandidate($details['displayName'] ?? '');

    $keys = [];

    $assigneeKeyCandidate = $details['assigneeKey'] ?? '';
    if (is_string($assigneeKeyCandidate)) {
        $assigneeKeyCandidate = trim($assigneeKeyCandidate);
        if ($assigneeKeyCandidate !== '') {
            $normalizedAssigneeKey = mb_strtolower($assigneeKeyCandidate, 'UTF-8');
            $keys[] = $normalizedAssigneeKey;
        }
    }

    foreach (array_keys($idCandidates) as $candidate) {
        $keys[] = 'id::' . $candidate;
    }

    foreach (array_keys($nameCandidates) as $candidate) {
        $keys[] = 'name::' . $candidate;
    }

    $viewerRoleCandidate = $details['viewerRole'] ?? ($details['role'] ?? '');
    if (is_string($viewerRoleCandidate) && docs_normalize_assignment_role($viewerRoleCandidate) === 'admin') {
        $keys[] = 'role::admin';
    }

    return $keys;
}

function docs_sanitize_assignee_view_entry($value): array
{
    if (!is_array($value)) {
        return [];
    }

    $entry = [
        'assigneeKey' => sanitize_text_field($value['assigneeKey'] ?? '', 200),
        'id' => sanitize_text_field($value['id'] ?? '', 160),
        'name' => sanitize_text_field($value['name'] ?? '', 200),
        'viewedAt' => sanitize_text_field($value['viewedAt'] ?? '', 40),
    ];

    $entry = array_filter($entry, static function ($item) {
        return $item !== '';
    });

    return empty($entry) ? [] : $entry;
}

function docs_sanitize_assignee_views_payload($value): array
{
    if (!is_array($value)) {
        return [];
    }

    $result = [];
    foreach ($value as $entry) {
        $sanitized = docs_sanitize_assignee_view_entry($entry);
        if (!empty($sanitized)) {
            $result[] = $sanitized;
        }
    }

    return $result;
}

function docs_collect_valid_assignee_view_keys(array $record, ?array $assigneesOverride = null): array
{
    $validKeys = [];
    $viewParticipants = docs_extract_view_participants($record, $assigneesOverride);

    foreach ($viewParticipants as $entry) {
        if (!is_array($entry)) {
            continue;
        }

        foreach (docs_collect_assignee_index_keys($entry) as $key) {
            $normalizedKey = mb_strtolower(trim((string) $key), 'UTF-8');
            if ($normalizedKey !== '') {
                $validKeys[$normalizedKey] = true;
            }
        }
    }

    return $validKeys;
}

function docs_prune_assignee_views_for_record(array &$record, ?array $assigneesOverride = null): void
{
    if (!isset($record['assigneeViews']) || !is_array($record['assigneeViews'])) {
        return;
    }

    $validKeys = docs_collect_valid_assignee_view_keys($record, $assigneesOverride);
    if (empty($validKeys)) {
        unset($record['assigneeViews']);
        return;
    }

    $filteredViews = [];
    foreach ($record['assigneeViews'] as $viewEntry) {
        if (!is_array($viewEntry)) {
            continue;
        }

        $viewKey = !empty($viewEntry['assigneeKey'])
            ? mb_strtolower(trim((string) $viewEntry['assigneeKey']), 'UTF-8')
            : '';
        $viewId = isset($viewEntry['id'])
            ? docs_normalize_identifier_candidate_value($viewEntry['id'])
            : '';

        $keep = $viewKey !== '' && isset($validKeys[$viewKey]);
        if (!$keep && $viewId !== '') {
            $keep = isset($validKeys['id::' . $viewId]);
        }

        if ($keep) {
            $filteredViews[] = $viewEntry;
        }
    }

    $sanitizedViews = docs_sanitize_assignee_views_payload($filteredViews);
    if (!empty($sanitizedViews)) {
        $record['assigneeViews'] = $sanitizedViews;
        return;
    }

    unset($record['assigneeViews']);
}

function docs_collect_status_change_candidate_keys(array $requestContext, ?array $sessionAuth, string $statusChangeAuthor): array
{
    $candidates = [];

    $append = static function (string $key) use (&$candidates): void {
        if ($key === '') {
            return;
        }
        $candidates[$key] = true;
    };

    $viewKeys = docs_collect_view_candidate_keys($requestContext, ['viewerName' => $statusChangeAuthor]);
    foreach ($viewKeys as $key) {
        $append($key);
    }

    if (is_array($sessionAuth)) {
        foreach (['telegramId', 'chatId', 'responsibleNumber', 'login'] as $field) {
            if (empty($sessionAuth[$field])) {
                continue;
            }
            $normalized = docs_normalize_identifier_candidate_value($sessionAuth[$field]);
            if ($normalized !== '') {
                $append('id::' . $normalized);
            }
        }

        if (!empty($sessionAuth['fullName'])) {
            $normalized = docs_normalize_name_candidate_value($sessionAuth['fullName']);
            if ($normalized !== '') {
                $append('name::' . $normalized);
            }
        }

        if (!empty($sessionAuth['login'])) {
            $normalized = docs_normalize_name_candidate_value($sessionAuth['login']);
            if ($normalized !== '') {
                $append('name::' . $normalized);
            }
        }
    }

    $normalizedAuthor = docs_normalize_name_candidate_value($statusChangeAuthor);
    if ($normalizedAuthor !== '') {
        $append('name::' . $normalizedAuthor);
    }

    $normalizedIdentifier = docs_normalize_identifier_candidate_value($statusChangeAuthor);
    if ($normalizedIdentifier !== '') {
        $append('id::' . $normalizedIdentifier);
    }

    return array_keys($candidates);
}

function docs_sanitize_assignee_status_history_entry($value): array
{
    if (!is_array($value)) {
        return [];
    }

    $status = sanitize_status($value['status'] ?? '', false);
    $timestamp = docs_normalize_datetime_iso($value['changedAt'] ?? null);
    if ($status === '' || $timestamp === null) {
        return [];
    }

    $entry = [
        'status' => $status,
        'changedAt' => $timestamp,
    ];

    $author = sanitize_text_field($value['changedBy'] ?? '', 200);
    if ($author !== '') {
        $entry['changedBy'] = $author;
    }

    return $entry;
}

function docs_sanitize_assignee_status_history_record($value): array
{
    if (!is_array($value)) {
        return [];
    }

    $assigneeKey = sanitize_text_field($value['assigneeKey'] ?? '', 200);
    if ($assigneeKey === '') {
        return [];
    }

    $entries = [];
    if (isset($value['entries']) && is_array($value['entries'])) {
        foreach ($value['entries'] as $entry) {
            $sanitized = docs_sanitize_assignee_status_history_entry($entry);
            if (!empty($sanitized)) {
                $entries[] = $sanitized;
            }
        }
    }

    if (empty($entries)) {
        return [];
    }

    usort($entries, static function ($a, $b) {
        return strcmp($a['changedAt'], $b['changedAt']);
    });

    $deduplicated = [];
    foreach ($entries as $entry) {
        $key = $entry['changedAt'] . '|' . $entry['status'];
        if (isset($deduplicated[$key])) {
            if (!empty($entry['changedBy']) && empty($deduplicated[$key]['changedBy'])) {
                $deduplicated[$key]['changedBy'] = $entry['changedBy'];
            }
            continue;
        }
        $deduplicated[$key] = $entry;
    }

    return [
        'assigneeKey' => $assigneeKey,
        'entries' => array_values($deduplicated),
    ];
}

function docs_sanitize_assignee_status_history_collection($value): array
{
    if (!is_array($value)) {
        return [];
    }

    $result = [];
    foreach ($value as $record) {
        $sanitized = docs_sanitize_assignee_status_history_record($record);
        if (!empty($sanitized)) {
            $result[] = $sanitized;
        }
    }

    if (empty($result)) {
        return [];
    }

    usort($result, static function ($a, $b) {
        return strcmp(mb_strtolower($a['assigneeKey'], 'UTF-8'), mb_strtolower($b['assigneeKey'], 'UTF-8'));
    });

    return $result;
}

function docs_sanitize_assignee_status_history_entry_collection($value): array
{
    if (!is_array($value)) {
        return [];
    }

    $entries = [];
    foreach ($value as $entry) {
        $sanitized = docs_sanitize_assignee_status_history_entry($entry);
        if (!empty($sanitized)) {
            $entries[] = $sanitized;
        }
    }

    if (empty($entries)) {
        return [];
    }

    usort($entries, static function ($a, $b) {
        return strcmp($a['changedAt'], $b['changedAt']);
    });

    $deduplicated = [];
    foreach ($entries as $entry) {
        $key = $entry['changedAt'] . '|' . $entry['status'];
        if (isset($deduplicated[$key])) {
            if (!empty($entry['changedBy']) && empty($deduplicated[$key]['changedBy'])) {
                $deduplicated[$key]['changedBy'] = $entry['changedBy'];
            }
            continue;
        }
        $deduplicated[$key] = $entry;
    }

    return array_values($deduplicated);
}

function docs_register_task_view_event(string $organizationName, string $documentId, array $requestContext, array $details = []): array
{
    $result = [
        'recorded' => false,
        'alreadyRecorded' => false,
    ];

    $organization = docs_normalize_organization_candidate($organizationName);
    $documentId = sanitize_text_field($documentId, 200);

    if ($organization === '' || $documentId === '') {
        return $result;
    }

    $folder = sanitize_folder_name($organization);
    $records = load_registry($folder);
    $recordIndex = null;

    foreach ($records as $index => $record) {
        if (!is_array($record) || !isset($record['id'])) {
            continue;
        }

        if ((string) $record['id'] === $documentId) {
            $recordIndex = $index;
            break;
        }
    }

    if ($recordIndex === null) {
        docs_log_view_status_event('documents:register_view document_not_found', [
            'organization' => $organization,
            'documentId' => $documentId,
        ]);
        return $result;
    }

    $assignees = docs_extract_view_participants($records[$recordIndex]);
    if (empty($assignees)) {
        docs_log_view_status_event('documents:register_view no_assignees', [
            'organization' => $organization,
            'documentId' => $documentId,
        ]);
        return $result;
    }

    $assigneeIndex = docs_index_assignees($assignees);
    if (empty($assigneeIndex)) {
        docs_log_view_status_event('documents:register_view assignee_index_empty', [
            'organization' => $organization,
            'documentId' => $documentId,
            'assigneesCount' => count($assignees),
        ]);
        return $result;
    }

    $candidateKeys = docs_collect_view_candidate_keys($requestContext, $details);
    $assigneeKeys = array_keys($assigneeIndex);
    docs_log_view_status_event('documents:register_view candidates', [
        'organization' => $organization,
        'documentId' => $documentId,
        'candidateKeysCount' => count($candidateKeys),
        'candidateKeysSample' => array_slice($candidateKeys, 0, 12),
        'assigneeKeysCount' => count($assigneeKeys),
        'assigneeKeysSample' => array_slice($assigneeKeys, 0, 12),
    ]);
    $matchedKey = '';
    $matchedAssignee = null;

    foreach ($candidateKeys as $candidateKey) {
        if (isset($assigneeIndex[$candidateKey])) {
            $matchedKey = $candidateKey;
            $matchedAssignee = $assigneeIndex[$candidateKey];
            break;
        }
    }

    if ($matchedAssignee === null) {
        $rawContext = isset($requestContext['raw']) && is_array($requestContext['raw'])
            ? $requestContext['raw']
            : [];
        $userContext = isset($requestContext['user']) && is_array($requestContext['user'])
            ? $requestContext['user']
            : [];
        $userSummary = [
            'primaryId' => $requestContext['primaryId'] ?? null,
            'identity' => $requestContext['identity'] ?? null,
            'telegramUserId' => $rawContext['telegram_user_id'] ?? null,
            'telegramUsername' => $rawContext['telegram_username'] ?? null,
            'user' => [
                'id' => $userContext['id'] ?? null,
                'username' => $userContext['username'] ?? null,
                'fullName' => $userContext['fullName'] ?? null,
            ],
        ];
        docs_log_view_status_event('documents:register_view no_match', [
            'organization' => $organization,
            'documentId' => $documentId,
            'candidateKeysCount' => count($candidateKeys),
            'candidateKeysSample' => array_slice($candidateKeys, 0, 12),
            'assigneeKeysCount' => count($assigneeKeys),
            'assigneeKeysSample' => array_slice($assigneeKeys, 0, 12),
            'requestUser' => $userSummary,
        ]);

        $fallbackUserNames = [];
        $addFallbackUserName = static function ($value) use (&$fallbackUserNames): void {
            $normalized = docs_normalize_name_candidate_value($value ?? '');
            if ($normalized !== '') {
                $fallbackUserNames[$normalized] = true;
            }
        };

        $addFallbackUserName($requestContext['primaryId'] ?? '');
        $addFallbackUserName($userContext['fullName'] ?? null);
        $addFallbackUserName($userContext['firstName'] ?? null);
        $addFallbackUserName($userContext['lastName'] ?? null);
        $addFallbackUserName($rawContext['telegram_full_name'] ?? null);

        $fallbackMatchedAssignee = null;
        $fallbackMatchedKey = '';
        if (!empty($fallbackUserNames)) {
            foreach ($assignees as $assignee) {
                if (!is_array($assignee)) {
                    continue;
                }

                foreach (['fullName', 'name', 'responsible'] as $field) {
                    if (!isset($assignee[$field])) {
                        continue;
                    }

                    $normalizedName = docs_normalize_name_candidate_value($assignee[$field]);
                    if ($normalizedName === '') {
                        continue;
                    }

                    if (isset($fallbackUserNames[$normalizedName])) {
                        $fallbackMatchedAssignee = $assignee;
                        $fallbackMatchedKey = 'name::' . $normalizedName;
                        break 2;
                    }
                }
            }
        }

        if ($fallbackMatchedAssignee === null) {
            return $result;
        }

        $matchedAssignee = $fallbackMatchedAssignee;
        $matchedKey = $fallbackMatchedKey;
        docs_log_view_status_event('documents:register_view fallback_name_match', [
            'organization' => $organization,
            'documentId' => $documentId,
            'matchedKey' => $matchedKey,
        ]);
    }

    $timestamp = null;
    if (isset($details['viewedAt']) && is_string($details['viewedAt'])) {
        $normalizedTimestamp = docs_normalize_datetime_iso($details['viewedAt']);
        if ($normalizedTimestamp !== null) {
            $timestamp = $normalizedTimestamp;
        }
    }
    if ($timestamp === null) {
        $timestamp = date('c');
    }

    $normalizedKey = mb_strtolower($matchedKey, 'UTF-8');

    $normalizedId = '';
    if (strpos($normalizedKey, 'id::') === 0) {
        $normalizedId = substr($normalizedKey, 4);
    }

    if ($normalizedId === '') {
        $normalizedId = docs_normalize_identifier_candidate_value($matchedAssignee['id'] ?? '');
    }

    if ($normalizedId === '') {
        $normalizedId = docs_normalize_identifier_candidate_value($requestContext['primaryId'] ?? '');
    }

    if ($normalizedId === '') {
        $normalizedId = docs_normalize_identifier_candidate_value($requestContext['raw']['telegram_user_id'] ?? '');
    }

    if ($normalizedId === '') {
        return $result;
    }

    $viewerName = '';
    if (isset($requestContext['user']) && is_array($requestContext['user'])) {
        $viewerName = sanitize_text_field((string) ($requestContext['user']['fullName'] ?? ''), 200);
        if ($viewerName === '') {
            $firstName = sanitize_text_field((string) ($requestContext['user']['firstName'] ?? ''), 120);
            $lastName = sanitize_text_field((string) ($requestContext['user']['lastName'] ?? ''), 160);
            $viewerName = trim($firstName . ' ' . $lastName);
        }
        if ($viewerName === '' && !empty($requestContext['user']['username'])) {
            $viewerName = '@' . sanitize_text_field((string) $requestContext['user']['username'], 120);
        }
    }

    if ($viewerName === '' && isset($details['viewerName'])) {
        $viewerName = sanitize_text_field((string) $details['viewerName'], 200);
    }

    if ($viewerName === '' && isset($matchedAssignee['name'])) {
        $viewerName = (string) $matchedAssignee['name'];
    } elseif ($viewerName === '' && isset($matchedAssignee['responsible'])) {
        $viewerName = (string) $matchedAssignee['responsible'];
    }

    $viewsMap = [];
    $orderedKeys = [];

    if (isset($records[$recordIndex]['assigneeViews']) && is_array($records[$recordIndex]['assigneeViews'])) {
        foreach ($records[$recordIndex]['assigneeViews'] as $entry) {
            if (!is_array($entry)) {
                continue;
            }

            $entryKey = '';
            if (!empty($entry['assigneeKey'])) {
                $entryKey = mb_strtolower((string) $entry['assigneeKey'], 'UTF-8');
            }

            if ($entryKey === '' && !empty($entry['id'])) {
                $candidate = docs_normalize_identifier_candidate_value($entry['id']);
                if ($candidate !== '') {
                    $entryKey = 'id::' . $candidate;
                }
            }

            if ($entryKey === '') {
                continue;
            }

            if (!isset($viewsMap[$entryKey])) {
                $viewsMap[$entryKey] = $entry;
                $orderedKeys[] = $entryKey;
            }
        }
    }

    $existingEntry = null;
    if (isset($viewsMap[$normalizedKey]) && is_array($viewsMap[$normalizedKey])) {
        $existingEntry = $viewsMap[$normalizedKey];
    } elseif ($normalizedId !== '') {
        $idKey = 'id::' . $normalizedId;
        if (isset($viewsMap[$idKey]) && is_array($viewsMap[$idKey])) {
            $existingEntry = $viewsMap[$idKey];
            $normalizedKey = $idKey;
            $matchedKey = $idKey;
        }
    }

    if (is_array($existingEntry) && isset($existingEntry['viewedAt']) && $existingEntry['viewedAt'] !== '') {
        $result['alreadyRecorded'] = true;
        $result['viewedAt'] = (string) $existingEntry['viewedAt'];
        if (isset($existingEntry['assigneeKey'])) {
            $result['assigneeKey'] = (string) $existingEntry['assigneeKey'];
        }
        if (isset($existingEntry['id'])) {
            $result['id'] = (string) $existingEntry['id'];
        }
        if (isset($existingEntry['name'])) {
            $result['name'] = (string) $existingEntry['name'];
        }

        return $result;
    }

    $viewEntry = [
        'assigneeKey' => $matchedKey,
        'viewedAt' => $timestamp,
    ];

    if ($normalizedId !== '') {
        $viewEntry['id'] = $normalizedId;
    }

    if ($viewerName !== '') {
        $viewEntry['name'] = $viewerName;
    }

    $updatedEntry = is_array($existingEntry)
        ? array_merge($existingEntry, $viewEntry)
        : $viewEntry;
    $updatedEntry['assigneeKey'] = $matchedKey;
    $updatedEntry['viewedAt'] = $timestamp;

    $viewsMap[$normalizedKey] = $updatedEntry;
    if (!in_array($normalizedKey, $orderedKeys, true)) {
        $orderedKeys[] = $normalizedKey;
    }

    $updatedViews = [];
    foreach ($orderedKeys as $key) {
        if (!isset($viewsMap[$key])) {
            continue;
        }

        $updatedViews[] = $viewsMap[$key];
    }

    $sanitizedViews = docs_sanitize_assignee_views_payload($updatedViews);
    if (empty($sanitizedViews)) {
        return $result;
    }

    $records[$recordIndex]['assigneeViews'] = $sanitizedViews;
    save_registry($folder, $records);

    $logContext = [
        'organization' => $organization,
        'folder' => $folder,
        'documentId' => $documentId,
        'assigneeKey' => $matchedKey,
        'viewerId' => $normalizedId,
    ];

    if (isset($details['trigger'])) {
        $logContext['trigger'] = sanitize_text_field((string) $details['trigger'], 120);
    }

    log_docs_event('Task view recorded', $logContext);

    $result['recorded'] = true;
    $result['viewedAt'] = $timestamp;
    $result['assigneeKey'] = $matchedKey;
    if ($normalizedId !== '') {
        $result['id'] = $normalizedId;
    }
    if ($viewerName !== '') {
        $result['name'] = $viewerName;
    }

    return $result;
}

function load_registry(string $folder): array
{
    $file = get_registry_path($folder);
    $context = [
        'folder' => $folder,
        'path' => $file,
    ];

    if (!is_file($file)) {
        log_docs_event('Registry file missing', $context);
        return [];
    }

    $size = @filesize($file);
    if ($size !== false) {
        $context['fileSize'] = $size;
    }

    $raw = file_get_contents($file);
    if ($raw === false) {
        log_docs_event('Registry file read failed', $context);
        return [];
    }

    $context['rawLength'] = strlen($raw);

    if (trim($raw) === '') {
        log_docs_event('Registry file empty', $context);
        return [];
    }

    $data = json_decode($raw, true);
    if (!is_array($data)) {
        $context['jsonError'] = json_last_error_msg();
        log_docs_event('Registry decode error', $context);
        return [];
    }

    $context['recordsCount'] = count($data);

    $sampleIds = [];
    $sampleRecords = [];
    foreach (array_slice($data, 0, 5) as $record) {
        if (!is_array($record)) {
            continue;
        }

        if (isset($record['id'])) {
            $sampleIds[] = (string) $record['id'];
        } elseif (isset($record['entryNumber'])) {
            $sampleIds[] = (string) $record['entryNumber'];
        }

        $summary = [];
        if (isset($record['id'])) {
            $summary['id'] = (string) $record['id'];
        }
        if (isset($record['entryNumber'])) {
            $summary['entryNumber'] = (string) $record['entryNumber'];
        }
        if (isset($record['status']) && $record['status'] !== '') {
            $summary['status'] = (string) $record['status'];
        }
        $assignees = docs_extract_assignees($record);
        if (!empty($assignees)) {
            $assignee = $assignees[0];
            if (!empty($assignee['name'])) {
                $summary['assigneeName'] = (string) $assignee['name'];
            } elseif (!empty($assignee['responsible'])) {
                $summary['assigneeName'] = (string) $assignee['responsible'];
            }
            foreach (['id', 'telegram', 'chatId'] as $field) {
                if (!empty($assignee[$field])) {
                    $summary['assignee' . ucfirst($field)] = (string) $assignee[$field];
                    break;
                }
            }
            $summary['assigneesCount'] = count($assignees);
        } elseif (isset($record['responsible']) && $record['responsible'] !== '') {
            $summary['assigneeName'] = (string) $record['responsible'];
        }

        if (!empty($summary)) {
            $sampleRecords[] = $summary;
        }
    }

    if (!empty($sampleIds)) {
        $context['sampleIds'] = array_values(array_unique($sampleIds));
    }
    if (!empty($sampleRecords)) {
        $context['sampleRecords'] = $sampleRecords;
    }

    log_docs_event('Registry file loaded', $context);

    return $data;
}

function save_registry(string $folder, array $records): void
{
    $dir = ensure_organization_directory($folder);
    $file = $dir . '/' . REGISTRY_FILENAME;
    $json = json_encode(array_values($records), JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    file_put_contents($file, $json, LOCK_EX);
}

function docs_lock_registry(string $folder): array
{
    $dir = ensure_organization_directory($folder);
    $file = $dir . '/' . REGISTRY_FILENAME;
    $handle = @fopen($file, 'c+');
    if ($handle === false) {
        log_docs_event('Registry file open failed', [
            'file' => $file,
            'folder' => $folder,
        ]);
        return [null, []];
    }

    if (!flock($handle, LOCK_EX)) {
        log_docs_event('Registry file lock failed', [
            'file' => $file,
            'folder' => $folder,
        ]);
        fclose($handle);
        return [null, []];
    }

    rewind($handle);
    $raw = stream_get_contents($handle);
    if ($raw === false) {
        log_docs_event('Registry file read failed (locked)', [
            'file' => $file,
            'folder' => $folder,
        ]);
        $records = [];
    } elseif (trim($raw) === '') {
        $records = [];
    } else {
        $decoded = json_decode($raw, true);
        if (!is_array($decoded)) {
            log_docs_event('Registry decode error (locked)', [
                'file' => $file,
                'folder' => $folder,
                'jsonError' => json_last_error_msg(),
            ]);
            $records = [];
        } else {
            $records = $decoded;
        }
    }

    register_shutdown_function(function () use ($handle) {
        if (is_resource($handle)) {
            flock($handle, LOCK_UN);
            fclose($handle);
        }
    });

    return [$handle, $records];
}

function docs_save_registry_locked($handle, array $records): bool
{
    if (!is_resource($handle)) {
        return false;
    }

    $json = json_encode(array_values($records), JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    if ($json === false) {
        return false;
    }

    rewind($handle);
    if (!ftruncate($handle, 0)) {
        return false;
    }

    $written = fwrite($handle, $json);
    if ($written === false) {
        return false;
    }

    if (!fflush($handle)) {
        return false;
    }

    return true;
}

function docs_unlock_registry($handle): void
{
    if (!is_resource($handle)) {
        return;
    }
    flock($handle, LOCK_UN);
    fclose($handle);
}

function docs_generate_password_hash(string $password): ?string
{
    $password = trim($password);
    if ($password === '') {
        return null;
    }

    if (function_exists('password_hash')) {
        $hash = password_hash($password, PASSWORD_DEFAULT);
        if (is_string($hash) && $hash !== '') {
            return $hash;
        }
    }

    $saltSource = null;
    if (function_exists('random_bytes')) {
        try {
            $saltSource = random_bytes(16);
        } catch (Throwable $exception) {
            $saltSource = null;
        }
    }

    if ($saltSource === null) {
        $saltSource = uniqid('', true);
    }

    $salt = substr(str_replace('+', '.', base64_encode($saltSource)), 0, 22);
    $fallback = crypt($password, '$2y$10$' . $salt);
    if (is_string($fallback) && $fallback !== '') {
        return $fallback;
    }

    return null;
}

function docs_normalize_theme_mode($value): string
{
    $mode = mb_strtolower(trim((string) $value), 'UTF-8');
    if ($mode === 'light') {
        return 'light';
    }
    if ($mode === 'dark') {
        return 'dark';
    }

    return '';
}

function sanitize_admin_entry(array $entry): array
{
    $clean = [
        'number' => sanitize_text_field($entry['number'] ?? '', 20),
        'responsible' => sanitize_text_field($entry['responsible'] ?? '', 200),
        'position' => sanitize_text_field($entry['position'] ?? '', 160),
        'telegram' => sanitize_text_field($entry['telegram'] ?? '', 120),
        'chatId' => sanitize_text_field($entry['chatId'] ?? '', 40),
        'email' => sanitize_text_field($entry['email'] ?? '', 160),
        'department' => sanitize_text_field($entry['department'] ?? '', 160),
        'note' => sanitize_text_field($entry['note'] ?? '', 300),
        'login' => sanitize_text_field($entry['login'] ?? '', 120),
        'theme' => docs_normalize_theme_mode($entry['theme'] ?? ''),
    ];

    if (isset($entry['role'])) {
        $role = sanitize_text_field((string) $entry['role'], 60);
        if ($role !== '') {
            $clean['role'] = $role;
        }
    }

    $passwordRaw = isset($entry['password']) ? trim((string) $entry['password']) : '';
    $passwordHashRaw = isset($entry['passwordHash']) ? trim((string) $entry['passwordHash']) : '';
    $passwordHash = '';

    if ($passwordRaw !== '') {
        $generated = docs_generate_password_hash($passwordRaw);
        if (is_string($generated) && $generated !== '') {
            $passwordHash = sanitize_text_field($generated, 255);
        }
    } elseif ($passwordHashRaw !== '') {
        $passwordHash = sanitize_text_field($passwordHashRaw, 255);
    }

    if ($passwordHash !== '') {
        $clean['passwordHash'] = $passwordHash;
    }

    return $clean;
}

function sanitize_admin_settings(array $payload): array
{
    $responsibles = [];
    if (isset($payload['responsibles']) && is_array($payload['responsibles'])) {
        foreach ($payload['responsibles'] as $entry) {
            if (!is_array($entry)) {
                continue;
            }

            $clean = sanitize_admin_entry($entry);

            $hasValue = false;
            foreach ($clean as $value) {
                if ($value !== '') {
                    $hasValue = true;
                    break;
                }
            }

            if ($hasValue) {
                if (!isset($clean['role']) || $clean['role'] === '') {
                    $clean['role'] = 'responsible';
                }
                $responsibles[] = $clean;
            }
        }
    }

    $block2 = [];
    if (isset($payload['block2']) && is_array($payload['block2'])) {
        foreach ($payload['block2'] as $entry) {
            if (!is_array($entry)) {
                continue;
            }

            $clean = sanitize_admin_entry($entry);

            $hasValue = false;
            foreach ($clean as $value) {
                if ($value !== '') {
                    $hasValue = true;
                    break;
                }
            }

            if ($hasValue) {
                if (!isset($clean['role']) || $clean['role'] === '') {
                    $clean['role'] = 'director';
                }
                $block2[] = $clean;
            }
        }
    }

    $block3 = [];
    if (isset($payload['block3']) && is_array($payload['block3'])) {
        foreach ($payload['block3'] as $entry) {
            if (!is_array($entry)) {
                continue;
            }

            $clean = sanitize_admin_entry($entry);

            $hasValue = false;
            foreach ($clean as $value) {
                if ($value !== '') {
                    $hasValue = true;
                    break;
                }
            }

            if ($hasValue) {
                if (!isset($clean['role']) || $clean['role'] === '') {
                    $clean['role'] = 'subordinate';
                }
                $block3[] = $clean;
            }
        }
    }

    return [
        'responsibles' => $responsibles,
        'block2' => $block2,
        'block3' => $block3,
    ];
}

function docs_sanitize_column_widths($input): array
{
    if (!is_array($input)) {
        return [];
    }

    $allowedKeys = array_keys(DOCS_COLUMN_WIDTH_DEFAULTS);
    $normalized = [];

    foreach ($input as $key => $value) {
        if (!is_string($key) || !in_array($key, $allowedKeys, true)) {
            continue;
        }

        if (is_array($value) && array_key_exists('value', $value)) {
            $value = $value['value'];
        }

        if (is_string($value)) {
            $value = trim($value);
        }

        if ($value === '' || $value === null) {
            continue;
        }

        if (!is_numeric($value)) {
            continue;
        }

        $width = (int) round((float) $value);
        if ($width < DOCS_COLUMN_WIDTH_MIN) {
            $width = DOCS_COLUMN_WIDTH_MIN;
        } elseif ($width > DOCS_COLUMN_WIDTH_MAX) {
            $width = DOCS_COLUMN_WIDTH_MAX;
        }

        $normalized[$key] = $width;
    }

    return $normalized;
}

function docs_normalize_column_width_map($map): array
{
    if (!is_array($map)) {
        return [];
    }

    $normalized = [];

    foreach ($map as $profile => $entry) {
        if (!is_string($profile) || $profile === '') {
            continue;
        }

        $profileKey = docs_normalize_table_preferences_profile_key($profile);
        if ($profileKey === '') {
            continue;
        }

        $entryArray = is_array($entry) ? $entry : [];
        $columns = [];
        if (isset($entryArray['columns'])) {
            $columns = docs_sanitize_column_widths($entryArray['columns']);
        }

        $normalizedEntry = ['columns' => $columns];

        if (isset($entryArray['updatedAt']) && is_string($entryArray['updatedAt']) && $entryArray['updatedAt'] !== '') {
            $normalizedEntry['updatedAt'] = $entryArray['updatedAt'];
        }

        if (isset($entryArray['updatedBy']) && $entryArray['updatedBy'] !== '') {
            $normalizedEntry['updatedBy'] = sanitize_text_field((string) $entryArray['updatedBy'], 200);
        }

        $normalized[$profileKey] = $normalizedEntry;
    }

    return $normalized;
}

function docs_sanitize_column_order($input): array
{
    $defaults = DOCS_COLUMN_ORDER_DEFAULTS;
    if (!is_array($input)) {
        return $defaults;
    }

    $allowed = array_fill_keys($defaults, true);
    $seen = [];
    $normalized = [];

    foreach ($input as $value) {
        if (!is_string($value) && !is_int($value)) {
            continue;
        }
        $key = trim((string) $value);
        if ($key === '' || !isset($allowed[$key]) || isset($seen[$key])) {
            continue;
        }
        $seen[$key] = true;
        $normalized[] = $key;
    }

    foreach ($defaults as $key) {
        if (!isset($seen[$key])) {
            $normalized[] = $key;
        }
    }

    return $normalized;
}

