    return $normalized;
}

function docs_normalize_column_order_map($map): array
{
    if (!is_array($map)) {
        return [];
    }

    $normalized = [];

    foreach ($map as $profile => $entry) {
        if (!is_string($profile) || $profile === '') {
            continue;
        }
        $profileKey = docs_normalize_table_preferences_profile_key($profile);
        if ($profileKey === '') {
            continue;
        }
        $entryArray = is_array($entry) ? $entry : [];
        $columns = isset($entryArray['columns'])
            ? docs_sanitize_column_order($entryArray['columns'])
            : DOCS_COLUMN_ORDER_DEFAULTS;

        $normalizedEntry = ['columns' => $columns];
        if (isset($entryArray['updatedAt']) && is_string($entryArray['updatedAt']) && $entryArray['updatedAt'] !== '') {
            $normalizedEntry['updatedAt'] = $entryArray['updatedAt'];
        }
        if (isset($entryArray['updatedBy']) && $entryArray['updatedBy'] !== '') {
            $normalizedEntry['updatedBy'] = sanitize_text_field((string) $entryArray['updatedBy'], 200);
        }
        $normalized[$profileKey] = $normalizedEntry;
    }

    return $normalized;
}

function docs_normalize_table_preferences_profile_key(string $profile): string
{
    $key = preg_replace('/[^a-z0-9:_-]/i', '', strtolower(trim($profile)));

    return is_string($key) && $key !== '' ? $key : 'default';
}

function docs_normalize_legacy_profile_key_without_colon(string $profile): string
{
    $key = preg_replace('/[^a-z0-9_-]/i', '', strtolower(trim($profile)));

    return is_string($key) ? $key : '';
}

function docs_sanitize_table_filter_selections($input): array
{
    if (!is_array($input)) {
        return [];
    }

    $allowed = array_fill_keys(DOCS_COLUMN_ORDER_DEFAULTS, true);
    $normalized = [];

    foreach ($input as $key => $values) {
        if (!is_string($key) || !isset($allowed[$key]) || !is_array($values)) {
            continue;
        }

        $selected = [];
        $seen = [];
        foreach ($values as $value) {
            $text = sanitize_text_field((string) $value, 220);
            if ($text === '') {
                continue;
            }
            $lookup = mb_strtolower($text, 'UTF-8');
            if (isset($seen[$lookup])) {
                continue;
            }
            $seen[$lookup] = true;
            $selected[] = $text;
            if (count($selected) >= DOCS_FILTER_SELECTION_MAX_VALUES) {
                break;
            }
        }

        if (!empty($selected)) {
            $normalized[$key] = $selected;
        }
    }

    return $normalized;
}

function docs_sanitize_table_filter_preferences($input): array
{
    if (!is_array($input)) {
        return [];
    }

    $allowed = array_fill_keys(DOCS_COLUMN_ORDER_DEFAULTS, true);
    $normalized = [];

    foreach ($input as $key => $entry) {
        if (!is_string($key) || !isset($allowed[$key])) {
            continue;
        }

        $text = '';
        $selected = [];
        if (is_array($entry)) {
            $text = sanitize_text_field((string) ($entry['text'] ?? ''), 180);
            $selectedMap = docs_sanitize_table_filter_selections([$key => $entry['selected'] ?? []]);
            $selected = $selectedMap[$key] ?? [];
        } else {
            $text = sanitize_text_field((string) $entry, 180);
        }

        if ($text !== '' || !empty($selected)) {
            $normalized[$key] = [
                'text' => $text,
                'selected' => $selected,
            ];
        }
    }

    return $normalized;
}

function docs_sanitize_table_filter_order($input, array $filters): array
{
    $allowed = array_fill_keys(DOCS_COLUMN_ORDER_DEFAULTS, true);
    $seen = [];
    $order = [];

    $append = static function ($value) use (&$seen, &$order, $allowed, $filters): void {
        if (!is_string($value) && !is_int($value)) {
            return;
        }
        $key = trim((string) $value);
        if ($key === '' || !isset($allowed[$key]) || isset($seen[$key]) || !isset($filters[$key])) {
            return;
        }
        $seen[$key] = true;
        $order[] = $key;
    };

    if (is_array($input)) {
        foreach ($input as $value) {
            $append($value);
        }
    }

    foreach (DOCS_COLUMN_ORDER_DEFAULTS as $key) {
        $append($key);
    }

    return $order;
}

function docs_sanitize_table_sorting($input): array
{
    $result = [
        'enabled' => false,
        'rules' => [],
    ];
    if (!is_array($input) || empty($input['rules']) || !is_array($input['rules'])) {
        return $result;
    }

    $allowed = array_fill_keys(DOCS_COLUMN_ORDER_DEFAULTS, true);
    unset($allowed['actions'], $allowed['files']);
    $seen = [];
    foreach ($input['rules'] as $rule) {
        if (!is_array($rule)) {
            continue;
        }
        $column = sanitize_text_field((string) ($rule['column'] ?? ''), 80);
        if ($column === '' || !isset($allowed[$column]) || isset($seen[$column])) {
            continue;
        }
        $direction = strtolower(sanitize_text_field((string) ($rule['direction'] ?? ''), 10));
        $seen[$column] = true;
        $result['rules'][] = [
            'column' => $column,
            'direction' => $direction === 'desc' ? 'desc' : 'asc',
        ];
        if (count($result['rules']) >= 3) {
            break;
        }
    }
    $result['enabled'] = !empty($result['rules']) && !empty($input['enabled']);

    return $result;
}

function docs_sanitize_table_columns($input): array
{
    $source = is_array($input) ? $input : [];
    $columns = [];

    foreach (DOCS_COLUMN_WIDTH_DEFAULTS as $key => $defaultWidth) {
        $entry = isset($source[$key]) && is_array($source[$key]) ? $source[$key] : [];
        $width = docs_sanitize_column_widths([$key => $entry['width'] ?? $defaultWidth]);
        $columns[$key] = [
            'visible' => !array_key_exists('visible', $entry) || $entry['visible'] !== false,
            'width' => $width[$key] ?? $defaultWidth,
        ];
    }

    return $columns;
}

function docs_sanitize_table_grouping($input): array
{
    $source = is_array($input) ? $input : [];
    $column = sanitize_text_field((string) ($source['column'] ?? ''), 80);
    $allowed = array_fill_keys(DOCS_COLUMN_ORDER_DEFAULTS, true);
    $allowed['department'] = true;
    unset($allowed['actions'], $allowed['summary'], $allowed['resolution'], $allowed['instruction']);

    return [
        'column' => $column !== '' && isset($allowed[$column]) ? $column : '',
    ];
}

function docs_sanitize_table_page_size($value): int|string
{
    if (is_string($value) && mb_strtolower(trim($value), 'UTF-8') === 'all') {
        return 'all';
    }

    $pageSize = (int) $value;
    if (!in_array($pageSize, [25, 50, 100], true)) {
        return 25;
    }

    return $pageSize;
}

function docs_sanitize_visual_hex_color($value, string $fallback = '#e2e8f0'): string
{
    $color = is_string($value) ? trim($value) : '';
    if (preg_match('/^#?([0-9a-f]{3}|[0-9a-f]{6})$/i', $color, $matches) !== 1) {
        return $fallback;
    }

    $hex = strtolower($matches[1]);
    if (strlen($hex) === 3) {
        $hex = $hex[0] . $hex[0] . $hex[1] . $hex[1] . $hex[2] . $hex[2];
    }

    return '#' . $hex;
}

function docs_sanitize_visual_settings($input): array
{
    $source = is_array($input) ? $input : [];
    $fontSize = (int) round((float) ($source['fontSize'] ?? 14));
    $fontSize = max(12, min(22, $fontSize));
    $lineHeight = (float) ($source['lineHeight'] ?? 1.45);
    $lineHeight = max(1.2, min(2.0, $lineHeight));
    $borderWidth = (float) ($source['borderWidth'] ?? 1);
    $borderWidth = max(0, min(4, $borderWidth));
    $borderOpacity = (float) ($source['borderOpacity'] ?? 0.85);
    $borderOpacity = max(0, min(1, $borderOpacity));
    $columnsSource = isset($source['columns']) && is_array($source['columns']) ? $source['columns'] : [];
    $columns = [];

    foreach (DOCS_COLUMN_WIDTH_DEFAULTS as $key => $defaultWidth) {
        $entry = isset($columnsSource[$key]) && is_array($columnsSource[$key]) ? $columnsSource[$key] : [];
        $width = docs_sanitize_column_widths([$key => $entry['width'] ?? $defaultWidth]);
        $columnFontSize = (int) round((float) ($entry['fontSize'] ?? $fontSize));
        $columnFontSize = max(12, min(22, $columnFontSize));
        $columns[$key] = [
            'width' => $width[$key] ?? $defaultWidth,
            'fontSize' => $columnFontSize,
            'visible' => !array_key_exists('visible', $entry) || $entry['visible'] !== false,
        ];
    }

    $mailingSource = isset($source['mailing']) && is_array($source['mailing']) ? $source['mailing'] : [];

    return [
        'fontSize' => $fontSize,
        'lineHeight' => round($lineHeight, 2),
        'borderColor' => docs_sanitize_visual_hex_color($source['borderColor'] ?? '#e2e8f0'),
        'borderWidth' => $borderWidth,
        'borderOpacity' => $borderOpacity,
        'columns' => $columns,
        'sorting' => docs_sanitize_table_sorting($source['sorting'] ?? []),
        'mailing' => [
            'notifyDirectorAboutAttachedReplies' => !empty($mailingSource['notifyDirectorAboutAttachedReplies']),
        ],
    ];
}

function docs_table_filter_texts(array $filters): array
{
    $texts = [];
    foreach ($filters as $key => $entry) {
        if (isset($entry['text']) && $entry['text'] !== '') {
            $texts[$key] = $entry['text'];
        }
    }

    return $texts;
}

function docs_table_filter_selected_values(array $filters): array
{
    $selected = [];
    foreach ($filters as $key => $entry) {
        if (!empty($entry['selected']) && is_array($entry['selected'])) {
            $selected[$key] = $entry['selected'];
        }
    }

    return $selected;
}

function docs_sanitize_custom_document_tabs($input): array
{
    if (!is_array($input)) {
        return [];
    }

    $tabs = [];
    $seen = [];
    foreach ($input as $index => $item) {
        if (!is_array($item) || count($tabs) >= 24) {
            continue;
        }
        $name = sanitize_text_field((string) ($item['name'] ?? ($item['label'] ?? '')), 48);
        if ($name === '') {
            continue;
        }
        $id = sanitize_text_field((string) ($item['id'] ?? ''), 80);
        if ($id === '' || in_array($id, ['all', 'overdue', 'completed', 'withoutStatus'], true) || isset($seen[$id])) {
            $id = 'custom_' . time() . '_' . (int) $index;
        }
        $seen[$id] = true;

        $filters = docs_sanitize_table_filter_preferences($item['filters'] ?? []);
        $selections = docs_sanitize_table_filter_selections($item['filterSelections'] ?? []);
        foreach ($selections as $key => $values) {
            if (!isset($filters[$key])) {
                $filters[$key] = ['text' => '', 'selected' => $values];
            } elseif (empty($filters[$key]['selected'])) {
                $filters[$key]['selected'] = $values;
            }
        }

        $baseTab = sanitize_text_field((string) ($item['baseTab'] ?? 'all'), 40);
        if (!in_array($baseTab, ['all', 'overdue', 'completed', 'withoutStatus'], true)) {
            $baseTab = 'all';
        }

        $tabs[] = [
            'id' => $id,
            'name' => $name,
            'filters' => docs_table_filter_texts($filters),
            'filterSelections' => docs_table_filter_selected_values($filters),
            'filterOrder' => docs_sanitize_table_filter_order($item['filterOrder'] ?? [], $filters),
            'globalSearchQuery' => sanitize_text_field((string) ($item['globalSearchQuery'] ?? ''), 180),
            'sorting' => docs_sanitize_table_sorting($item['sorting'] ?? []),
            'showUnassignedOnly' => !empty($item['showUnassignedOnly']),
            'showUnviewedOnly' => !empty($item['showUnviewedOnly']),
            'baseTab' => $baseTab,
            'custom' => true,
        ];
    }

    return $tabs;
}

function docs_sanitize_table_preferences($input): array
{
    $source = is_array($input) ? $input : [];
    $filters = docs_sanitize_table_filter_preferences($source['filters'] ?? []);
    $view = isset($source['view']) && is_array($source['view']) ? $source['view'] : [];
    $pageSize = docs_sanitize_table_page_size($view['pageSize'] ?? ($source['tablePageSize'] ?? 25));
    $density = sanitize_text_field((string) ($view['density'] ?? ($source['tableDensity'] ?? 'normal')), 20);
    if (!in_array($density, ['normal', 'compact'], true)) {
        $density = 'normal';
    }
    $groupingSource = isset($source['grouping']) && is_array($source['grouping'])
        ? $source['grouping']
        : ['column' => $source['groupingColumn'] ?? ''];
    $grouping = docs_sanitize_table_grouping($groupingSource);

    return [
        'filters' => $filters,
        'filterOrder' => docs_sanitize_table_filter_order($source['filterOrder'] ?? [], $filters),
        'globalSearchQuery' => sanitize_text_field((string) ($source['globalSearchQuery'] ?? ''), 180),
        'sorting' => docs_sanitize_table_sorting($source['sorting'] ?? []),
        'columns' => docs_sanitize_table_columns($source['columns'] ?? []),
        'visualSettings' => docs_sanitize_visual_settings($source['visualSettings'] ?? []),
        'columnOrder' => docs_sanitize_column_order($source['columnOrder'] ?? []),
        'customDocumentTabs' => docs_sanitize_custom_document_tabs($source['customDocumentTabs'] ?? []),
        'tablePageSize' => $pageSize,
        'view' => [
            'density' => $density,
            'pageSize' => $pageSize,
        ],
        'grouping' => $grouping,
        'groupingColumn' => $grouping['column'],
        'showUnassignedOnly' => !empty($source['showUnassignedOnly']),
        'showUnviewedOnly' => !empty($source['showUnviewedOnly']),
    ];
}

function docs_normalize_table_preferences_map($map): array
{
    if (!is_array($map)) {
        return [];
    }

    $normalized = [];
    foreach ($map as $profile => $entry) {
        if (!is_string($profile) || $profile === '') {
            continue;
        }
        $profileKey = docs_normalize_table_preferences_profile_key($profile);
        $entryArray = is_array($entry) ? $entry : [];
        $preferences = docs_sanitize_table_preferences($entryArray['preferences'] ?? []);
        $normalizedEntry = ['preferences' => $preferences];
        if (isset($entryArray['updatedAt']) && is_string($entryArray['updatedAt']) && $entryArray['updatedAt'] !== '') {
            $normalizedEntry['updatedAt'] = $entryArray['updatedAt'];
        }
        if (isset($entryArray['updatedBy']) && $entryArray['updatedBy'] !== '') {
            $normalizedEntry['updatedBy'] = sanitize_text_field((string) $entryArray['updatedBy'], 200);
        }
        $normalized[$profileKey] = $normalizedEntry;
    }

    return $normalized;
}

function normalize_identifier_value($value): string
{
    if (is_int($value) || is_float($value)) {
        $value = (string) $value;
    } elseif (!is_string($value)) {
        return '';
    }

    $value = trim($value);

    return $value === '' ? '' : $value;
}

function normalize_username_value($value): string
{
    $value = normalize_identifier_value($value);
    if ($value === '') {
        return '';
    }
    if ($value[0] === '@') {
        $value = substr($value, 1);
    }
    $value = trim($value);
    if ($value === '') {
        return '';
    }

    return mb_strtolower($value, 'UTF-8');
}

function split_name_tokens(string $value): array
{
    $value = trim($value);
    if ($value === '') {
        return [];
    }

    $parts = preg_split('/\s+/u', $value, -1, PREG_SPLIT_NO_EMPTY);
    if (!is_array($parts)) {
        return [];
    }

    return array_values(array_filter(array_map(static function ($token) {
        $token = trim((string) $token);
        if ($token === '') {
            return '';
        }

        return mb_strtolower($token, 'UTF-8');
    }, $parts)));
}

function extract_assignee_filter_from_array(array $source): ?array
{
    $ids = [];
    $pushId = static function ($value) use (&$ids): void {
        $normalized = normalize_identifier_value($value);
        if ($normalized !== '' && !in_array($normalized, $ids, true)) {
            $ids[] = $normalized;
        }
    };

    $pushId($source['telegram_user_id'] ?? null);
    $pushId($source['telegram_chat_id'] ?? null);
    $pushId($source['user_id'] ?? null);
    $pushId($source['chat_id'] ?? null);

    $username = normalize_username_value(
        $source['telegram_username']
        ?? ($source['username'] ?? null)
    );
    $fullName = sanitize_text_field((string) (
        $source['telegram_full_name']
        ?? ($source['full_name'] ?? ($source['name'] ?? ''))
    ), 200);

    $nameTokens = [];
    $rawNameTokens = $source['telegram_name_tokens'] ?? ($source['nameTokens'] ?? null);
    if (is_array($rawNameTokens)) {
        foreach ($rawNameTokens as $token) {
            $normalizedToken = sanitize_text_field((string) $token, 80);
            if ($normalizedToken !== '') {
                $nameTokens[] = mb_strtolower($normalizedToken, 'UTF-8');
            }
        }
    }

    if (empty($nameTokens) && $fullName !== '') {
        $nameTokens = split_name_tokens($fullName);
    }

    $nameTokens = array_values(array_unique(array_filter($nameTokens, static function ($token) {
        return is_string($token) && $token !== '';
    })));

    if (empty($ids) && $username === '' && empty($nameTokens) && $fullName === '') {
        return null;
    }

    $filter = [];
    if (!empty($ids)) {
        $filter['ids'] = array_values(array_unique($ids));
    }
    if ($username !== '') {
        $filter['username'] = $username;
    }
    if (!empty($nameTokens)) {
        $filter['nameTokens'] = $nameTokens;
    }
    if ($fullName !== '') {
        $filter['fullName'] = $fullName;
    }

    return $filter;
}

function assignee_filter_has_identity(?array $filter): bool
{
    if ($filter === null || empty($filter)) {
        return false;
    }

    if (isset($filter['ids']) && is_array($filter['ids'])) {
        foreach ($filter['ids'] as $id) {
            if (normalize_identifier_value($id) !== '') {
                return true;
            }
        }
    }

    if (!empty($filter['username']) && normalize_username_value($filter['username']) !== '') {
        return true;
    }

    if (!empty($filter['fullName']) && docs_normalize_name_candidate_value($filter['fullName']) !== '') {
        return true;
    }

    if (isset($filter['nameTokens']) && is_array($filter['nameTokens'])) {
        foreach ($filter['nameTokens'] as $token) {
            if (trim((string) $token) !== '') {
                return true;
            }
        }
    }

    return false;
}

function extract_assignee_match_data(array $record): array
{
    $data = [
        'ids' => [],
        'usernames' => [],
        'names' => [],
    ];

    $assignees = docs_extract_assignees($record);
    if (isset($record['subordinates']) && is_array($record['subordinates'])) {
        foreach ($record['subordinates'] as $subordinateEntry) {
            if (is_array($subordinateEntry)) {
                $assignees[] = $subordinateEntry;
            }
        }
    }
    if (isset($record['responsibles']) && is_array($record['responsibles'])) {
        foreach ($record['responsibles'] as $responsibleEntry) {
            if (is_array($responsibleEntry)) {
                $assignees[] = $responsibleEntry;
            }
        }
    }
    if (isset($record['director']) && is_array($record['director'])) {
        $assignees[] = $record['director'];
    }
    if (isset($record['directors']) && is_array($record['directors'])) {
        foreach ($record['directors'] as $directorEntry) {
            if (is_array($directorEntry)) {
                $assignees[] = $directorEntry;
            }
        }
    }
    foreach (['responsible', 'subordinate', 'director', 'assignee'] as $singleKey) {
        if (!array_key_exists($singleKey, $record)) {
            continue;
        }
        if (is_array($record[$singleKey])) {
            $assignees[] = $record[$singleKey];
            continue;
        }
        $singleName = sanitize_text_field((string) $record[$singleKey], 200);
        if ($singleName !== '') {
            $assignees[] = [
                'id' => $singleName,
                'username' => $singleName,
                'name' => $singleName,
            ];
        }
    }

    $idFields = ['id', 'chatId', 'chat_id', 'telegram', 'email', 'number', 'login'];
    $usernameFields = ['username', 'userName', 'telegramUsername', 'telegram_username'];
    $nameFields = ['name', 'responsible', 'fio', 'fullName', 'displayName'];
    foreach ($assignees as $assignee) {
        if (!is_array($assignee)) {
            continue;
        }

        foreach ($idFields as $field) {
            if (!isset($assignee[$field])) {
                continue;
            }

            $normalized = normalize_identifier_value($assignee[$field]);
            if ($normalized === '') {
                continue;
            }

            $data['ids'][] = $normalized;
            $username = normalize_username_value($normalized);
            if ($username !== '') {
                $data['usernames'][] = $username;
            }
        }

        foreach ($usernameFields as $field) {
            if (!isset($assignee[$field])) {
                continue;
            }

            $username = normalize_username_value($assignee[$field]);
            if ($username !== '') {
                $data['usernames'][] = $username;
            }
        }

        foreach ($nameFields as $field) {
            if (!isset($assignee[$field])) {
                continue;
            }

            $sanitized = sanitize_text_field((string) $assignee[$field], 200);
            if ($sanitized === '') {
                continue;
            }

            $tokens = split_name_tokens($sanitized);
            if (!empty($tokens)) {
                $data['names'][] = $tokens;
            }
        }

        $compositeName = $assignee['responsible'] ?? ($assignee['name'] ?? '');
        $compositeKey = docs_build_responsible_composite_key($assignee['number'] ?? '', $compositeName);
        if ($compositeKey !== '') {
            $data['ids'][] = 'combo::' . $compositeKey;
        }
    }

    if (isset($record['assigneeId'])) {
        $normalized = normalize_identifier_value($record['assigneeId']);
        if ($normalized !== '') {
            $data['ids'][] = $normalized;
        }
    }

    $data['ids'] = array_values(array_unique($data['ids']));
    $data['usernames'] = array_values(array_unique($data['usernames']));
    $data['names'] = array_values($data['names']);

    return $data;
}

function document_matches_assignee_filter_core(array $record, array $filter, ?array &$trace = null): bool
{
    if (empty($filter)) {
        if ($trace !== null) {
            $trace = array_merge($trace, [
                'matchedBy' => 'no-filter',
                'matchedValue' => null,
                'candidateIds' => [],
                'candidateUsernames' => [],
                'candidateNames' => [],
            ]);
        }
        return true;
    }

    $matchData = extract_assignee_match_data($record);

    if ($trace !== null) {
        $trace['candidateIds'] = array_slice($matchData['ids'], 0, 10);
        $trace['candidateUsernames'] = array_slice($matchData['usernames'], 0, 10);
        $trace['candidateNames'] = array_map(static function (array $tokens) {
            return implode(' ', $tokens);
        }, array_slice($matchData['names'], 0, 10));
        $trace['matchedBy'] = null;
        $trace['matchedValue'] = null;
    }

    if (!empty($filter['ids'])) {
        foreach ($filter['ids'] as $expectedId) {
            $normalizedExpected = normalize_identifier_value($expectedId);
            if ($normalizedExpected === '') {
                continue;
            }
            foreach ($matchData['ids'] as $candidateId) {
                if ($candidateId === $normalizedExpected) {
                    if ($trace !== null) {
                        $trace['matchedBy'] = 'id';
                        $trace['matchedValue'] = $normalizedExpected;
                    }
                    return true;
                }
            }
        }
    }

    if (!empty($filter['username'])) {
        $expectedUsername = normalize_username_value($filter['username']);
        foreach ($matchData['usernames'] as $candidateUsername) {
            if ($expectedUsername !== '' && $candidateUsername === $expectedUsername) {
                if ($trace !== null) {
                    $trace['matchedBy'] = 'username';
                    $trace['matchedValue'] = $candidateUsername;
                }
                return true;
            }
        }
    }

    if (!empty($filter['nameTokens'])) {
        $expectedTokens = array_values(array_filter(array_map(static function ($token) {
            return mb_strtolower(trim((string) $token), 'UTF-8');
        }, (array) $filter['nameTokens'])));
        foreach ($matchData['names'] as $candidateTokens) {
            if (!empty($expectedTokens) && empty(array_diff($expectedTokens, $candidateTokens))) {
                if ($trace !== null) {
                    $trace['matchedBy'] = 'nameTokens';
                    $trace['matchedValue'] = implode(' ', $candidateTokens);
                }
                return true;
            }
        }
    }

    if (!empty($filter['fullName'])) {
        $expectedName = docs_normalize_name_candidate_value($filter['fullName']);
        foreach ($matchData['names'] as $candidateTokens) {
            $candidateName = docs_normalize_name_candidate_value(implode(' ', $candidateTokens));
            if ($expectedName !== '' && $candidateName === $expectedName) {
                if ($trace !== null) {
                    $trace['matchedBy'] = 'fullName';
                    $trace['matchedValue'] = $candidateName;
                }
                return true;
            }
        }
    }

    if ($trace !== null) {
        $trace['matchedBy'] = $trace['matchedBy'] ?? null;
        $trace['matchedValue'] = $trace['matchedValue'] ?? null;
    }

    return false;
}

function normalize_responsible_name(?string $value): string
{
    if ($value === null) {
        return '';
    }

    $sanitized = sanitize_text_field($value, 200);

    return $sanitized === '' ? '' : mb_strtolower($sanitized, 'UTF-8');
}

function find_responsible_entry_for_record(array $record, array $responsibles): ?array
{
    if (empty($responsibles)) {
        return null;
    }

    $candidateIds = [];
    $candidateNames = [];
    $assignees = docs_extract_assignees($record);

    foreach ($assignees as $assignee) {
        if (!is_array($assignee)) {
            continue;
        }

        foreach (['id', 'chatId', 'chat_id', 'telegram'] as $field) {
            if (!isset($assignee[$field])) {
                continue;
            }

            $normalized = normalize_identifier_value($assignee[$field]);
            if ($normalized !== '') {
                $candidateIds[] = $normalized;
            }
        }

        foreach (['name', 'responsible'] as $field) {
            if (!isset($assignee[$field])) {
                continue;
            }

            $normalizedName = normalize_responsible_name((string) $assignee[$field]);
            if ($normalizedName !== '') {
                $candidateNames[] = $normalizedName;
            }
        }
    }

    if (isset($record['assigneeId'])) {
        $normalized = normalize_identifier_value($record['assigneeId']);
        if ($normalized !== '') {
            $candidateIds[] = $normalized;
        }
    }

    foreach ($responsibles as $entry) {
        if (!is_array($entry)) {
            continue;
        }

        foreach (['id', 'number', 'telegram', 'chatId', 'email'] as $field) {
            if (!isset($entry[$field])) {
                continue;
            }

            $normalized = normalize_identifier_value($entry[$field]);
            if ($normalized === '') {
                continue;
            }

            foreach ($candidateIds as $candidate) {
                if ($candidate === $normalized) {
                    return $entry;
                }
            }
        }

        if (!empty($candidateNames) && isset($entry['responsible'])) {
            $entryName = normalize_responsible_name((string) $entry['responsible']);
            if ($entryName === '') {
                continue;
            }

            foreach ($candidateNames as $candidateName) {
                if ($candidateName === $entryName) {
                    return $entry;
                }
            }
        }
    }

    return null;
}

function summarize_responsible_for_log(array $responsible): array
{
    $summary = [];
    foreach (['number', 'responsible', 'telegram', 'chatId', 'email', 'department', 'note'] as $field) {
        if (!isset($responsible[$field])) {
            continue;
        }

        $value = trim((string) $responsible[$field]);
        if ($value === '') {
            continue;
        }

        $summary[$field] = $value;
    }

    return $summary;
}

function merge_record_with_responsible(array $record, array $responsible): array
{
    $merged = $record;
    $assignees = docs_extract_assignees($merged);
    $assignee = $assignees[0] ?? [];

    if ((!isset($assignee['name']) || $assignee['name'] === '') && !empty($responsible['responsible'])) {
        $assignee['name'] = $responsible['responsible'];
    }

    $map = [
        'department' => 'department',
        'position' => 'position',
        'telegram' => 'telegram',
        'chatId' => 'chatId',
        'email' => 'email',
        'note' => 'note',
    ];

    foreach ($map as $targetField => $sourceField) {
        if (!isset($assignee[$targetField]) || $assignee[$targetField] === '') {
            if (!empty($responsible[$sourceField])) {
                $assignee[$targetField] = $responsible[$sourceField];
            }
        }
    }

    if ((!isset($assignee['id']) || $assignee['id'] === '') && !empty($responsible['telegram'])) {
        $assignee['id'] = $responsible['telegram'];
    } elseif ((!isset($assignee['id']) || $assignee['id'] === '') && !empty($responsible['chatId'])) {
        $assignee['id'] = $responsible['chatId'];
    } elseif ((!isset($assignee['id']) || $assignee['id'] === '') && !empty($responsible['number'])) {
        $assignee['id'] = $responsible['number'];
    }

    $primarySanitized = sanitize_assignee_payload($assignee, false);
    if (empty($primarySanitized)) {
        $remaining = [];
        foreach (array_slice($assignees, 1) as $extra) {
            $sanitized = sanitize_assignee_payload($extra, false);
            if (!empty($sanitized)) {
                $remaining[] = $sanitized;
            }
        }
        docs_apply_assignees_to_record($merged, $remaining);
        return $merged;
    }

    if (!isset($primarySanitized['assignedAt']) || $primarySanitized['assignedAt'] === '') {
        $primarySanitized['assignedAt'] = date('c');
    }

    $normalizedAssignees = [$primarySanitized];
    foreach (array_slice($assignees, 1) as $extra) {
        $sanitized = sanitize_assignee_payload($extra, false);
        if (!empty($sanitized)) {
            $normalizedAssignees[] = $sanitized;
        }
    }

    docs_apply_assignees_to_record($merged, $normalizedAssignees);

    return $merged;
}

function document_matches_assignee_filter(array $record, array $filter, array $responsibles = [], ?array &$debugTrace = null): bool
{
    $coreTrace = [];
    if (document_matches_assignee_filter_core($record, $filter, $coreTrace)) {
        if ($debugTrace !== null) {
            $debugTrace = array_merge($coreTrace, [
                'resolvedViaResponsible' => false,
                'matchedResponsible' => null,
            ]);
        }

        return true;
    }

    if ($debugTrace !== null) {
        $debugTrace = array_merge($coreTrace, [
            'resolvedViaResponsible' => false,
            'matchedResponsible' => null,
        ]);
    }

    if (empty($responsibles)) {
        return false;
    }

    $matchedResponsible = find_responsible_entry_for_record($record, $responsibles);
    if ($matchedResponsible === null) {
        return false;
    }

    $augmentedRecord = merge_record_with_responsible($record, $matchedResponsible);

    $augmentedTrace = [];
    $matched = document_matches_assignee_filter_core($augmentedRecord, $filter, $augmentedTrace);

    if ($debugTrace !== null) {
        $debugTrace = array_merge($augmentedTrace, [
            'resolvedViaResponsible' => true,
            'matchedResponsible' => summarize_responsible_for_log($matchedResponsible),
        ]);
    }

    return $matched;
}

function docs_should_trace_mini_app_user(?array $filter): bool
{
    if ($filter === null || empty($filter['ids']) || !is_array($filter['ids'])) {
        return false;
    }

    return in_array('807550434', $filter['ids'], true);
}

function docs_trace_mini_app_task_visibility(
    array $record,
    array $filter,
    array $responsibles,
    string $organization,
    string $folder,
    string $stage
): void {
    $recordId = isset($record['id']) ? (string) $record['id'] : '';
    if ($recordId !== 'doc_a012f5b66c5d0a3f') {
        return;
    }

    $trace = [];
    $matched = document_matches_assignee_filter($record, $filter, $responsibles, $trace);
    $assignees = docs_extract_assignees($record);
    $assigneeSummary = [];
    foreach ($assignees as $entry) {
        if (!is_array($entry)) {
            continue;
        }
        $assigneeSummary[] = array_filter([
            'id' => $entry['id'] ?? null,
            'telegram' => $entry['telegram'] ?? null,
            'chatId' => $entry['chatId'] ?? null,
            'login' => $entry['login'] ?? null,
            'name' => $entry['name'] ?? null,
            'responsible' => $entry['responsible'] ?? null,
        ], static function ($value) {
            return $value !== null && $value !== '';
        });
    }

    docs_write_mini_app_debug_log('Mini app task visibility trace', [
        'stage' => $stage,
        'organization' => $organization,
        'folder' => $folder,
        'recordId' => $recordId,
        'entryNumber' => $record['entryNumber'] ?? null,
        'status' => $record['status'] ?? null,
        'assignees' => $assigneeSummary,
        'filter' => summarize_assignee_filter_for_log($filter),
        'matched' => $matched,
        'trace' => $trace,
    ]);
}

function summarize_assignee_filter_for_log(?array $filter): array
{
    if ($filter === null) {
        return ['applied' => false];
    }

    $summary = ['applied' => true];

    if (isset($filter['ids']) && is_array($filter['ids'])) {
        $summary['ids'] = array_slice(array_values(array_map('strval', $filter['ids'])), 0, 10);
        $summary['idsCount'] = count($filter['ids']);
    }

    if (!empty($filter['username'])) {
        $summary['username'] = (string) $filter['username'];
    }

    if (!empty($filter['fullName'])) {
        $summary['fullName'] = (string) $filter['fullName'];
    }

    if (isset($filter['nameTokens']) && is_array($filter['nameTokens'])) {
        $summary['nameTokens'] = array_slice(array_values(array_map('strval', $filter['nameTokens'])), 0, 10);
        $summary['nameTokensCount'] = count($filter['nameTokens']);
    }

    return $summary;
}

function filter_documents_for_assignee(array $records, ?array $filter, array $responsibles = []): array
{
    if ($filter === null) {
        $filtered = [];
        foreach ($records as $record) {
            if (is_array($record)) {
                $filtered[] = $record;
            }
        }

        log_docs_event('Assignee filter skipped', [
            'recordsCount' => count($filtered),
            'responsiblesCount' => count($responsibles),
        ]);

        return $filtered;
    }

    $filterSummary = summarize_assignee_filter_for_log($filter);
    $totalSupplied = count($records);

    log_docs_event('Assignee filter started', [
        'recordsCount' => $totalSupplied,
        'responsiblesCount' => count($responsibles),
        'filter' => $filterSummary,
    ]);

    $filtered = [];
    $samples = [];
    $checked = 0;

    foreach ($records as $record) {
        if (!is_array($record)) {
            continue;
        }

        $checked++;

        $debugTrace = [];
        $matched = document_matches_assignee_filter($record, $filter, $responsibles, $debugTrace);
        if ($matched) {
            $filtered[] = $record;
        }

        if (count($samples) < 15) {
            $assignees = docs_extract_assignees($record);
            $primaryAssignee = $assignees[0] ?? [];

            $recordSummary = [
                'matched' => $matched,
            ];

            if (isset($record['id'])) {
                $recordSummary['id'] = (string) $record['id'];
            }
            if (isset($record['entryNumber'])) {
                $recordSummary['entryNumber'] = (string) $record['entryNumber'];
            }
            if (!empty($record['status'])) {
                $recordSummary['status'] = (string) $record['status'];
            }

            $assigneeId = null;
            foreach (['id', 'telegram', 'chatId'] as $field) {
                if (!empty($primaryAssignee[$field])) {
                    $assigneeId = (string) $primaryAssignee[$field];
                    break;
                }
            }
            if ($assigneeId === null && !empty($record['assigneeId'])) {
                $assigneeId = (string) $record['assigneeId'];
            }
            if ($assigneeId !== null) {
                $recordSummary['assigneeId'] = $assigneeId;
            }

            $assigneeName = $primaryAssignee['name']
                ?? $primaryAssignee['responsible']
                ?? ($record['responsible'] ?? null);
            if (!empty($assigneeName)) {
                $recordSummary['assigneeName'] = (string) $assigneeName;
            }

            if (!empty($assignees)) {
                $recordSummary['assigneesCount'] = count($assignees);
                $namesSample = [];
                foreach (array_slice($assignees, 0, 3) as $assigneeEntry) {
                    if (!is_array($assigneeEntry)) {
                        continue;
                    }
                    $nameCandidate = $assigneeEntry['name']
                        ?? $assigneeEntry['responsible']
                        ?? ($assigneeEntry['email'] ?? null);
                    if (!empty($nameCandidate)) {
                        $namesSample[] = (string) $nameCandidate;
                    }
                }
                if (!empty($namesSample)) {
                    $recordSummary['assigneesSample'] = $namesSample;
                }
            }

            if (!empty($debugTrace)) {
                if (array_key_exists('matchedBy', $debugTrace)) {
                    $recordSummary['matchedBy'] = $debugTrace['matchedBy'];
                }
                if (!empty($debugTrace['matchedValue'])) {
                    $recordSummary['matchedValue'] = $debugTrace['matchedValue'];
                }
                if (!empty($debugTrace['candidateIds'])) {
                    $recordSummary['candidateIds'] = array_slice($debugTrace['candidateIds'], 0, 5);
                }
                if (!empty($debugTrace['candidateUsernames'])) {
                    $recordSummary['candidateUsernames'] = array_slice($debugTrace['candidateUsernames'], 0, 5);
                }
                if (!empty($debugTrace['candidateNames'])) {
                    $recordSummary['candidateNames'] = array_slice($debugTrace['candidateNames'], 0, 5);
                }
                if (array_key_exists('resolvedViaResponsible', $debugTrace)) {
                    $recordSummary['resolvedViaResponsible'] = $debugTrace['resolvedViaResponsible'];
                }
                if (!empty($debugTrace['matchedResponsible'])) {
                    $recordSummary['matchedResponsible'] = $debugTrace['matchedResponsible'];
                }
            }

            $samples[] = $recordSummary;
        }
    }

    $logContext = [
        'recordsChecked' => $checked,
        'recordsMatched' => count($filtered),
        'recordsSupplied' => $totalSupplied,
        'recordsSkipped' => max(0, $totalSupplied - $checked),
        'responsiblesCount' => count($responsibles),
        'filter' => $filterSummary,
    ];

    if (!empty($filtered)) {
        $matchedSamples = [];
        foreach ($filtered as $record) {
            if (!is_array($record)) {
                continue;
            }

            $matchedSamples[] = summarize_document_record_for_log($record);
            if (count($matchedSamples) >= 10) {
                break;
            }
        }

        if (!empty($matchedSamples)) {
            $logContext['matchedSamples'] = $matchedSamples;
        }
    }

    if (!empty($samples)) {
        $logContext['samples'] = $samples;
    }

    log_docs_event('Assignee filter completed', $logContext);

    return $filtered;
}

function load_admin_settings(string $folder): array
{
    $defaults = [
        'responsibles' => [],
        'block2' => [],
        'block3' => [],
        'columnWidths' => [],
        'columnOrders' => [],
        'outgoingColumnOrders' => [],
        'ordersColumnOrders' => [],
        'tablePreferences' => [],
    ];

    $file = get_settings_path($folder);
    if (!is_file($file)) {
        return $defaults;
    }

    $raw = file_get_contents($file);
    if ($raw === false || trim($raw) === '') {
        return $defaults;
    }

    $decoded = json_decode($raw, true);
    if (!is_array($decoded)) {
        return $defaults;
    }

    $sanitized = sanitize_admin_settings($decoded + $defaults);
    $sanitized['columnWidths'] = isset($decoded['columnWidths'])
        ? docs_normalize_column_width_map($decoded['columnWidths'])
        : [];
    $sanitized['columnOrders'] = isset($decoded['columnOrders'])
        ? docs_normalize_column_order_map($decoded['columnOrders'])
        : [];
    $sanitized['outgoingColumnOrders'] = isset($decoded['outgoingColumnOrders'])
        ? docs_normalize_outgoing_column_order_map($decoded['outgoingColumnOrders'])
        : [];
    $sanitized['ordersColumnOrders'] = isset($decoded['ordersColumnOrders'])
        ? docs_normalize_orders_column_order_map($decoded['ordersColumnOrders'])
        : [];
    $sanitized['tablePreferences'] = isset($decoded['tablePreferences'])
        ? docs_normalize_table_preferences_map($decoded['tablePreferences'])
        : [];

    return $sanitized + [
        'columnWidths' => [],
        'columnOrders' => [],
        'outgoingColumnOrders' => [],
        'ordersColumnOrders' => [],
        'tablePreferences' => [],
    ];
}

function load_responsibles_for_folder(string $folder): array
{
    $settings = load_admin_settings($folder);

    $responsibles = [];
    if (isset($settings['responsibles']) && is_array($settings['responsibles'])) {
        $responsibles = $settings['responsibles'];
    }

    if (isset($settings['block3']) && is_array($settings['block3'])) {
        foreach ($settings['block3'] as $entry) {
            if (is_array($entry)) {
                $responsibles[] = $entry;
            }
        }
    }

    return $responsibles;
}

function docs_find_theme_mode_for_telegram_user(array $settings, string $telegramUserId): string
{
    $normalizedUserId = normalize_identifier_value($telegramUserId);
    if ($normalizedUserId === '') {
        return '';
    }

    foreach (['responsibles', 'block2', 'block3'] as $groupKey) {
        if (!isset($settings[$groupKey]) || !is_array($settings[$groupKey])) {
            continue;
        }

        foreach ($settings[$groupKey] as $entry) {
            if (!is_array($entry)) {
                continue;
            }

            $entryTelegramId = normalize_identifier_value($entry['telegram'] ?? ($entry['chatId'] ?? ($entry['id'] ?? '')));
            if ($entryTelegramId === '' || $entryTelegramId !== $normalizedUserId) {
                continue;
            }

            $mode = docs_normalize_theme_mode($entry['theme'] ?? '');
            if ($mode !== '') {
                return $mode;
            }
        }
    }

    return '';
}

function docs_save_theme_mode_for_telegram_user(array &$settings, string $telegramUserId, string $themeMode): bool
{
    $normalizedUserId = normalize_identifier_value($telegramUserId);
    $normalizedTheme = docs_normalize_theme_mode($themeMode);
    if ($normalizedUserId === '' || $normalizedTheme === '') {
        return false;
    }

    $updated = false;
    foreach (['responsibles', 'block2', 'block3'] as $groupKey) {
        if (!isset($settings[$groupKey]) || !is_array($settings[$groupKey])) {
            continue;
        }

        foreach ($settings[$groupKey] as $index => $entry) {
            if (!is_array($entry)) {
                continue;
            }

            $entryTelegramId = normalize_identifier_value($entry['telegram'] ?? ($entry['chatId'] ?? ($entry['id'] ?? '')));
            if ($entryTelegramId === '' || $entryTelegramId !== $normalizedUserId) {
                continue;
            }

            $settings[$groupKey][$index]['theme'] = $normalizedTheme;
            $updated = true;
        }
    }

    return $updated;
}

function docs_normalize_identifier_candidate_value($value): string
{
    $normalized = normalize_identifier_value($value);
    if ($normalized === '') {
        return '';
    }

    if ($normalized[0] === '@') {
        $normalized = substr($normalized, 1);
    }

    return mb_strtolower($normalized, 'UTF-8');
}

function docs_normalize_name_candidate_value($value): string
{
    if ($value === null) {
        return '';
    }

    $string = trim((string) $value);
    if ($string === '') {
        return '';
    }

    return mb_strtolower($string, 'UTF-8');
}

function docs_normalize_responsible_composite_key_value(string $value): string
{
    $normalized = trim($value);
    if ($normalized === '') {
        return '';
    }

    if (stripos($normalized, 'combo::') === 0) {
        $normalized = substr($normalized, 7);
    }

    $normalized = mb_strtolower($normalized, 'UTF-8');
    $normalized = preg_replace('/[^\p{L}\p{N}]+/u', '', $normalized);

    return $normalized === null ? '' : $normalized;
}

function docs_build_responsible_composite_key($number, $responsible): string
{
    $normalizedNumber = normalize_identifier_value($number);
    $normalizedResponsible = $responsible === null ? '' : trim((string) $responsible);

    if ($normalizedNumber === '' || $normalizedResponsible === '') {
        return '';
    }

    $combined = $normalizedNumber . ' ' . $normalizedResponsible;

    return docs_normalize_responsible_composite_key_value($combined);
}

function docs_entry_matches_candidate(array $entry, string $candidate): bool
{
    $normalizedId = docs_normalize_identifier_candidate_value($candidate);
    if ($normalizedId !== '') {
        foreach (['telegram', 'chatId', 'chat_id', 'id', 'userId', 'user_id', 'number', 'email', 'login', 'username', 'userName', 'telegramUsername', 'telegram_username'] as $field) {
            if (!isset($entry[$field])) {
                continue;
            }
            $value = docs_normalize_identifier_candidate_value($entry[$field]);
            if ($value !== '' && $value === $normalizedId) {
                return true;
            }
        }
    }

    $normalizedName = docs_normalize_name_candidate_value($candidate);
    if ($normalizedName !== '') {
        foreach (['responsible', 'name', 'fio', 'fullName', 'displayName'] as $field) {
            if (!isset($entry[$field])) {
                continue;
            }
            $entryName = docs_normalize_name_candidate_value($entry[$field]);
            if ($entryName !== '' && $entryName === $normalizedName) {
                return true;
            }
        }
    }

    $normalizedCompositeCandidate = docs_normalize_responsible_composite_key_value($candidate);
    if ($normalizedCompositeCandidate !== '') {
        $entryName = $entry['responsible'] ?? ($entry['name'] ?? '');
        $compositeEntryKey = docs_build_responsible_composite_key($entry['number'] ?? '', $entryName);
        if ($compositeEntryKey !== '' && $compositeEntryKey === $normalizedCompositeCandidate) {
            return true;
        }
    }

    return false;
}

function docs_collect_record_responsible_candidates(array $record): array
{
    $candidates = [];

    $assignees = docs_extract_assignees($record);
    foreach ($assignees as $assignee) {
        if (!is_array($assignee)) {
            continue;
        }

        foreach (['id', 'chatId', 'chat_id', 'telegram', 'number', 'email', 'login'] as $field) {
            if (empty($assignee[$field])) {
                continue;
            }

            $candidates[] = (string) $assignee[$field];
        }

        foreach (['name', 'responsible', 'fio'] as $field) {
            if (empty($assignee[$field])) {
                continue;
            }

            $candidates[] = (string) $assignee[$field];
        }

        if (!empty($assignee['number'])) {
            $responsibleName = $assignee['responsible'] ?? ($assignee['name'] ?? '');
            if ($responsibleName !== '') {
                $candidates[] = trim((string) $assignee['number'] . ' ' . (string) $responsibleName);
            }
        }
    }

    if (!empty($record['assigneeId'])) {
        $candidates[] = (string) $record['assigneeId'];
    }

    if (isset($record['assigneeIds']) && is_array($record['assigneeIds'])) {
        foreach ($record['assigneeIds'] as $value) {
            if ($value === null || $value === '') {
                continue;
            }

            $candidates[] = (string) $value;
        }
    }

    if (!empty($record['responsible'])) {
        $candidates[] = (string) $record['responsible'];
    }

    if (!empty($record['number']) && !empty($record['responsible'])) {
        $candidates[] = trim((string) $record['number'] . ' ' . (string) $record['responsible']);
    }

    if (isset($record['responsibles']) && is_array($record['responsibles'])) {
        foreach ($record['responsibles'] as $entry) {
            if (is_array($entry)) {
                foreach (['responsible', 'name', 'fio'] as $field) {
                    if (!empty($entry[$field])) {
                        $candidates[] = (string) $entry[$field];
                    }
                }

                foreach (['id', 'chatId', 'chat_id', 'telegram', 'number', 'email', 'login'] as $field) {
                    if (!empty($entry[$field])) {
                        $candidates[] = (string) $entry[$field];
                    }
                }

                if (!empty($entry['number'])) {
                    $responsibleName = $entry['responsible'] ?? ($entry['name'] ?? '');
                    if ($responsibleName !== '') {
                        $candidates[] = trim((string) $entry['number'] . ' ' . (string) $responsibleName);
                    }
                }
            } elseif ($entry !== null && $entry !== '') {
                $candidates[] = (string) $entry;
            }
        }
    }

    $filtered = array_filter(array_map(static function ($value) {
        $trimmed = trim((string) $value);

        return $trimmed === '' ? null : $trimmed;
    }, $candidates));

    return array_values(array_unique($filtered));
}

function docs_record_is_active(array $record): bool
{
    $status = isset($record['status']) ? sanitize_text_field((string) $record['status'], 120) : '';

    if ($status === '') {
        return true;
    }

    $normalized = mb_strtolower($status, 'UTF-8');
    $inactiveTokens = ['выполн', 'отмен', 'заверш', 'done', 'cancel', 'закрыт'];

    foreach ($inactiveTokens as $token) {
        if (mb_strpos($normalized, $token) !== false) {
            return false;
        }
    }

    return true;
}

function docs_enrich_responsibles_with_counts(array $responsibles, array $records): array
{
    if (empty($responsibles) || empty($records)) {
        return $responsibles;
    }

    $totals = [];
    $seen = [];

    foreach ($records as $index => $record) {
        if (!is_array($record)) {
            continue;
        }

        $candidates = docs_collect_record_responsible_candidates($record);
        if (empty($candidates)) {
            continue;
        }

        $keyParts = [];
        if (!empty($record['id'])) {
            $keyParts[] = (string) $record['id'];
        }
        if (!empty($record['organization'])) {
            $keyParts[] = (string) $record['organization'];
        }
        if (!empty($record['registryNumber'])) {
            $keyParts[] = (string) $record['registryNumber'];
        }
        if (empty($keyParts)) {
            $keyParts[] = (string) $index;
        }

        $recordKey = implode('|', $keyParts);
        $isActive = docs_record_is_active($record);

        foreach ($responsibles as $responsibleIndex => $entry) {
            if (!is_array($entry)) {
                continue;
            }

            $matched = false;
            foreach ($candidates as $candidate) {
                if (docs_entry_matches_candidate($entry, $candidate)) {
                    $matched = true;
                    break;
                }
            }

            if (!$matched) {
                continue;
            }

            if (!isset($seen[$responsibleIndex])) {
                $seen[$responsibleIndex] = [];
                $totals[$responsibleIndex] = ['total' => 0, 'active' => 0];
            }

            if (isset($seen[$responsibleIndex][$recordKey])) {
                continue;
            }

            $seen[$responsibleIndex][$recordKey] = true;
            $totals[$responsibleIndex]['total']++;
            if ($isActive) {
                $totals[$responsibleIndex]['active']++;
            }
        }
    }

    foreach ($responsibles as $responsibleIndex => &$entry) {
        if (!is_array($entry)) {
            continue;
        }

        if (isset($totals[$responsibleIndex])) {
            $entry['totalCount'] = $totals[$responsibleIndex]['total'];
            $entry['activeCount'] = $totals[$responsibleIndex]['active'];
            if (!isset($entry['count']) || !is_numeric($entry['count'])) {
                $entry['count'] = $totals[$responsibleIndex]['active'];
            }
        } else {
            $entry['totalCount'] = $entry['totalCount'] ?? 0;
            $entry['activeCount'] = $entry['activeCount'] ?? 0;
            if (!isset($entry['count'])) {
                $entry['count'] = 0;
            }
        }
    }
    unset($entry);

    return $responsibles;
}

function docs_build_subordinate_directory(array $subordinates, array $responsibles): array
{
    $merged = $subordinates;

    foreach ($responsibles as $responsible) {
        if (!is_array($responsible)) {
            continue;
        }

        $entry = $responsible;
        $entry['role'] = 'subordinate';
        $merged[] = $entry;
    }

    if (empty($merged)) {
        return [];
    }

    return docs_filter_unique_assignees_by_primary_keys($merged);
}

function docs_user_is_block2_member(array $block2, array $requestContext): bool
{
    if (empty($block2)) {
        return false;
    }

    $userCandidates = docs_collect_request_identity_candidates($requestContext);
    $filter = [
        'ids' => $userCandidates['ids'] ?? [],
        'username' => '',
        'fullName' => '',
        'nameTokens' => [],
    ];

    if (empty($filter['ids']) || !is_array($filter['ids'])) {
        return false;
    }

    foreach ($block2 as $entry) {
        if (!is_array($entry)) {
            continue;
        }

        if (docs_director_participant_matches_filter($entry, $filter)) {
            return true;
        }
    }

    return false;
}

function docs_user_can_manage_instructions(?string $organization, array $requestContext, ?array $sessionAuth = null, ?array $block2 = null): bool
{
    $sessionRole = '';
    if (is_array($sessionAuth) && isset($sessionAuth['role'])) {
        $sessionRole = strtolower((string) $sessionAuth['role']);
    }

    if ($block2 === null) {
        if ($organization === null || $organization === '') {
            return false;
        }

        $folder = sanitize_folder_name($organization);
        $settings = load_admin_settings($folder);
        $block2 = isset($settings['block2']) && is_array($settings['block2'])
            ? $settings['block2']
            : [];
    }

    if (empty($block2)) {
        return false;
    }

    return docs_user_is_block2_member($block2, $requestContext);
}

function docs_user_can_manage_subordinates(?array $sessionAuth): bool
{
    if (!is_array($sessionAuth)) {
        return false;
    }

    $role = strtolower((string) ($sessionAuth['role'] ?? ''));
    if ($role === 'admin') {
        return true;
    }

    if ($role !== 'user') {
        return false;
    }

    $responsibleRole = strtolower((string) ($sessionAuth['responsibleRole'] ?? ''));
    if ($responsibleRole === '') {
        return false;
    }

    $allowed = [
        'director',
        'responsible',
        'administrator',
        'admin',
        'директор',
        'ответственный',
        'администратор',
        'руководитель',
    ];

    return in_array($responsibleRole, $allowed, true);
}

function docs_collect_session_auth_candidates(array $sessionAuth): array
{
    $candidates = [];

    $pushCandidate = static function ($value) use (&$candidates): void {
        if ($value === null) {
            return;
        }

        if (is_scalar($value)) {
            $string = trim((string) $value);
            if ($string !== '') {
                $candidates[] = $string;
            }
            return;
        }

        if (is_array($value)) {
            foreach ($value as $nested) {
                if (is_scalar($nested)) {
                    $string = trim((string) $nested);
                    if ($string !== '') {
                        $candidates[] = $string;
                    }
                }
            }
        }
    };

    $identifierFields = ['login', 'telegramId', 'chatId', 'responsibleNumber', 'id', 'userId', 'username'];
    foreach ($identifierFields as $field) {
        if (isset($sessionAuth[$field])) {
            $pushCandidate($sessionAuth[$field]);
        }
    }

    if (isset($sessionAuth['fullName'])) {
        $pushCandidate($sessionAuth['fullName']);
    }

    $firstName = isset($sessionAuth['firstName']) ? (string) $sessionAuth['firstName'] : '';
    $lastName = isset($sessionAuth['lastName']) ? (string) $sessionAuth['lastName'] : '';
    if ($firstName !== '') {
        $pushCandidate($firstName);
    }
    if ($lastName !== '') {
        $pushCandidate($lastName);
    }
    $combined = trim($firstName . ' ' . $lastName);
    if ($combined !== '') {
        $pushCandidate($combined);
    }

    return array_values(array_unique($candidates));
}

function docs_session_user_is_restricted_for_deletion(?array $sessionAuth, ?array $settings): bool
{
    if (!is_array($sessionAuth) || !is_array($settings)) {
        return false;
    }

    $role = strtolower((string) ($sessionAuth['role'] ?? ''));
    if ($role !== 'admin') {
        return false;
    }

    // Администратор должен сохранять полный доступ даже если указан в списках ответственных/подчинённых.
    return false;
}

function docs_user_can_delete_documents(?array $sessionAuth, ?array $settings = null): bool
{
    if (!is_array($sessionAuth)) {
        return false;
    }

    $role = strtolower((string) ($sessionAuth['role'] ?? ''));
    if ($role !== 'admin') {
        return false;
    }

    if (!is_array($settings)) {
        return true;
    }

    return !docs_session_user_is_restricted_for_deletion($sessionAuth, $settings);
}

function docs_user_can_create_documents(?array $sessionAuth): bool
{
    if (!is_array($sessionAuth)) {
        return false;
    }

    $role = strtolower((string) ($sessionAuth['role'] ?? ''));
    if ($role !== 'admin') {
        return false;
    }

    $adminScope = strtolower((string) ($sessionAuth['adminScope'] ?? ''));
    if ($adminScope === 'director') {
        return false;
    }

    return true;
}

function docs_resolve_column_width_owner_id(array $requestContext, ?array $sessionAuth = null): string
{
    $explicitUserKey = '';
    if (isset($requestContext['raw']) && is_array($requestContext['raw'])) {
        $explicitUserKey = (string) ($requestContext['raw']['user_key'] ?? '');
    }
    if ($explicitUserKey !== '') {
        $normalizedExplicitUserKey = trim($explicitUserKey);
        if (preg_match('/^[a-z_]+:(.+)$/iu', $normalizedExplicitUserKey, $matches) && isset($matches[1])) {
            $normalizedExplicitUserKey = (string) $matches[1];
        }
        $normalizedExplicitUserKey = docs_normalize_identifier_candidate_value($normalizedExplicitUserKey);
        if ($normalizedExplicitUserKey !== '') {
            return substr($normalizedExplicitUserKey, 0, 120);
        }
    }

    $candidates = [];

    if (is_array($sessionAuth)) {
        $candidates[] = $sessionAuth['login'] ?? '';
        $candidates[] = $sessionAuth['telegramId'] ?? '';
        $candidates[] = $sessionAuth['chatId'] ?? '';
        $candidates[] = $sessionAuth['responsibleNumber'] ?? '';
    }

    if (!empty($requestContext['primaryId'])) {
        $candidates[] = (string) $requestContext['primaryId'];
    }

    if (isset($requestContext['user']) && is_array($requestContext['user'])) {
        $requestUser = $requestContext['user'];
        $candidates[] = $requestUser['id'] ?? '';
        $candidates[] = $requestUser['username'] ?? '';
        $candidates[] = $requestUser['fullName'] ?? '';
    }

    foreach ($candidates as $candidate) {
        $normalized = docs_normalize_identifier_candidate_value((string) $candidate);
        if ($normalized !== '') {
            return substr($normalized, 0, 120);
        }
    }

    return '';
}

function docs_resolve_column_width_profile(string $organization, array $requestContext, ?array $sessionAuth = null, ?array $block2 = null): string
{
    $role = '';
    if (is_array($sessionAuth) && isset($sessionAuth['role'])) {
        $role = strtolower((string) $sessionAuth['role']);
    }

    $baseProfile = 'responsible';
    if ($role === 'admin') {
        $baseProfile = 'admin';
    } else {
        if ($block2 === null) {
            if ($organization !== '') {
                $folder = sanitize_folder_name($organization);
                $settings = load_admin_settings($folder);
                $block2 = isset($settings['block2']) && is_array($settings['block2'])
                    ? $settings['block2']
                    : [];
            } else {
                $block2 = [];
            }
        }

        if (!empty($block2) && docs_user_is_block2_member($block2, $requestContext)) {
            $baseProfile = 'director';
        }
    }

    $ownerId = docs_resolve_column_width_owner_id($requestContext, $sessionAuth);
    if ($ownerId !== '') {
        return $baseProfile . ':' . $ownerId;
    }

    return $baseProfile;
}

function docs_build_permissions_summary(?string $organization, array $requestContext, ?array $sessionAuth = null, ?array $block2 = null, ?array $settings = null): array
{
    $role = is_array($sessionAuth) ? strtolower((string) ($sessionAuth['role'] ?? '')) : '';

    $settingsForDeletion = $settings;
    if ($settingsForDeletion === null && $role === 'admin' && $organization !== null && $organization !== '') {
        static $settingsCache = [];
        $folder = sanitize_folder_name($organization);
        if (!array_key_exists($folder, $settingsCache)) {
            $settingsCache[$folder] = load_admin_settings($folder);
        }
        $settingsForDeletion = $settingsCache[$folder];
    }

    return [
        'canManageInstructions' => docs_user_can_manage_instructions($organization, $requestContext, $sessionAuth, $block2),
        'canCreateDocuments' => docs_user_can_create_documents($sessionAuth),
        'canManageSubordinates' => docs_user_can_manage_subordinates($sessionAuth),
        'canDeleteDocuments' => docs_user_can_delete_documents($sessionAuth, $settingsForDeletion),
    ];
}

function docs_collect_request_identity_candidates(array $requestContext): array
{
    $ids = [];
    $names = [];

    $pushId = static function ($value) use (&$ids): void {
        $normalized = docs_normalize_identifier_candidate_value($value);
        if ($normalized !== '') {
            $ids[$normalized] = true;
        }
    };

    $pushName = static function ($value) use (&$names): void {
        $normalized = docs_normalize_name_candidate_value($value);
        if ($normalized !== '') {
            $names[$normalized] = true;
        }
    };

    if (!empty($requestContext['primaryId'])) {
        $pushId($requestContext['primaryId']);
    }

    if (isset($requestContext['raw']) && is_array($requestContext['raw'])) {
        $raw = $requestContext['raw'];
        if (!empty($raw['telegram_user_id'])) {
            $pushId($raw['telegram_user_id']);
        }
        if (!empty($raw['telegram_chat_id'])) {
            $pushId($raw['telegram_chat_id']);
        }
        if (!empty($raw['telegram_username'])) {
            $pushId($raw['telegram_username']);
        }
        if (!empty($raw['telegram_full_name'])) {
            $pushName($raw['telegram_full_name']);
        }
    }

    if (isset($requestContext['user']) && is_array($requestContext['user'])) {
        $user = $requestContext['user'];
        if (!empty($user['id'])) {
            $pushId($user['id']);
        }
        if (!empty($user['username'])) {
            $pushId($user['username']);
        }
        if (!empty($user['fullName'])) {
            $pushName($user['fullName']);
        }
        $full = trim((string) ($user['firstName'] ?? '') . ' ' . (string) ($user['lastName'] ?? ''));
        if ($full !== '') {
            $pushName($full);
        }
    }

    if (isset($requestContext['filter']) && is_array($requestContext['filter'])) {
        $filter = $requestContext['filter'];
        if (!empty($filter['ids']) && is_array($filter['ids'])) {
            foreach ($filter['ids'] as $value) {
                $pushId($value);
            }
        }
        if (!empty($filter['username'])) {
            $pushId($filter['username']);
        }
        if (!empty($filter['fullName'])) {
            $pushName($filter['fullName']);
        }
    }

    return [
        'ids' => array_keys($ids),
        'names' => array_keys($names),
    ];
}

function docs_collect_record_assignee_candidates(array $record): array
{
    $ids = [];
    $names = [];

    $pushId = static function ($value) use (&$ids): void {
        $normalized = docs_normalize_identifier_candidate_value($value);
        if ($normalized !== '') {
            $ids[$normalized] = true;
        }
    };

    $pushName = static function ($value) use (&$names): void {
        $normalized = docs_normalize_name_candidate_value($value);
        if ($normalized !== '') {
            $names[$normalized] = true;
        }
    };

    $assignees = docs_extract_assignees($record);
    foreach ($assignees as $assignee) {
        if (!is_array($assignee)) {
            continue;
        }
        foreach (['id', 'telegram', 'chatId', 'number', 'email', 'login'] as $field) {
            if (!empty($assignee[$field])) {
                $pushId($assignee[$field]);
            }
        }
        foreach (['name', 'responsible'] as $field) {
            if (!empty($assignee[$field])) {
                $pushName($assignee[$field]);
            }
        }
    }

    if (isset($record['assigneeIds']) && is_array($record['assigneeIds'])) {
        foreach ($record['assigneeIds'] as $candidate) {
            $pushId($candidate);
        }
    }

    if (!empty($record['assigneeId'])) {
        $pushId($record['assigneeId']);
    }

    if (!empty($record['responsible'])) {
        $pushName($record['responsible']);
    }

    if (isset($record['responsibles']) && is_array($record['responsibles'])) {
        foreach ($record['responsibles'] as $candidate) {
            $pushName($candidate);
        }
    }

    return [
        'ids' => array_keys($ids),
        'names' => array_keys($names),
    ];
}

function docs_review_flow_enabled(array $record): bool
{
    return (string) ($record['reviewFlow'] ?? '') === DOCS_REVIEW_FLOW_RESPONSIBLE_SUBORDINATE;
}

function docs_normalize_subordinate_review_status($value): string
{
    $normalized = mb_strtolower(trim((string) $value), 'UTF-8');
    if ($normalized === '') {
        return '';
    }

    $map = [
        'accepted' => 'accepted',
        'accept' => 'accepted',
        'принять' => 'accepted',
        'принято' => 'accepted',
        'принят' => 'accepted',
        'revision' => 'revision',
        'rework' => 'revision',
        'revise' => 'revision',
        'на доработку' => 'revision',
        'на доработке' => 'revision',
        'доработка' => 'revision',
        'доработать' => 'revision',
    ];

    return $map[$normalized] ?? '';
}

function docs_subordinate_review_status_label(string $status): string
{
    return $status === 'accepted' ? 'Принято' : 'На доработку';
}

function docs_normalize_subordinate_submission_status($value): string
{
    $normalized = mb_strtolower(trim((string) $value), 'UTF-8');
    if ($normalized === '') {
        return '';
    }

    $map = [
        'submitted' => 'submitted',
        'submit' => 'submitted',
        'review' => 'submitted',
        'на проверке' => 'submitted',
        'на проверку' => 'submitted',
        'отправлено' => 'submitted',
        'отправлен' => 'submitted',
    ];

    return $map[$normalized] ?? '';
}

function docs_collect_unique_subordinate_review_entries(array $record): array
{
    $entries = [];
    $seen = [];

    $register = static function (array $entry) use (&$entries, &$seen): void {
        if (empty($entry)) {
            return;
        }

        $entry['role'] = 'subordinate';
        $keys = docs_collect_assignee_index_keys($entry);
        $primaryKey = '';
        foreach ($keys as $key) {
            if ($key !== '') {
                $primaryKey = mb_strtolower($key, 'UTF-8');
                break;
            }
        }
        if ($primaryKey === '') {
            $primaryKey = 'entry::' . count($entries);
        }
        if (isset($seen[$primaryKey])) {
            return;
        }

        $seen[$primaryKey] = true;
        $entries[] = $entry;
    };

    foreach (docs_extract_assignees($record) as $entry) {
        if (!is_array($entry)) {
            continue;
        }
        if (docs_normalize_assignment_role((string) ($entry['role'] ?? '')) === 'subordinate') {
            $register($entry);
        }
    }

    if (isset($record['subordinates']) && is_array($record['subordinates'])) {
        foreach ($record['subordinates'] as $entry) {
            if (is_array($entry)) {
                $register($entry);
            }
        }
    } elseif (isset($record['subordinate']) && is_array($record['subordinate'])) {
        $register($record['subordinate']);
    }

    return $entries;
}

function docs_assignment_instruction_requires_work(array $entry): bool
{
    $instruction = sanitize_instruction(isset($entry['assignmentInstruction']) ? (string) $entry['assignmentInstruction'] : '');
    if ($instruction === '') {
        return false;
    }

    $normalized = mb_strtolower($instruction, 'UTF-8');
    $normalized = str_replace('ё', 'е', $normalized);
    $normalized = preg_replace('/\s+/u', ' ', $normalized);

    return trim((string) $normalized) === 'в работу';
}

function docs_get_subordinate_review_summary(array $record): array
{
    $entries = docs_collect_unique_subordinate_review_entries($record);
    $accepted = 0;
    $total = 0;

    foreach ($entries as $entry) {
        if (!docs_assignment_instruction_requires_work($entry)) {
            continue;
        }
        $total++;
        if (docs_normalize_subordinate_review_status($entry['reviewStatus'] ?? '') === 'accepted') {
            $accepted++;
        }
    }

    return [
        'accepted' => $accepted,
        'total' => $total,
        'allAccepted' => $total === 0 || $accepted >= $total,
    ];
}

function docs_collect_current_responsible_assignment_entries(array $record): array
{
    $entries = [];
    $seen = [];

    $register = static function (array $entry, string $fallbackRole) use (&$entries, &$seen): void {
        if (empty($entry)) {
            return;
        }

        $role = docs_normalize_assignment_role((string) ($entry['role'] ?? ''));
        if ($role === '') {
            $role = docs_normalize_assignment_role($fallbackRole);
        }
        if (!in_array($role, ['responsible', 'subordinate'], true)) {
            return;
        }

        $entry['role'] = $role;
        $keys = docs_collect_assignee_index_keys($entry);
        $primaryKey = '';
        foreach ($keys as $key) {
            if ($key !== '') {
                $primaryKey = mb_strtolower($role . '::' . $key, 'UTF-8');
                break;
            }
        }
        if ($primaryKey === '') {
            $primaryKey = 'entry::' . count($entries);
        }
        if (isset($seen[$primaryKey])) {
            return;
        }

        $seen[$primaryKey] = true;
        $entries[] = $entry;
    };

    foreach (docs_extract_assignees($record) as $entry) {
        if (!is_array($entry)) {
            continue;
        }
        $register($entry, 'responsible');
    }

    if (isset($record['responsibles']) && is_array($record['responsibles'])) {
        foreach ($record['responsibles'] as $entry) {
            if (is_array($entry)) {
                $register($entry, 'responsible');
            }
        }
    } elseif (isset($record['responsible']) && is_array($record['responsible'])) {
        $register($record['responsible'], 'responsible');
    }

    if (isset($record['subordinates']) && is_array($record['subordinates'])) {
        foreach ($record['subordinates'] as $entry) {
            if (is_array($entry)) {
                $register($entry, 'subordinate');
            }
        }
    } elseif (isset($record['subordinate']) && is_array($record['subordinate'])) {
        $register($record['subordinate'], 'subordinate');
    }

    return $entries;
}

function docs_assignment_entry_matches_current_user(
    array $entry,
    array $requestContext,
    array $directories = [],
    ?array $sessionAuth = null
): bool {
    $userCandidates = docs_collect_extended_assignment_author_candidates($requestContext, $directories, $sessionAuth);
    if (empty($userCandidates['ids']) && empty($userCandidates['names'])) {
        return false;
    }

    return docs_assignment_identity_candidates_intersect(
        docs_collect_assignment_identity_candidates($entry),
        $userCandidates
    );
}

function docs_get_assignee_latest_status(array $record, array $entry): string
{
    $history = isset($record['assigneeStatusHistory']) && is_array($record['assigneeStatusHistory'])
        ? docs_sanitize_assignee_status_history_collection($record['assigneeStatusHistory'])
        : [];
    if (empty($history)) {
        return '';
    }

    $entryKeys = array_map(static function ($key): string {
        return mb_strtolower((string) $key, 'UTF-8');
    }, docs_collect_assignee_index_keys($entry));

    if (empty($entryKeys)) {
        return '';
    }

    $latest = null;
    $latestTimestamp = null;
    foreach ($history as $historyEntry) {
        $historyKey = mb_strtolower((string) ($historyEntry['assigneeKey'] ?? ''), 'UTF-8');
        if ($historyKey === '' || !in_array($historyKey, $entryKeys, true)) {
            continue;
        }
        $entries = isset($historyEntry['entries']) && is_array($historyEntry['entries'])
            ? $historyEntry['entries']
            : [];
        if (empty($entries)) {
            continue;
        }
        $lastEntry = $entries[count($entries) - 1];
        $timestamp = strtotime((string) ($lastEntry['changedAt'] ?? ''));
        if ($latest === null || ($timestamp !== false && ($latestTimestamp === null || $timestamp > $latestTimestamp))) {
            $latest = $lastEntry;
            $latestTimestamp = $timestamp !== false ? $timestamp : $latestTimestamp;
        }
    }

    return is_array($latest) ? sanitize_status((string) ($latest['status'] ?? ''), false) : '';
}

function docs_assignment_entry_completed_for_current_responsible(
    array $record,
    array $entry,
    array $requestContext,
    array $directories = [],
    ?array $sessionAuth = null
): bool {
    if (docs_assignment_entry_matches_current_user($entry, $requestContext, $directories, $sessionAuth)) {
        return true;
    }

    if (docs_normalize_subordinate_review_status($entry['reviewStatus'] ?? '') === 'accepted') {
        return true;
    }

    $status = sanitize_status((string) ($entry['status'] ?? ''), false);
    if (docs_status_key_from_status($status) === 'done') {
        return true;
    }

    $latestStatus = docs_get_assignee_latest_status($record, $entry);
    return docs_status_key_from_status($latestStatus) === 'done';
}

function docs_assignment_entry_display_name(array $entry): string
{
    foreach (['name', 'responsible', 'fullName', 'fio', 'displayName', 'login', 'email', 'telegram', 'chatId', 'id'] as $field) {
        $value = sanitize_text_field((string) ($entry[$field] ?? ''), 200);
        if ($value !== '') {
            return $value;
        }
    }

    return 'исполнитель';
}

function docs_build_current_responsible_assignment_block_message(array $pendingNames): string
{
    $names = array_values(array_unique(array_filter(array_map(static function ($name): string {
        return sanitize_text_field((string) $name, 200);
    }, $pendingNames))));
    if (empty($names)) {
        return 'Вы назначили исполнителя. Ему нужно завершить задачу.';
    }
    $list = implode(', ', array_slice($names, 0, 5));
    if (count($names) > 5) {
        $list .= ' +' . (count($names) - 5);
    }

    return 'Вы назначили: ' . $list . '. Ему нужно завершить задачу.';
}

function docs_get_current_responsible_assignment_completion_summary(
    array $record,
    array $requestContext,
    array $directories = [],
    ?array $sessionAuth = null
): array {
    $entries = docs_collect_current_responsible_assignment_entries($record);
    $completed = 0;
    $total = 0;
    $pendingNames = [];

    foreach ($entries as $entry) {
        if (!is_array($entry) || empty($entry)) {
            continue;
        }

        $role = docs_normalize_assignment_role((string) ($entry['role'] ?? ''));
        if ($role === 'subordinate' && !docs_assignment_instruction_requires_work($entry)) {
            continue;
        }

        if (!docs_entry_assigned_by_current_user($entry, $requestContext, $directories, $sessionAuth)) {
            continue;
        }

        $total++;
        if (docs_assignment_entry_completed_for_current_responsible($record, $entry, $requestContext, $directories, $sessionAuth)) {
            $completed++;
            continue;
        }

        $pendingNames[] = docs_assignment_entry_display_name($entry);
    }

    return [
        'completed' => $completed,
        'total' => $total,
        'allCompleted' => $total === 0 || $completed >= $total,
        'pendingNames' => array_values(array_unique($pendingNames)),
        'message' => docs_build_current_responsible_assignment_block_message($pendingNames),
    ];
}

function docs_collect_record_responsible_only_candidates(array $record): array
{
    $ids = [];
    $names = [];

    $pushId = static function ($value) use (&$ids): void {
        $normalized = docs_normalize_identifier_candidate_value($value);
        if ($normalized !== '') {
            $ids[$normalized] = true;
        }
    };

    $pushName = static function ($value) use (&$names): void {
        $normalized = docs_normalize_name_candidate_value($value);
        if ($normalized !== '') {
            $names[$normalized] = true;
        }
    };

    foreach (docs_extract_assignees($record) as $assignee) {
        if (!is_array($assignee)) {
            continue;
        }

        if (docs_normalize_assignment_role((string) ($assignee['role'] ?? 'responsible')) === 'subordinate') {
            continue;
        }

        foreach (['id', 'telegram', 'chatId', 'number', 'email', 'login'] as $field) {
            if (!empty($assignee[$field])) {
                $pushId($assignee[$field]);
            }
        }
        foreach (['name', 'responsible'] as $field) {
            if (!empty($assignee[$field])) {
                $pushName($assignee[$field]);
            }
        }
    }

    if (isset($record['responsibles']) && is_array($record['responsibles'])) {
        foreach ($record['responsibles'] as $responsible) {
            if (is_array($responsible)) {
                foreach (['id', 'telegram', 'chatId', 'number', 'email', 'login'] as $field) {
                    if (!empty($responsible[$field])) {
                        $pushId($responsible[$field]);
                    }
                }
                foreach (['name', 'responsible'] as $field) {
                    if (!empty($responsible[$field])) {
                        $pushName($responsible[$field]);
                    }
                }
            } elseif (is_scalar($responsible)) {
                $pushName($responsible);
            }
        }
    }

    if (!empty($record['assigneeId'])) {
        $pushId($record['assigneeId']);
    }
    if (!empty($record['responsible'])) {
        $pushName($record['responsible']);
    }

    return [
        'ids' => array_keys($ids),
        'names' => array_keys($names),
    ];
}

function docs_request_matches_record_responsible_only(array $record, array $requestContext): bool
{
    $userCandidates = docs_collect_request_identity_candidates($requestContext);
    if (empty($userCandidates['ids']) && empty($userCandidates['names'])) {
        return false;
    }

    $recordCandidates = docs_collect_record_responsible_only_candidates($record);

    foreach ($userCandidates['ids'] as $candidate) {
        if (in_array($candidate, $recordCandidates['ids'], true)) {
            return true;
        }
    }

    foreach ($userCandidates['names'] as $candidate) {
        if (in_array($candidate, $recordCandidates['names'], true)) {
            return true;
        }
    }

    return false;
}

function docs_build_subordinate_review_target_keys(string $candidate): array
{
    $candidate = sanitize_text_field($candidate, 200);
    if ($candidate === '') {
        return [];
    }

    $keys = [];
    $normalizedId = docs_normalize_identifier_candidate_value($candidate);
    if ($normalizedId !== '') {
        $keys[] = 'id::' . $normalizedId;
    }

    $normalizedName = docs_normalize_name_candidate_value($candidate);
    if ($normalizedName !== '') {
        $keys[] = 'name::' . $normalizedName;
    }

    return array_values(array_unique($keys));
}

function docs_subordinate_entry_matches_review_target(array $entry, array $targetKeys): bool
{
    if (empty($targetKeys)) {
        return false;
    }

    $entryKeys = docs_collect_assignee_index_keys($entry);
    foreach ($entryKeys as $entryKey) {
        $normalizedEntryKey = mb_strtolower($entryKey, 'UTF-8');
        foreach ($targetKeys as $targetKey) {
            if ($normalizedEntryKey === mb_strtolower($targetKey, 'UTF-8')) {
                return true;
            }
        }
    }

    return false;
}

function docs_request_matches_subordinate_entry(array $entry, array $requestContext): bool
{
    $userCandidates = docs_collect_request_identity_candidates($requestContext);
    if (empty($userCandidates['ids']) && empty($userCandidates['names'])) {
        return false;
    }

    $entryIds = [];
    $entryNames = [];

    foreach (['id', 'telegram', 'chatId', 'number', 'email', 'login'] as $field) {
        if (empty($entry[$field])) {
            continue;
        }

        $normalized = docs_normalize_identifier_candidate_value($entry[$field]);
        if ($normalized !== '') {
            $entryIds[$normalized] = true;
        }
    }

    foreach (['name', 'responsible'] as $field) {
        if (empty($entry[$field])) {
            continue;
        }

        $normalized = docs_normalize_name_candidate_value($entry[$field]);
        if ($normalized !== '') {
            $entryNames[$normalized] = true;
        }
    }

    foreach ($userCandidates['ids'] as $candidate) {
        if (isset($entryIds[$candidate])) {
            return true;
        }
    }

    foreach ($userCandidates['names'] as $candidate) {
        if (isset($entryNames[$candidate])) {
            return true;
        }
    }

    return false;
}

function docs_apply_subordinate_review_to_entry(
    array $entry,
    string $status,
    string $comment,
    array $reviewerMeta,
    string $reviewedAt
): array {
    $entry['role'] = 'subordinate';
    $entry['reviewStatus'] = $status;
    if ($comment !== '') {
        $entry['reviewComment'] = $comment;
    } elseif (isset($entry['reviewComment'])) {
        unset($entry['reviewComment']);
    }
    $entry['reviewedAt'] = $reviewedAt;
    $entry['reviewedBy'] = sanitize_text_field((string) ($reviewerMeta['label'] ?? ''), 200);
    $entry['reviewedByTelegram'] = sanitize_text_field((string) ($reviewerMeta['telegram'] ?? ''), 120);
    $entry['reviewedById'] = sanitize_text_field((string) ($reviewerMeta['id'] ?? ''), 120);
    $entry['reviewedByLogin'] = sanitize_text_field((string) ($reviewerMeta['login'] ?? ''), 120);
    if ($status === 'revision') {
        unset(
            $entry['submissionStatus'],
            $entry['submittedAt'],
            $entry['submittedBy'],
            $entry['submittedByTelegram'],
            $entry['submittedById'],
            $entry['submittedByLogin']
        );
    }

    return array_filter($entry, static function ($value) {
        return $value !== '';
    });
}

function docs_apply_subordinate_submission_to_entry(array $entry, array $submitterMeta, string $submittedAt): array
{
    $entry['role'] = 'subordinate';
    $entry['submissionStatus'] = 'submitted';
    $entry['submittedAt'] = $submittedAt;
    $entry['submittedBy'] = sanitize_text_field((string) ($submitterMeta['label'] ?? ''), 200);
    $entry['submittedByTelegram'] = sanitize_text_field((string) ($submitterMeta['telegram'] ?? ''), 120);
    $entry['submittedById'] = sanitize_text_field((string) ($submitterMeta['id'] ?? ''), 120);
    $entry['submittedByLogin'] = sanitize_text_field((string) ($submitterMeta['login'] ?? ''), 120);

    if (docs_normalize_subordinate_review_status($entry['reviewStatus'] ?? '') === 'revision') {
        unset(
            $entry['reviewStatus'],
            $entry['reviewComment'],
            $entry['reviewedAt'],
            $entry['reviewedBy'],
            $entry['reviewedByTelegram'],
            $entry['reviewedById'],
            $entry['reviewedByLogin']
        );
    }

    return array_filter($entry, static function ($value) {
        return $value !== '';
    });
}

function docs_resolve_subordinate_submission_candidate_from_entry(array $entry): string
{
    foreach (['id', 'telegram', 'chatId', 'number', 'email', 'login', 'name', 'responsible'] as $field) {
        if (!isset($entry[$field]) || !is_scalar($entry[$field])) {
            continue;
        }

        $candidate = sanitize_text_field((string) $entry[$field], 200);
        if ($candidate !== '') {
            return $candidate;
        }
    }

    return '';
}

function docs_record_entry_is_subordinate(array $record, array $entry): bool
{
    if (docs_normalize_assignment_role((string) ($entry['role'] ?? '')) === 'subordinate') {
        return true;
    }

    $entryKeys = array_map(static function ($key): string {
        return mb_strtolower(trim((string) $key), 'UTF-8');
    }, docs_collect_assignee_index_keys($entry));
    $entryKeys = array_values(array_filter($entryKeys, static fn(string $key): bool => $key !== ''));
    if (empty($entryKeys)) {
        return false;
    }

    foreach (docs_collect_unique_subordinate_review_entries($record) as $subordinate) {
        $subordinateKeys = array_map(static function ($key): string {
            return mb_strtolower(trim((string) $key), 'UTF-8');
        }, docs_collect_assignee_index_keys($subordinate));
        if (!empty(array_intersect($entryKeys, $subordinateKeys))) {
            return true;
        }
    }

    return false;
}

function docs_append_subordinate_status_history(
    array &$record,
    array $subordinate,
    string $subordinateCandidate,
    string $status,
    string $changedBy,
    array $extraAssigneeKeys = []
): void {
    $assigneeKeys = docs_collect_assignee_index_keys($subordinate);
    if ($subordinateCandidate !== '') {
        $assigneeKeys = array_merge($assigneeKeys, docs_build_subordinate_review_target_keys($subordinateCandidate));
    }
    if (!empty($extraAssigneeKeys)) {
        $assigneeKeys = array_merge($assigneeKeys, $extraAssigneeKeys);
    }

    $normalizedAssigneeKeys = [];
    foreach ($assigneeKeys as $assigneeKey) {
        $normalizedKey = mb_strtolower(trim((string) $assigneeKey), 'UTF-8');
        if ($normalizedKey !== '') {
            $normalizedAssigneeKeys[$normalizedKey] = $normalizedKey;
        }
    }

    if (empty($normalizedAssigneeKeys)) {
        return;
    }

    $normalizedStatus = sanitize_status($status);
    if ($normalizedStatus === '') {
        return;
    }

    $entry = [
        'status' => $normalizedStatus,
        'changedAt' => date('c'),
        'changedBy' => sanitize_text_field($changedBy, 200),
    ];

    foreach ($normalizedAssigneeKeys as $assigneeKey) {
        docs_append_assignee_status_history($record, $assigneeKey, $entry);
    }
}

function docs_subordinate_latest_status_is_in_work(
    array $record,
    array $subordinate,
    string $subordinateCandidate = ''
): bool {
    if (empty($record['assigneeStatusHistory']) || !is_array($record['assigneeStatusHistory'])) {
        return false;
    }

    $candidateKeys = docs_collect_assignee_index_keys($subordinate);
    if ($subordinateCandidate !== '') {
        $candidateKeys = array_merge($candidateKeys, docs_build_subordinate_review_target_keys($subordinateCandidate));
    }
    $candidateKeys = array_values(array_unique(array_filter(array_map(static function ($key) {
        return mb_strtolower(trim((string) $key), 'UTF-8');
    }, $candidateKeys))));
    if (empty($candidateKeys)) {
        return false;
    }

    $history = docs_sanitize_assignee_status_history_collection($record['assigneeStatusHistory']);
    $latestStatus = '';
    $latestTimestamp = 0;
    foreach ($history as $historyRecord) {
        $assigneeKey = mb_strtolower(trim((string) ($historyRecord['assigneeKey'] ?? '')), 'UTF-8');
        if ($assigneeKey === '' || !in_array($assigneeKey, $candidateKeys, true)) {
            continue;
        }

        $entries = isset($historyRecord['entries']) && is_array($historyRecord['entries'])
            ? $historyRecord['entries']
            : [];
        foreach ($entries as $entry) {
            if (!is_array($entry)) {
                continue;
            }
            $status = sanitize_status((string) ($entry['status'] ?? ''), false);
            if ($status === '') {
                continue;
            }
            $timestamp = strtotime((string) ($entry['changedAt'] ?? ''));
            if ($timestamp === false) {
                $timestamp = 0;
            }
            if ($latestStatus === '' || $timestamp >= $latestTimestamp) {
                $latestStatus = $status;
                $latestTimestamp = $timestamp;
            }
        }
    }

    if ($latestStatus === '') {
        return false;
    }

    $normalizedStatus = mb_strtolower($latestStatus, 'UTF-8');
    return mb_stripos($normalizedStatus, 'в работе', 0, 'UTF-8') !== false
        || mb_stripos($normalizedStatus, 'принято в работу', 0, 'UTF-8') !== false;
}

function docs_apply_subordinate_review_decision(
    array &$record,
    string $subordinateCandidate,
    string $status,
    string $comment,
    array $reviewerMeta
): ?array {
    $targetKeys = docs_build_subordinate_review_target_keys($subordinateCandidate);
    if (empty($targetKeys)) {
        return null;
    }

    $existingAssignees = docs_extract_assignees($record);
    $responsibleEntries = [];
    $subordinateEntries = [];
    $seenSubordinateKeys = [];

    $registerSubordinateEntry = static function (array $entry) use (&$subordinateEntries, &$seenSubordinateKeys): void {
        if (empty($entry)) {
            return;
        }
        $entry['role'] = 'subordinate';
        $keys = docs_collect_assignee_index_keys($entry);
        foreach ($keys as $key) {
            if ($key !== '' && isset($seenSubordinateKeys[$key])) {
                return;
            }
        }
        foreach ($keys as $key) {
            if ($key !== '') {
                $seenSubordinateKeys[$key] = true;
            }
        }
        $subordinateEntries[] = $entry;
    };

    foreach ($existingAssignees as $existingAssignee) {
        if (!is_array($existingAssignee)) {
            continue;
        }

        if (docs_normalize_assignment_role((string) ($existingAssignee['role'] ?? '')) === 'subordinate') {
            $registerSubordinateEntry($existingAssignee);
        } else {
            $responsibleEntries[] = $existingAssignee;
        }
    }

    if (isset($record['subordinates']) && is_array($record['subordinates'])) {
        foreach ($record['subordinates'] as $existingSubordinate) {
            if (is_array($existingSubordinate)) {
                $registerSubordinateEntry($existingSubordinate);
            }
        }
    } elseif (isset($record['subordinate']) && is_array($record['subordinate'])) {
        $registerSubordinateEntry($record['subordinate']);
    }

    $reviewedAt = date('c');
    $reviewedEntry = null;
    foreach ($subordinateEntries as &$subordinateEntry) {
        if (!is_array($subordinateEntry)) {
            continue;
        }

        if (!docs_subordinate_entry_matches_review_target($subordinateEntry, $targetKeys)) {
            continue;
        }

        $subordinateEntry = docs_apply_subordinate_review_to_entry(
            $subordinateEntry,
            $status,
            $comment,
            $reviewerMeta,
            $reviewedAt
        );
        $reviewedEntry = $subordinateEntry;
    }
    unset($subordinateEntry);

    if ($reviewedEntry === null) {
        return null;
    }

    $combinedAssignees = array_merge($responsibleEntries, $subordinateEntries);
    $newAssignments = [];
    docs_apply_assignees_to_record($record, $combinedAssignees, $newAssignments);
    $record['subordinates'] = array_values($subordinateEntries);
    unset($record['subordinate']);

    return $reviewedEntry;
}

function docs_apply_subordinate_submission(
    array &$record,
    string $subordinateCandidate,
    array $requestContext,
    array $submitterMeta
): ?array {
    $targetKeys = docs_build_subordinate_review_target_keys($subordinateCandidate);
    if (empty($targetKeys)) {
        return null;
    }

    $existingAssignees = docs_extract_assignees($record);
    $responsibleEntries = [];
    $subordinateEntries = [];
    $seenSubordinateKeys = [];

    $registerSubordinateEntry = static function (array $entry) use (&$subordinateEntries, &$seenSubordinateKeys): void {
        if (empty($entry)) {
            return;
        }
        $entry['role'] = 'subordinate';
        $keys = docs_collect_assignee_index_keys($entry);
        foreach ($keys as $key) {
            if ($key !== '' && isset($seenSubordinateKeys[$key])) {
                return;
            }
        }
        foreach ($keys as $key) {
            if ($key !== '') {
                $seenSubordinateKeys[$key] = true;
            }
        }
        $subordinateEntries[] = $entry;
    };

    foreach ($existingAssignees as $existingAssignee) {
        if (!is_array($existingAssignee)) {
            continue;
        }

        if (docs_normalize_assignment_role((string) ($existingAssignee['role'] ?? '')) === 'subordinate') {
            $registerSubordinateEntry($existingAssignee);
        } else {
            $responsibleEntries[] = $existingAssignee;
        }
    }

    if (isset($record['subordinates']) && is_array($record['subordinates'])) {
        foreach ($record['subordinates'] as $existingSubordinate) {
            if (is_array($existingSubordinate)) {
                $registerSubordinateEntry($existingSubordinate);
            }
        }
    } elseif (isset($record['subordinate']) && is_array($record['subordinate'])) {
        $registerSubordinateEntry($record['subordinate']);
    }

    $submittedAt = date('c');
    $submittedEntry = null;
    $matchedButForbidden = false;
    foreach ($subordinateEntries as &$subordinateEntry) {
        if (!is_array($subordinateEntry)) {
            continue;
        }

        if (!docs_subordinate_entry_matches_review_target($subordinateEntry, $targetKeys)) {
            continue;
        }

        if (!docs_request_matches_subordinate_entry($subordinateEntry, $requestContext)) {
            $matchedButForbidden = true;
            continue;
        }

        if (docs_normalize_subordinate_review_status($subordinateEntry['reviewStatus'] ?? '') === 'accepted') {
            return ['__accepted' => true];
        }

        if (!docs_assignment_instruction_requires_work($subordinateEntry)) {
            return ['__requiresWorkInstruction' => true];
        }

        $subordinateEntry = docs_apply_subordinate_submission_to_entry(
            $subordinateEntry,
            $submitterMeta,
            $submittedAt
        );
        $submittedEntry = $subordinateEntry;
    }
    unset($subordinateEntry);

    if ($submittedEntry === null) {
        return $matchedButForbidden ? ['__forbidden' => true] : null;
    }

    $combinedAssignees = array_merge($responsibleEntries, $subordinateEntries);
    $newAssignments = [];
    docs_apply_assignees_to_record($record, $combinedAssignees, $newAssignments);
    $record['subordinates'] = array_values($subordinateEntries);
    unset($record['subordinate']);

    return $submittedEntry;
}

function docs_collect_record_subordinate_candidates(array $record): array
{
    $ids = [];
    $names = [];

    $pushId = static function ($value) use (&$ids): void {
        $normalized = docs_normalize_identifier_candidate_value($value);
        if ($normalized !== '') {
            $ids[$normalized] = true;
        }
    };

    $pushName = static function ($value) use (&$names): void {
        $normalized = docs_normalize_name_candidate_value($value);
        if ($normalized !== '') {
            $names[$normalized] = true;
        }
    };

    $subordinates = [];
    if (isset($record['subordinates']) && is_array($record['subordinates'])) {
        $subordinates = $record['subordinates'];
    } elseif (isset($record['subordinate']) && is_array($record['subordinate'])) {
        $subordinates = [$record['subordinate']];
    }

    foreach ($subordinates as $subordinate) {
        if (!is_array($subordinate)) {
            continue;
        }
        foreach (['id', 'telegram', 'chatId', 'number', 'email', 'login'] as $field) {
            if (!empty($subordinate[$field])) {
                $pushId($subordinate[$field]);
            }
        }
        foreach (['name', 'responsible'] as $field) {
            if (!empty($subordinate[$field])) {
                $pushName($subordinate[$field]);
            }
        }
    }

    return [
        'ids' => array_keys($ids),
        'names' => array_keys($names),
    ];
}

