    }

    $requestContext = docs_build_request_user_context();

    $payload = load_json_payload();
    if (empty($payload) && !empty($_POST) && is_array($_POST)) {
        $payload = $_POST;
    }

    if (empty($payload) || !is_array($payload)) {
        respond_success(['logged' => false]);
        return;
