    $eventRaw = isset($payload['event']) ? (string) $payload['event'] : 'task_view_pdf_diagnostics';
    $event = sanitize_text_field($eventRaw, 120);
    if ($event === '') {
        $event = 'task_view_pdf_diagnostics';
    }

