    case 'mini_app_task_snapshot':
        $requestContext = docs_build_request_user_context();
        $method = $_SERVER['REQUEST_METHOD'] ?? 'GET';
        if (strtoupper($method) !== 'POST') {
            respond_error('Некорректный метод запроса.', 405);
