            $removedCount = count($removedEntries);
            $message = $removedCount > 1 ? 'Подчинённые удалены.' : 'Подчинённый удалён.';
        } elseif ($updateType === 'subordinate_submit') {
            if (!docs_review_flow_enabled($records[$recordIndex])) {
                respond_error('Отправка на проверку доступна только для новых задач.', 403, [
                    'requiresReviewFlow' => DOCS_REVIEW_FLOW_RESPONSIBLE_SUBORDINATE,
                ]);
            }

            if ($isDirector || !$actsAsTaskSubordinate) {
                respond_error('Отправить выполнение на проверку может только назначенный подчинённый.', 403, [
                    'requiresSubordinate' => true,
                ]);
            }

            $currentSharedStatus = sanitize_status(
                isset($records[$recordIndex]['status']) ? (string) $records[$recordIndex]['status'] : ''
            );
            if (in_array($currentSharedStatus, ['Выполнено', 'Отменено'], true)) {
                respond_error('Нельзя отправить на проверку закрытую задачу.', 422, [
                    'closedStatus' => $currentSharedStatus,
                ]);
            }

            $subordinateCandidate = '';
            foreach (['subordinateId', 'subordinate', 'id'] as $field) {
                if (!isset($payload[$field]) || !is_scalar($payload[$field])) {
                    continue;
                }

                $subordinateCandidate = sanitize_text_field((string) $payload[$field], 200);
                if ($subordinateCandidate !== '') {
                    break;
                }
            }

            if ($subordinateCandidate === '' && isset($payload['subordinateIds']) && is_array($payload['subordinateIds'])) {
                foreach ($payload['subordinateIds'] as $candidate) {
                    if (!is_scalar($candidate)) {
                        continue;
                    }
                    $subordinateCandidate = sanitize_text_field((string) $candidate, 200);
                    if ($subordinateCandidate !== '') {
                        break;
                    }
                }
            }

            if ($subordinateCandidate === '') {
                respond_error('Не указан подчинённый для отправки на проверку.', 400);
            }

            $submitterMeta = [
                'label' => $assignmentAuthor,
                'telegram' => (string) ($assignmentAuthorMeta['assignedByTelegram'] ?? ''),
                'id' => (string) ($assignmentAuthorMeta['assignedById'] ?? ''),
                'login' => (string) ($assignmentAuthorMeta['assignedByLogin'] ?? ''),
            ];

            $submittedSubordinate = docs_apply_subordinate_submission(
                $records[$recordIndex],
                $subordinateCandidate,
                $requestContext,
                $submitterMeta
            );

            if (is_array($submittedSubordinate) && !empty($submittedSubordinate['__forbidden'])) {
                respond_error('Можно отправить на проверку только своё выполнение.', 403, [
                    'requiresSubordinateOwner' => true,
                ]);
            }

            if (is_array($submittedSubordinate) && !empty($submittedSubordinate['__accepted'])) {
                respond_error('Выполнение подчинённого уже принято.', 422, [
                    'alreadyAccepted' => true,
                ]);
            }

            if (is_array($submittedSubordinate) && !empty($submittedSubordinate['__requiresWorkInstruction'])) {
                respond_error('Отправка на проверку доступна только для поручения «В работу».', 422, [
                    'requiresWorkInstruction' => true,
                ]);
            }

            if ($submittedSubordinate === null) {
                respond_error('Подчинённый не найден среди назначенных.', 404);
            }

            $submitterStatusKeys = docs_collect_status_change_candidate_keys(
                $requestContext,
                $sessionAuthArray,
                $assignmentAuthor
            );
            docs_append_subordinate_status_history(
                $records[$recordIndex],
                $submittedSubordinate,
                $subordinateCandidate,
                'На проверке',
                $assignmentAuthor,
                $submitterStatusKeys
            );

            $reviewSharedStatus = 'На проверке';
            if ($currentSharedStatus !== $reviewSharedStatus) {
                $statusUpdatedAt = date('c');
                $records[$recordIndex]['status'] = $reviewSharedStatus;
                $records[$recordIndex]['statusUpdatedAt'] = $statusUpdatedAt;
                docs_append_status_history(
                    $records[$recordIndex],
                    $reviewSharedStatus,
                    $assignmentAuthor,
                    $statusUpdatedAt
                );
            }

            $message = 'Ответственный уведомлен.  Задача перемещена в статус «На проверке».';
        } elseif ($updateType === 'subordinate_review') {
            if (!docs_review_flow_enabled($records[$recordIndex])) {
                respond_error('Приёмка доступна только для новых задач.', 403, [
                    'requiresReviewFlow' => DOCS_REVIEW_FLOW_RESPONSIBLE_SUBORDINATE,
                ]);
            }

            if (!$isDirector && !$isTaskResponsible) {
                respond_error('Недостаточно прав для приёмки выполнения подчинённого.', 403, [
                    'requiresResponsible' => true,
                ]);
            }

            $subordinateCandidate = '';
            foreach (['subordinateId', 'subordinate', 'id'] as $field) {
                if (!isset($payload[$field]) || !is_scalar($payload[$field])) {
                    continue;
                }

                $subordinateCandidate = sanitize_text_field((string) $payload[$field], 200);
                if ($subordinateCandidate !== '') {
                    break;
                }
            }

            if ($subordinateCandidate === '' && isset($payload['subordinateIds']) && is_array($payload['subordinateIds'])) {
                foreach ($payload['subordinateIds'] as $candidate) {
                    if (!is_scalar($candidate)) {
                        continue;
                    }
                    $subordinateCandidate = sanitize_text_field((string) $candidate, 200);
                    if ($subordinateCandidate !== '') {
                        break;
                    }
                }
            }

            if ($subordinateCandidate === '') {
                respond_error('Не указан подчинённый для приёмки.', 400);
            }

            $rawReviewStatus = $payload['reviewStatus'] ?? ($payload['decision'] ?? '');
            $reviewStatus = docs_normalize_subordinate_review_status($rawReviewStatus);
            if ($reviewStatus === '') {
                respond_error('Не указано решение по выполнению.', 400);
            }

            $reviewCommentRaw = '';
            if (isset($payload['reviewComment']) && is_scalar($payload['reviewComment'])) {
                $reviewCommentRaw = (string) $payload['reviewComment'];
            } elseif (isset($payload['comment']) && is_scalar($payload['comment'])) {
                $reviewCommentRaw = (string) $payload['comment'];
            }
            $reviewComment = sanitize_assignment_comment($reviewCommentRaw);
            if ($reviewStatus === 'revision' && $reviewComment === '') {
                respond_error('Комментарий обязателен для отправки на доработку.', 422, [
                    'requiresComment' => true,
                ]);
            }

            $submittedTargetFound = false;
            $targetKeys = docs_build_subordinate_review_target_keys($subordinateCandidate);
            foreach (docs_collect_unique_subordinate_review_entries($records[$recordIndex]) as $entry) {
                if (!docs_subordinate_entry_matches_review_target($entry, $targetKeys)) {
                    continue;
                }
                $submittedTargetFound = true;
                if (docs_request_matches_subordinate_entry($entry, $requestContext)) {
                    respond_error('Нельзя принять собственное выполнение.', 403, [
                        'selfReviewForbidden' => true,
                    ]);
                }
                if (docs_normalize_subordinate_submission_status($entry['submissionStatus'] ?? '') !== 'submitted') {
                    respond_error('Подчинённый ещё не отправил выполнение на проверку.', 422, [
                        'requiresSubmission' => true,
                    ]);
                }
                break;
            }

            if (!$submittedTargetFound) {
                respond_error('Подчинённый не найден среди назначенных.', 404);
            }

            $reviewerMeta = [
                'label' => $assignmentAuthor,
                'telegram' => (string) ($assignmentAuthorMeta['assignedByTelegram'] ?? ''),
                'id' => (string) ($assignmentAuthorMeta['assignedById'] ?? ''),
                'login' => (string) ($assignmentAuthorMeta['assignedByLogin'] ?? ''),
            ];

            $reviewedSubordinate = docs_apply_subordinate_review_decision(
                $records[$recordIndex],
                $subordinateCandidate,
                $reviewStatus,
                $reviewComment,
                $reviewerMeta
            );

            if ($reviewedSubordinate === null) {
                respond_error('Подчинённый не найден среди назначенных.', 404);
            }

            docs_append_subordinate_status_history(
                $records[$recordIndex],
                $reviewedSubordinate,
                $subordinateCandidate,
                $reviewStatus === 'accepted' ? 'Выполнено' : 'В работе',
                $assignmentAuthor
            );

            $message = $reviewStatus === 'accepted'
                ? 'Выполнение подчинённого принято.'
                : 'Выполнение подчинённого отправлено на доработку.';
        } elseif ($updateType === 'file_brief') {
            if (!$isDirector && !$isTaskAssignee) {
                respond_error('Недостаточно прав для сохранения краткого ИИ.', 403, [
                    'requiresDirector' => true,
                    'requiresAssignee' => true,
                ]);
            }

            if (!isset($records[$recordIndex]['files']) || !is_array($records[$recordIndex]['files']) || empty($records[$recordIndex]['files'])) {
                respond_error('В задаче нет файлов для сохранения краткого ИИ.', 404);
            }

            $nextAiBrief = sanitize_text_field((string) ($payload['aiBrief'] ?? ''), 2000);
            if ($nextAiBrief === '') {
                respond_error('Пустой краткий ИИ нельзя сохранить.', 400);
            }

            $storedNameCandidate = sanitize_text_field((string) ($payload['fileStoredName'] ?? ''), 255);
            $originalNameCandidate = sanitize_text_field((string) ($payload['fileOriginalName'] ?? ''), 220);
            $urlCandidateRaw = sanitize_text_field((string) ($payload['fileUrl'] ?? ''), 500);
            $urlCandidate = '';
            if ($urlCandidateRaw !== '') {
                $urlPath = parse_url($urlCandidateRaw, PHP_URL_PATH);
                if (is_string($urlPath) && $urlPath !== '') {
                    $urlCandidate = sanitize_text_field(rawurldecode(basename($urlPath)), 255);
                }
            }

            $updated = false;
            foreach ($records[$recordIndex]['files'] as &$taskFile) {
                if (!is_array($taskFile)) {
                    continue;
                }

                $fileStoredName = sanitize_text_field((string) ($taskFile['storedName'] ?? ''), 255);
                $fileOriginalName = sanitize_text_field((string) ($taskFile['originalName'] ?? ''), 220);
                $fileUrlName = '';
                if (!empty($taskFile['url'])) {
                    $fileUrlPath = parse_url((string) $taskFile['url'], PHP_URL_PATH);
                    if (is_string($fileUrlPath) && $fileUrlPath !== '') {
                        $fileUrlName = sanitize_text_field(rawurldecode(basename($fileUrlPath)), 255);
                    }
                }

                $isMatch = false;
                if ($storedNameCandidate !== '' && $storedNameCandidate === $fileStoredName) {
                    $isMatch = true;
                } elseif ($originalNameCandidate !== '' && $originalNameCandidate === $fileOriginalName) {
                    $isMatch = true;
                } elseif ($urlCandidate !== '' && $urlCandidate === $fileUrlName) {
                    $isMatch = true;
                }

                if (!$isMatch) {
                    continue;
                }

                $taskFile['aiBrief'] = $nextAiBrief;
                if (isset($taskFile['briefai'])) {
                    unset($taskFile['briefai']);
                }
                $updated = true;
                break;
            }
            unset($taskFile);

            if (!$updated) {
                respond_error('Не удалось найти файл для сохранения краткого ИИ.', 404);
            }

            $message = 'Кратко ИИ сохранено.';
        } elseif ($updateType === 'complete') {
            if (!$isTaskDirector) {
                respond_error('Недостаточно прав для завершения задачи.', 403, [
                    'requiresDirector' => true,
                    'requiresTaskDirector' => true,
                ]);
            }

            $statusAuthor = $assignmentAuthor;
            $records[$recordIndex]['directorStatus'] = 'done';
            $records[$recordIndex]['directorStatusUpdatedAt'] = date('c');
            $records[$recordIndex]['directorStatusAuthor'] = $statusAuthor;
            $records[$recordIndex]['directorCompletedAt'] = date('Y-m-d');

            $message = 'Задача отмечена выполненной для директора.';
        } elseif ($updateType === 'status') {
            $canManageStatus = $isDirector || $isTaskAssignee;
            if (!$canManageStatus) {
                respond_error('Недостаточно прав для изменения статуса.', 403, [
                    'requiresDirector' => true,
                    'requiresAssignee' => true,
                ]);
            }

            $rawStatus = isset($payload['status']) ? (string) $payload['status'] : '';
            $nextStatus = sanitize_status($rawStatus);
            $isCompletedStatus = mb_stripos($nextStatus, 'выполн') !== false;
            $shouldCompleteReviewFlowTask = false;
            if ($isCompletedStatus && docs_review_flow_enabled($records[$recordIndex]) && !$isDirector) {
                if (!$isTaskResponsible) {
                    respond_error('Закрыть задачу как выполненную может только ответственный.', 403, [
                        'requiresResponsible' => true,
                    ]);
                }
                $assignmentAuthorDirectories = [$responsibles, $subordinates, $block2];
                $ownAssignmentSummary = docs_get_current_responsible_assignment_completion_summary(
                    $records[$recordIndex],
                    $requestContext,
                    $assignmentAuthorDirectories,
                    $sessionAuthArray
                );
                if (!empty($ownAssignmentSummary['total']) && empty($ownAssignmentSummary['allCompleted'])) {
                    respond_error($ownAssignmentSummary['message'], 422, [
                        'pendingAssignees' => $ownAssignmentSummary['pendingNames'],
                        'completedAssignments' => $ownAssignmentSummary['completed'],
                        'totalAssignments' => $ownAssignmentSummary['total'],
                        'scope' => 'currentResponsibleAssignments',
                    ]);
                }
                $reviewSummary = docs_get_subordinate_review_summary($records[$recordIndex]);
                $shouldCompleteReviewFlowTask = !empty($ownAssignmentSummary['total'])
                    && !empty($reviewSummary['total'])
                    && !empty($reviewSummary['allAccepted']);
            }

            $statusAuthor = $assignmentAuthor;
            $statusAssigneeKey = docs_match_status_change_assignee_key(
                $records[$recordIndex],
                $requestContext,
                $sessionAuthArray,
                $statusAuthor
            );
            $shouldUpdateSharedStatus = $isDirector
                || $shouldCompleteReviewFlowTask
                || $statusAssigneeKey === null
                || $statusAssigneeKey === '';
            if ($shouldUpdateSharedStatus) {
                $records[$recordIndex]['status'] = $nextStatus;
                $records[$recordIndex]['statusUpdatedAt'] = $nextStatus === '' ? null : date('c');
                docs_append_status_history(
                    $records[$recordIndex],
                    $nextStatus,
                    $statusAuthor,
                    $records[$recordIndex]['statusUpdatedAt'],
                    $statusAssigneeKey
                );
            } else {
                if ($nextStatus !== '') {
                    docs_append_assignee_status_history($records[$recordIndex], $statusAssigneeKey, [
                        'status' => $nextStatus,
                        'changedAt' => date('c'),
                        'changedBy' => $statusAuthor,
                    ]);
                } else {
                    docs_clear_assignee_status_history($records[$recordIndex], $statusAssigneeKey);
                }
            }

            $existingCompleted = isset($records[$recordIndex]['completedAt'])
                ? sanitize_date_field((string) $records[$recordIndex]['completedAt'])
                : '';
            if ($shouldUpdateSharedStatus && $isCompletedStatus) {
                $records[$recordIndex]['completedAt'] = $existingCompleted !== '' ? $existingCompleted : date('Y-m-d');
            } elseif ($shouldUpdateSharedStatus && isset($records[$recordIndex]['completedAt'])) {
                unset($records[$recordIndex]['completedAt']);
            }

            $message = 'Статус обновлён.';
        } elseif ($updateType === 'due_date') {
            if (!docs_user_is_block2_member($block2, $requestContext)) {
                respond_error('Недостаточно прав для изменения срока.', 403, [
                    'requiresDirector' => true,
                ]);
            }

            $rawDueDate = isset($payload['dueDate']) ? (string) $payload['dueDate'] : '';
            $normalizedDueDate = sanitize_date_field($rawDueDate);
            $records[$recordIndex]['dueDate'] = $normalizedDueDate;
            if ($normalizedDueDate === '') {
                $message = 'Срок удалён.';
            } else {
                $message = 'Срок обновлён.';
            }
        } elseif ($updateType === 'instruction') {
            if (!docs_user_is_block2_member($block2, $requestContext)) {
                respond_error('Недостаточно прав для изменения поручения.', 403, [
                    'requiresDirector' => true,
                ]);
            }

            $rawInstruction = isset($payload['instruction']) ? (string) $payload['instruction'] : '';
            $normalizedInstruction = sanitize_instruction($rawInstruction);
            $records[$recordIndex]['instruction'] = $normalizedInstruction;
            if ($normalizedInstruction === '') {
                $message = 'Поручение удалено.';
            } else {
                $message = 'Поручение обновлено.';
            }
        } elseif ($updateType === 'folder') {
            $rawFolderId = isset($payload['folderId']) ? (string) $payload['folderId'] : '';
            $normalizedFolderId = sanitize_text_field($rawFolderId, 120);
            $folderUserIdRaw = isset($payload['folderUserId']) ? (string) $payload['folderUserId'] : '';
            $folderUserId = sanitize_text_field($folderUserIdRaw, 200);

            if ($folderUserId === '' && isset($requestContext['primaryId'])) {
                $folderUserId = sanitize_text_field((string) $requestContext['primaryId'], 200);
            }
            if ($folderUserId === '') {
                respond_error('Не удалось определить пользователя для папки.', 400);
            }

            if (!isset($records[$recordIndex]['folderByUser']) || !is_array($records[$recordIndex]['folderByUser'])) {
                $records[$recordIndex]['folderByUser'] = [];
            }

            if ($normalizedFolderId === '') {
                unset($records[$recordIndex]['folderByUser'][$folderUserId]);
            } else {
                $records[$recordIndex]['folderByUser'][$folderUserId] = $normalizedFolderId;
            }
            $message = 'Папка задачи обновлена.';
        } elseif ($updateType === 'folder_state') {
            $folderUserIdRaw = isset($payload['folderUserId']) ? (string) $payload['folderUserId'] : '';
            $folderUserId = sanitize_text_field($folderUserIdRaw, 200);
            if ($folderUserId === '' && isset($requestContext['primaryId'])) {
                $folderUserId = sanitize_text_field((string) $requestContext['primaryId'], 200);
            }
            if ($folderUserId === '') {
                respond_error('Не удалось определить пользователя для сохранения папок.', 400);
            }

            $rawFolderState = isset($payload['folderState']) && is_array($payload['folderState'])
                ? $payload['folderState']
                : [];
            $sanitizedFolderState = [];
            foreach ($rawFolderState as $entry) {
                if (!is_array($entry)) {
                    continue;
                }
                $folderId = sanitize_text_field((string) ($entry['id'] ?? ''), 120);
                $folderName = sanitize_text_field((string) ($entry['name'] ?? ''), 120);
                $folderColor = strtolower(trim((string) ($entry['color'] ?? '#4d91ff')));
                if (!preg_match('/^#[0-9a-f]{6}$/', $folderColor)) {
                    $folderColor = '#4d91ff';
                }
                if ($folderId === '' || $folderName === '') {
                    continue;
                }
                $sanitizedFolderState[] = [
                    'id' => $folderId,
                    'name' => $folderName,
                    'color' => $folderColor,
                ];
            }

            if (!isset($records[$recordIndex]['folderSettingsByUser']) || !is_array($records[$recordIndex]['folderSettingsByUser'])) {
                $records[$recordIndex]['folderSettingsByUser'] = [];
            }
            $records[$recordIndex]['folderSettingsByUser'][$folderUserId] = $sanitizedFolderState;
            $message = 'Список папок сохранён.';
        } else {
            respond_error('Неизвестный тип обновления.', 400, [
                'updateType' => $updateType,
            ]);
        }

        if ($originalDirector !== null) {
            $records[$recordIndex]['director'] = $originalDirector;
        }
        if ($originalDirectors !== null) {
            $records[$recordIndex]['directors'] = $originalDirectors;
        }

        $records[$recordIndex]['updatedAt'] = date('c');

        if ($registryHandle !== null) {
            try {
                docs_save_registry_locked($registryHandle, $records);
            } finally {
                docs_unlock_registry($registryHandle);
            }
        } else {
            save_registry($folder, $records);
        }
        docs_log_file_debug('Mini app update task saved', [
            'clientRequestId' => $clientRequestId !== '' ? $clientRequestId : null,
            'organization' => $organizationCandidate,
            'documentId' => $documentId,
            'updateType' => $updateType,
            'durationMs' => (int) round((microtime(true) - $requestStartedAt) * 1000),
        ]);

        $preparedRecords = docs_prepare_records_for_response([$records[$recordIndex]], $organizationCandidate, $folder);
        $updatedRecord = $preparedRecords[0] ?? $records[$recordIndex];
        $updatedAssignees = docs_extract_assignees($updatedRecord);
        $primaryAssignee = $updatedAssignees[0] ?? null;

        log_docs_event('Mini app task updated', [
            'organization' => $organizationCandidate,
            'documentId' => $documentId,
            'updateType' => $updateType,
            'assigneeId' => in_array($updateType, ['assign', 'assign_add'], true)
                ? ($primaryAssignee['id'] ?? null)
                : null,
            'assigneeIds' => in_array($updateType, ['assign', 'assign_add'], true)
                ? array_values(array_filter(array_map(static function ($entry) {
                    if (!is_array($entry)) {
                        return null;
                    }
                    if (!empty($entry['id'])) {
                        return (string) $entry['id'];
                    }
                    if (!empty($entry['telegram'])) {
                        return (string) $entry['telegram'];
                    }
                    if (!empty($entry['chatId'])) {
                        return (string) $entry['chatId'];
                    }
                    if (!empty($entry['email'])) {
                        return (string) $entry['email'];
                    }
                    return null;
                }, $updatedAssignees)))
                : null,
            'subordinateIds' => in_array($updateType, ['subordinates', 'subordinates_add', 'subordinate_submit', 'subordinate_review'], true)
                ? array_values(array_filter(array_map(static function ($entry) {
                    if (!is_array($entry)) {
                        return null;
                    }
                    $roleValue = strtolower((string) ($entry['role'] ?? ''));
                    if ($roleValue !== 'subordinate') {
                        return null;
                    }
                    foreach (['id', 'telegram', 'chatId', 'email', 'login', 'number'] as $field) {
                        if (!empty($entry[$field])) {
                            return (string) $entry[$field];
                        }
                    }

                    return null;
                }, $updatedAssignees)))
                : null,
            'status' => $updateType === 'status' || $updateType === 'complete' ? ($updatedRecord['status'] ?? null) : null,
            'dueDate' => $updateType === 'due_date' ? ($updatedRecord['dueDate'] ?? null) : null,
            'telegramUserId' => $requestContext['primaryId'] ?? null,
        ]);

        $responsePayload = [
            'message' => $message,
            'organization' => $organizationCandidate,
            'task' => $updatedRecord,
        ];

        if ($updateType === 'subordinate_submit' && is_array($submittedSubordinate) && !empty($submittedSubordinate)) {
            $submittedSubordinateForNotification = $submittedSubordinate;
            if (!function_exists('fastcgi_finish_request')) {
                docs_notify_responsible_about_subordinate_submission(
                    $updatedRecord,
                    $folder,
                    $organizationCandidate,
                    $submittedSubordinateForNotification
                );
                respond_success($responsePayload);
            }
            respond_success_with_background_task($responsePayload, static function () use ($submittedSubordinateForNotification, $updatedRecord, $folder, $organizationCandidate): void {
                docs_notify_responsible_about_subordinate_submission(
                    $updatedRecord,
                    $folder,
                    $organizationCandidate,
                    $submittedSubordinateForNotification
                );
            });
        }

        if ($updateType === 'subordinate_review' && is_array($reviewedSubordinate) && !empty($reviewedSubordinate)) {
            $reviewedSubordinateForNotification = $reviewedSubordinate;
            if (!function_exists('fastcgi_finish_request')) {
                docs_notify_subordinate_about_review($updatedRecord, $organizationCandidate, $reviewedSubordinateForNotification);
                respond_success($responsePayload);
            }
            respond_success_with_background_task($responsePayload, static function () use ($reviewedSubordinateForNotification, $updatedRecord, $organizationCandidate): void {
                docs_notify_subordinate_about_review($updatedRecord, $organizationCandidate, $reviewedSubordinateForNotification);
            });
        }

        if (in_array($updateType, ['assign', 'assign_add', 'subordinates', 'subordinates_add'], true)
            && !empty($assignedAssignees)) {
            respond_success_with_background_task($responsePayload, static function () use ($assignedAssignees, $updatedRecord, $organizationCandidate): void {
                docs_send_task_assignment_notifications($assignedAssignees, $updatedRecord, $organizationCandidate);
            });
        }

        respond_success($responsePayload);
        break;

    case 'get_organization_template':
        if ($method !== 'GET') {
            respond_error('Некорректный метод запроса.', 405);
        }

        $requestedOrganization = docs_normalize_organization_candidate((string) ($_GET['organization'] ?? ''));
        $accessContext = docs_resolve_access_context($requestedOrganization);
        docs_require_admin_session($accessContext);

        $organization = $accessContext['active'];
        $folder = sanitize_folder_name($organization);
        $templateName = docs_get_organization_template_filename($folder);
        $templatePath = docs_get_organization_template_path($folder);
        $publicPath = '/' . build_public_path($folder, $templateName);
        $exists = is_file($templatePath);
        $templateMtime = $exists ? (int) (@filemtime($templatePath) ?: time()) : 0;
        $cacheStamp = $templateMtime > 0 ? (string) $templateMtime : (string) time();
        $versionedPublicPath = $exists
            ? $publicPath . (strpos($publicPath, '?') === false ? '?' : '&') . 'v=' . rawurlencode($cacheStamp)
            : '';
        $viewerUrl = $exists
            ? 'https://view.officeapps.live.com/op/view.aspx?src='
                . rawurlencode(docs_resolve_application_base_url() . $versionedPublicPath)
            : '';

        respond_success([
